window.JASTROW_CHUNKS[1]={"400":{"h":"אֲדִימָּא","r":"A00400","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(= h. <a href=\"#\" data-headword=\"אָדוֹם\">אָדוֹם</a>) <i>red, full of sap, fresh</i>. <span class=\"citation\">Bets. 24ᵇ</span>, Rashi; v. however, <a href=\"#\" data-headword=\"הֲדַם\">הֲדַם</a>.</div>","alt":[]},"401":{"h":"אֱדַיִן","r":"A00401","html":"<div class=\"sense\">(= h. <a href=\"#\" data-headword=\"אֲזִי\">אֲזַי</a>, <span dir=\"rtl\">אָז</span>; √<span dir=\"rtl\">ד־</span> = h. <span dir=\"rtl\">ז־</span>) <i>at that time, thereupon.</i> <span class=\"citation\">Dan. II, 15</span>; <span class=\"citation\">17</span>; <span class=\"citation\">19</span>.—בֵּאדַ׳ <i>at the same time, forthwith</i>. <span class=\"citation\">Ibid. 14</span>; <span class=\"citation\">35</span>.—מן א׳ <i>from that time.</i> <span class=\"citation\">Ezra V, 16</span>.</div>","alt":[]},"402":{"h":"אֲדִינַיָּא","r":"A00402","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוּדְנָא III\"><span dir=\"rtl\">אוּדְנָא</span> III</a></div>","alt":[]},"403":{"h":"אֲדִיצוּתָא","r":"A00403","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹדִיצוּתָא\">אוֹדִיצוּתָא</a></div>","alt":[]},"404":{"h":"אֲדִיק","r":"A00404","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דִּיק\">דִּיק</a></div>","alt":["אוֹדִיק"]},"405":{"h":"אַדִּיר","r":"A00405","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> ; <i>distinguished, glorious, mighty</i>.—Pl. <span dir=\"rtl\">אַדִּירִים</span>. <span class=\"citation\">Men. 53ᵃ</span></div>","alt":[]},"406":{"h":"אַדִּיר ²","r":"A00406","html":"<div class=\"sense\"><span class=\"citation\">Targ. O. Ex. XV, 6</span>; a. fr.</div>","alt":["אַדִּירָא"]},"407":{"h":"*אֲדֵירָא","r":"A00407","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"דִּירָא\">דֵּיר</a>, <i>rim, border</i>. <span class=\"citation\">Y. Sabb. III, 5ᵈ</span> bot. leaned a vessel <span dir=\"rtl\">לא׳ דתנורא</span> (Var. <span dir=\"rtl\">לאוירא</span>) against the rim of a heated store.</div>","alt":[]},"408":{"h":"אָדֵישׁ","r":"A00408","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּוּשׁ\">דּוּשׁ</a> ch.</div>","alt":[]},"409":{"h":"אד\"ך","r":"A00409","html":"<div class=\"sense\"><i>Adakh</i>, substitute of <a href=\"#\" data-headword=\"תְּקַל I\">תקל</a> (<span class=\"citation\">Dan. V, 25</span>) by permutation of letters called <span dir=\"rtl\">א&quot;תב&quot;ש</span> q. v. <span class=\"citation\">Snh. 22ᵃ</span>. <span class=\"citation\">Cant. R. to III, 4</span> <span dir=\"rtl\">אנם</span> (corr. acc.).</div>","alt":[]},"410":{"h":"אדכי","r":"A00410","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוּרְבָּא\">אוּרְבָּא</a></div>","alt":[]},"411":{"h":"אַדְכָּרָה","r":"A00411","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דְּכַר I\">דְּכַר</a>) </div><div class=\"sense\"><b>1)</b> <i>mention</i>, esp. <i>invocation of the Lord, Divine Name</i>. <span class=\"citation\">Y. Ber. IV, 8ᵃ</span> top <span dir=\"rtl\">לכל חדא וחדא מנהון אדכרה</span> for each benediction an invocation. <span class=\"citation\">R. Hash. 18ᵇ</span> <span dir=\"rtl\">בטילת אדכרתא</span> the use of the Divine Name in legal documents was abolished.</div><div class=\"sense\"><b>—2)</b>  (= b. h. <a href=\"#\" data-headword=\"אַזְכָּרָה\">אַזְכָּרָח</a>) <i>memorial offering</i>. <span class=\"citation\">Targ. O. Lev. II, 2</span>; a. e.</div>","alt":["אַדְכַּרְתָּא"]},"412":{"h":"אִדְכָּרוּ","r":"A00412","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אַדְכָּרָה\">foreg.</a>) <i>remembrance, mention</i>. <span class=\"citation\">Targ. Ps. XXX, 5</span> Ms. … <a href=\"#\" data-headword=\"רֵיו\">רוּ</a>; ed. <span dir=\"rtl\">רוּת …</span></div>","alt":["אִדְכָּרוּתָא"]},"413":{"h":"אַדְכַּרְתָּא","r":"A00413","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַדְכָּרָה\">אַדְכָּרָה</a></div>","alt":[]},"414":{"h":"אֲדָל","r":"A00414","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (√<span dir=\"rtl\">אד</span>, <a href=\"#\" data-headword=\"עד\">עד</a> dial. = <a href=\"#\" data-headword=\"חַד I\">חד</a>, <a href=\"#\" data-headword=\"גד\">גד</a>; cmp. <a href=\"#\" data-headword=\"גַּד I\"><span dir=\"rtl\">גַּד</span> I</a>, גִּידָּא II, <a href=\"#\" data-headword=\"חַרְדָּל\">חַרְדָּל</a>) <i>garden-cress, summer-savory</i>. <span class=\"citation\">Tosef. Shebi. V, 11</span> (ed. Zuck. <span dir=\"rtl\">אדיל</span>). <span class=\"citation\">Ukts. III, 4</span> <a href=\"#\" data-headword=\"ע׳\">ע׳</a>. <span class=\"citation\">Y. Shebi. VII, 37ᶜ</span> bot. <span dir=\"rtl\">ערל</span>; ib. 37ᵇ bot. <a href=\"#\" data-headword=\"עָרְלָה\">ערלה</a> (corr. acc.)</div>","alt":["אֲדִיל","עֲדָל"]},"415":{"h":"אַדְלָקָה","r":"A00415","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"הַדְלָקָה\">הַדְלָקָה</a>) <i>lighting.</i> Pl. <span dir=\"rtl\">אַדְלָקוֹת</span>. <span class=\"citation\">Y. Shebi. VII, beg. 37ᵇ</span> <span dir=\"rtl\">מיני א׳</span> sorts of plants used for lighting purposes.</div>","alt":[]},"416":{"h":"אֲדַם","r":"A00416","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֲדַם\">הֲדַם</a>. [v. Rabb. D. S. to <span class=\"citation\">Ab. Zar. 38ᵇ</span>, <span class=\"citation\">Bets. 24ᵇ</span>, note.]</div>","alt":[]},"417":{"h":"אָדַם","r":"A00417","html":"<div class=\"sense\"> , v. <a href=\"#\" data-headword=\"דָּמַם\">דמם</a>) [<i>to be viscous, thick, dark</i>] <i>to be red, grow red</i>.</div><div class=\"sense\"><b>Pi. אִדֵּם</b> <div class=\"sense\"><i>to redden, make red</i>. Y. Sabb. VII, 10ᶜ top <span dir=\"rtl\">המְאַדֵּם אודם</span> he who produces a red spot (congestion of blood, on a Sabbath).</div></div><div class=\"sense\"><b>Hif. הֶאֱדִים</b> <div class=\"sense\"><b>1)</b>  (b. h.) (b. h.) <i>to be, grow red</i>. <span class=\"citation\">Num. R. s. 9</span> (p. 231ᵇ ed. Amst.) <span dir=\"rtl\">מַאֲדֶמֶת</span> (<span dir=\"rtl\">היתה</span>) if she was red-faced. <span class=\"citation\">Ḥull. 53ᵇ</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to cause to blush, put to shame</i> (usu. <a href=\"#\" data-headword=\"לָבַן II\">הלבין</a>). <span class=\"citation\">Num. R. s. 4</span> (p. 218ᵈ ed. Amst.) (play on <span dir=\"rtl\">עובד אדום</span>).—<i>Part.</i> מַאֲדִים <i>the planet Mars</i>. <span class=\"citation\">Sabb. 156ᵃ</span>.—<i>Part. Hof</i>. <span dir=\"rtl\">מְאָדָּם</span>, <span dir=\"rtl\">מְאוּדָּם</span>. Y. Sabb. VII, 10ᶜ top <span dir=\"rtl\">מְאָדָּמִים</span> dyed red.</div></div>","alt":[]},"418":{"h":"אָדָם","r":"A00418","html":"<div class=\"sense\"> m. (b. h.) <i>man</i>, pr. n. m. <i>Adam</i>, frequ. <span dir=\"rtl\">א׳ הראשון</span> (abbr. <span dir=\"rtl\">אה&quot;ר</span>). <span class=\"citation\">Gen. R. s. 17</span>; a. fr.—<span dir=\"rtl\">ספרו של</span>, <span dir=\"rtl\">ספרא דאה&quot;ר אה&quot;ר</span> the (allegorical) book of Adam containing all generations and their leaders from beginning to resurrection, i.e. destinies of humanity. <span class=\"citation\">Ex. R. s. 40</span> beg. <span class=\"citation\">B. Mets. 85ᵇ</span> bot.</div>","alt":[]},"419":{"h":"אֲדָם","r":"A00419","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(= <a href=\"#\" data-headword=\"דָּם\">דָּם</a>, <a href=\"#\" data-headword=\"דְּמָא\">דְּמָא</a>) <i>blood</i>. <span class=\"citation\">Targ. I Chron. XXII, 7</span>; a. e.—<span class=\"citation\">Y. Maas. Sh. V, 56ᵈ</span> top <span dir=\"rtl\">מגבלא אַדְמֵיה</span> to mix its (the bird’s) blood. <span class=\"citation\">Git. 47ᵃ</span>; v. <a href=\"#\" data-headword=\"חוּל II\"><span dir=\"rtl\">חוּל</span> II</a>. Pl. <span dir=\"rtl\">אַדְמִין</span>. Targ. I Chr. l. c.; a. e.</div>","alt":["אַדְמָא","אִדְמָא"]},"420":{"h":"אֲדַמְדָּם","r":"A00420","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>reddish</i>. <span class=\"citation\">Y. Succ. III, 53ᵈ</span> <span dir=\"rtl\">איזהו א׳ שׁבאדומים</span> which of the red colors is called <i>adamdam?</i>—<span class=\"citation\">Shebu. 6ᵃ</span> <i>reddish leprosy</i> (<span class=\"citation\">Lev. XIII, 42</span>); a. e.</div>","alt":[]},"421":{"h":"אֲדַמְדְּמָנֵי","r":"A00421","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דָּמַם\">דמם</a>) <i>lumps of dripping grapes</i>. <span class=\"citation\">Gen. R. s. 34</span>, end <span dir=\"rtl\">אנא גבלין ליה א׳</span> we make for it a dough of &amp;c., v. <a href=\"#\" data-headword=\"דַּבְדְּבָנִיּוֹת\">דַבְדְּבָנִיֹּות</a>, <a href=\"#\" data-headword=\"דַּמְדְּמָנִיּוֹת\">דַּמְדְּמָנִיֹּות</a>.</div>","alt":[]},"422":{"h":"אֲדָמָה","r":"A00422","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> , cmp. <a href=\"#\" data-headword=\"אֲדַמְדְּמָנֵי\">foreg.</a>; <i>thick and moist</i>) [earth], <i>clay</i>. <span class=\"citation\">Gen. R. s. 14</span> the potter takes sand (<span dir=\"rtl\">עפר</span>) which is male (masc. gender) and clay (<a href=\"#\" data-headword=\"אֲדָמָה\">אדמה</a>) which is female (fem. gender).—<span class=\"citation\">Sabb. VIII, 5</span> <span dir=\"rtl\">א׳ כחותם וכ׳</span> as much clay as is required for a seal on bag-knots. [For the meaning of the phonetic equivalents of our w. in other Semit. tongues, v. Ges. H. Dict. s. v.]</div>","alt":[]},"423":{"h":"אַדְמוּמִית","r":"A00423","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">אדם</span>) <i>redness</i>. <span class=\"citation\">Ḥull. 87ᵇ</span>, a. e. <span dir=\"rtl\">מראה א׳</span> reddish color.</div>","alt":[]},"424":{"h":"אַדְמוֹן","r":"A00424","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Admon</i>, one of the justices of the peace in Jerusalem. <span class=\"citation\">Keth. XIII, 1</span>.—<span class=\"citation\">Ib. 105ᵃ</span> <span dir=\"rtl\">א׳ בן גדאי</span>.</div>","alt":[]},"425":{"h":"אַדְמוֹנִי","r":"A00425","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>ruddy, gold-colored</i>, esp. with refer. to hair. <span class=\"citation\">Y. Ned. I, 36ᵈ</span> bot.</div>","alt":[]},"426":{"h":"אֲדָמִי","r":"A00426","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Adami</i> (<span class=\"citation\">Josh. XIX, 33</span>). <span class=\"citation\">Y. Meg. I, 70ᵃ</span> bot. <span dir=\"rtl\">וא׳ דמין</span> <i>Adami</i> changes into <i>Damin</i></div>","alt":[]},"427":{"h":"אֲדַמְתָּא","r":"A00427","html":"<p class=\"morphology\">f.</p><div class=\"sense\">(= h. <a href=\"#\" data-headword=\"אֲדָמָה\">אֲדָמָה</a>) <i>earth</i>. <span class=\"citation\">Targ. O. Gen. II, 5</span>; a. fr.</div>","alt":["אַדְמְתָא"]},"428":{"h":"אֶדֶן","r":"A00428","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"אוּדְנָא III\"><span dir=\"rtl\">אוּדְנָא</span> III</a>; √<span dir=\"rtl\">דן</span>, <i>base, pedestal.</i> Pl. <span dir=\"rtl\">אֲדָנִים</span>. <span class=\"citation\">Y. Sabb. VII, 10ᵈ</span> top; Babl. ib. 98ᵇ. <span class=\"citation\">Y. Shek. I, 45ᵈ</span> bot.</div>","alt":[]},"429":{"h":"אֻדַן","r":"A00429","html":"<div class=\"sense\">, v. <span dir=\"rtl\">אוּ׳</span></div>","alt":["אֻדְנָא"]},"430":{"h":"אִדְנָא","r":"A00430","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אִכְרוּם\">אִי׳</a></div>","alt":[]},"431":{"h":"*אֲדַנְדְּקֵי","r":"A00431","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (a Babyl. corrupt. of ἐθνάρχοι, v. <span dir=\"rtl\">אדנקא</span> P. Sm. 40) <i>chiefs of tribes</i>. <span class=\"citation\">Ḥull. 60ᵇ</span> א׳ שלהן חמשה Ar. (ed. <a href=\"#\" data-headword=\"ארונקי\">ארונקי</a>, Mus. <a href=\"#\" data-headword=\"אדונקי\">אדונקי</a>) the six tribes had only five chiefs (v. <span class=\"citation\">Josh. XII, 3</span>). Ib. <span dir=\"rtl\">כתוב א׳ וכ׳</span> record the word <a href=\"#\" data-headword=\"א׳\">א׳</a> in thy lecture notes (as a foreign word) and explain it.</div>","alt":[]},"432":{"h":"אַדְנוּת","r":"A00432","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אָדוֹן\">אָדוֹן</a>) <i>lordship, authority</i>. <span class=\"citation\">Gen. R. s. 93</span>; a. e.</div>","alt":[]},"433":{"h":"אֲדֹנָי","r":"A00433","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> plur. excellentiæ) <i>the Lord, Adonai</i>. <span class=\"citation\">Gen. R. s. 17</span>; <span class=\"citation\">Koh. R. to VII, 23</span>.</div>","alt":[]},"434":{"h":"אַדְנֵי","r":"A00434","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"><i>name of a mythical animal, orangoutang</i>(?). <span class=\"citation\">Kil. VII, 5</span>, defined Y. ibid. 31ᶜ bot. <span dir=\"rtl\">בר נש דטור</span> <i>mountain-man</i>, brought forth by the mountain and drawing nourishment from the ground (cmp. <span class=\"citation\">Job V, 23</span>). <span class=\"citation\">Koh. R. to VI, 11</span>.</div>","alt":["(אַבְנֵי)","א׳ הַשָּׂדֶה"]},"435":{"h":"אדני","r":"A00435","html":"<div class=\"sense\"> <span class=\"citation\">Sabb. 35ᵇ</span>, v. <a href=\"#\" data-headword=\"*אֲרוֹנֵי\">אֲרוֹנֵי</a></div>","alt":["אדאני"]},"436":{"h":"אדני מריונים","r":"A00436","html":"<div class=\"sense\">, read <span dir=\"rtl\">אַרְכִי בִרְיוֹנִים</span>, v. <a href=\"#\" data-headword=\"בִּרְיוֹן\">בִּרְיוֹן</a> a. <a href=\"#\" data-headword=\"אַרְכִי I\"><a href=\"#\" data-headword=\"אַרְכִי I\">אַרְכִי</a>.</a></div>","alt":[]},"437":{"h":"אָדַק","r":"A00437","html":"<div class=\"sense\"> (√<span dir=\"rtl\">אד</span>, v. <span dir=\"rtl\">הדק</span>, <span dir=\"rtl\">חדק</span>)<i>to squeeze into, fasten</i>. Part. pass. <span dir=\"rtl\">אָדוּק</span>, pl. <span dir=\"rtl\">אֲדוּקִים</span>, <span dir=\"rtl\">אֲדוּקִין</span> </div><div class=\"sense\"><b>1)</b> <i>fastened to</i>. <span class=\"citation\">B. Bath. 77ᵇ</span> בשאדוקין בו Ms. M. (ed. <span dir=\"rtl\">באד׳</span>) when the mules are attached to the wagon; cmp. <span dir=\"rtl\">טכס</span> a. <span dir=\"rtl\">טקס</span></div><div class=\"sense\"><b>—2)</b>  (cmp. <span dir=\"rtl\">אָחוּז</span> s. v. <a href=\"#\" data-headword=\"אָחַז\">אחז</a>) <i>holding fast</i>. <span class=\"citation\">B. Mets. 7ᵃ</span>; <span class=\"citation\">7ᵇ</span> sq.</div>","alt":[]},"438":{"h":"אֲדַק","r":"A00438","html":"<div class=\"sense\">, (neut. v.) <i>to be fastened, stick to</i>. <span class=\"citation\">Targ. Lam. IV, 8</span>.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"אֲדִיק\">אָדִיק</a>, <i>attached, cleaving to</i>. <span class=\"citation\">Targ. Ps. XXII, 16</span> א׳ ל־ Ms. (ed. <a href=\"#\" data-headword=\"דְּבֵק\">אדביק</a>). <span class=\"citation\">Targ. Ex. XXVIII, 28</span>; a. e.</div><div class=\"sense\"><b>Pa. אַדֵּק</b> <div class=\"sense\"><b>1)</b> <i>to fasten to, to cause to take hold</i>. <span class=\"citation\">Targ. Y. Deut. XXVIII, 21</span>.</div><div class=\"sense\"><b>—2)</b> <i>to seize, take hold of</i>. Ibid. id5 <span dir=\"rtl\">ויאדקונכון</span> (ed. Vien. a. oth. <span dir=\"rtl\">ויערק׳</span> corr. <a href=\"#\" data-headword=\"ד\">ד</a> for <a href=\"#\" data-headword=\"ר\">ר</a>).</div></div><div class=\"sense\"><b>Ithpa. אִתְאַדֵּק</b> <div class=\"sense\"><i>to join, cling to</i>. <span class=\"citation\">Targ. Job. XLI, 9</span>; <span class=\"citation\">15</span> (Ms. <span dir=\"rtl\">מידבק</span>).</div></div>","alt":[]},"439":{"h":"אֲדָק","r":"A00439","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>clepsydra</i>, v. <a href=\"#\" data-headword=\"אֲרָק\">אֲרָק</a>.</div>","alt":[]},"440":{"h":"*אדקולאון","r":"A00440","html":"<div class=\"sense\"> <span class=\"citation\">Cant. R. to I, 11</span> <span dir=\"rtl\">לא׳ בן הדימה</span> (Var. <span dir=\"rtl\">לאר׳ כן</span>) a gloss inserted in the text, and which read <span dir=\"rtl\">לאו דוקא אלא כן הדימם</span> ‘not to be taken literally’ (that the Divine Word kissed every Israelite &amp;c.), ‘but he made them so imagine’.</div>","alt":["ארקולאון"]},"441":{"h":"אָדַר","r":"A00441","html":"<div class=\"sense\"><i>to cut off, surround, isolate;</i> whence </div><div class=\"sense\"><b>1)</b>  (b. h.) to <i>distinguish.</i>—Den. <a href=\"#\" data-headword=\"אַדִּיר\">אַדִּיר</a>. </div><div class=\"sense\"><b>2)</b>  (Assyr. v. <a href=\"#\" data-headword=\"אֲדָר\">אֲדָר</a>) <i>to darken</i>.</div><div class=\"sense\"><b>—3)</b>  *<i>to strip</i>. cmp. <a href=\"#\" data-headword=\"עֲדַר I\">עדר</a>.—<span class=\"citation\">B. Kam. 11ᵃ</span> (ref. to <a href=\"#\" data-headword=\"עד\">עד</a> <span class=\"citation\">Ex. XXII, 12</span>, v. <a href=\"#\" data-headword=\"עַד\">עַד</a> in H. Dict.) <span dir=\"rtl\">יביא אֲדוּרָה לב&quot;ד</span> Ar. (ed. <span dir=\"rtl\">עֲדוּדָה</span>, v. <a href=\"#\" data-headword=\"*עָדַד\">עדד</a>; Ms. <span dir=\"rtl\">ארורה</span>, corr. acc.) let him bring the stripped (the remnants of the torn animal, skin &amp;c.) before court for assessment of damages.</div>","alt":[]},"442":{"h":"אֲדַר","r":"A00442","html":"<div class=\"sense\">v. <a href=\"#\" data-headword=\"אִדַּר\">אִדְּרָא</a>, <a href=\"#\" data-headword=\"אֵדֶר I\">אִדְרָא</a>, <a href=\"#\" data-headword=\"אִידְּרוֹן\"><a href=\"#\" data-headword=\"אִידְּרוֹן\">אִדְּרוֹנָא</a>.</a></div><div class=\"sense\"><b>Pa. אַדַּר</b> <div class=\"sense\"><i>to distinguish</i>. <span class=\"citation\">Snh. 63ᵇ</span> (play on Adrammelekh <span class=\"citation\">II Kings XVI, 31</span>) <span dir=\"rtl\">דא׳ ליה וכ׳</span> (the mule) that gives distinction to its owner when travelling.</div></div>","alt":[]},"443":{"h":"אֲדָר","r":"A00443","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> Assyr. <i>the cloudy</i>; v. Fred. Delitzsch, The Hebr. Lang. p. 15) <i>Adar</i>, the twelfth month of the Jewish calendar, containing twenty nine days, and varying between the eleventh of February and the twenty eighth of March. In leap years: <span dir=\"rtl\">א׳ רִאשֹׁון</span> <i>First Adar</i>, of thirty days duration between the thirty first of January and the tenth of March; <span dir=\"rtl\">א׳ שֵׁנִי</span> <i>Second Adar</i>, of twenty nine days, between the second of March and the eighth of April. Targ. II Esth. IX, 29; a. fr.—<span class=\"citation\">Meg. I, 4</span>; a. fr.—Pl. <span dir=\"rtl\">אֲדָרִים</span>, <span dir=\"rtl\">אֲדָרִין</span>. <span class=\"citation\">R. Hash. 19ᵇ</span></div>","alt":["(אָדָר)"]},"444":{"h":"אִדַּר","r":"A00444","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אֵדֶר I\">אדר</a>, <a href=\"#\" data-headword=\"נְדַר I\">נדר</a> v. <a href=\"#\" data-headword=\"אָדַר\">אָדַר</a>) <i>a place cut off, circle</i> (cmp. <a href=\"#\" data-headword=\"זִירָה\">זִירָה</a>), whence <i>threshing place, barn;</i> also <i>the grain piled up in the barn for threshing;</i> cmp. <a href=\"#\" data-headword=\"גּוֹרֶן\">גּוֹרֶן</a>. <span class=\"citation\">Targ. Hos. II, 11</span> <span dir=\"rtl\">בעידן א׳</span> at the season of its being piled up; a. fr.—<span class=\"citation\">Gen. R. s. 63</span> the shovel <span dir=\"rtl\">דאפיך אי׳</span> which upturns the grain in the barn (= prayer averting evil decrees). <span class=\"citation\">Ib.</span> (play on <a href=\"#\" data-headword=\"אַדֶּרֶת\">אדרת</a> <span class=\"citation\">Gen. XXV, 25</span>) <span dir=\"rtl\">כקש מא׳</span> like chaff from the barn. <span class=\"citation\">Ruth R. to III, 3</span> <span dir=\"rtl\">להיכן אקימתא א׳</span> where didst thou put up the barn?—Pl. <span dir=\"rtl\">אִידְּרַיָּא</span>, <span dir=\"rtl\">אִדְּרֵי</span> &amp;c. <span class=\"citation\">Dan. II, 35</span>. <span class=\"citation\">Targ. I Sam. XXIII, 1</span>; a. e. <span class=\"citation\">Cant. R. to VII, 3</span> (homilet. rendition of <span dir=\"rtl\">הסהר אגן</span> Cant. l. c.) <span dir=\"rtl\">א׳ דאזהרה</span> a rounded place (cmp. <a href=\"#\" data-headword=\"גּוֹרֶן\">גורן</a>, <span dir=\"rtl\">זירה</span>) of enlightenment, i.e. hall of the Sanhedrin. [With <a href=\"#\" data-headword=\"א\">א</a> or <a href=\"#\" data-headword=\"נ\">נ</a> rejected: <span dir=\"rtl\">בי דרי</span>. <span class=\"citation\">Taan. 3ᵇ</span>. <span class=\"citation\">B. Mets. 73ᵃ</span>.]</div>","alt":["אִידַּר","אִדְּרָא","אִידְּרָא"]},"445":{"h":"אֵדֶר I","r":"A00445","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אָדַר\">אָדַר</a> 3) <i>skin, hide, leather-bag</i>. <span class=\"citation\">Y. Maas. Sh. IV, 55ᶜ</span> <span dir=\"rtl\">אדר תורתא</span> hide of a cow. <span class=\"citation\">Ib.</span> <span dir=\"rtl\"><span dir=\"rtl\">אדרא</span> (<a href=\"#\" data-headword=\"בָּרָא I\">ברא</a>) <span dir=\"rtl\">דתבנא</span></span>; <span class=\"citation\">Lam. R. to I, 1</span> (חד כותאי 2) <span dir=\"rtl\">אדר דתבן</span> Ar. (ed. <a href=\"#\" data-headword=\"דּוּר I\">דור</a>) a hide stuffed with straw. <span class=\"citation\">Y. Shebi. V, 36ᵃ</span> top <span dir=\"rtl\">א׳ דאילין חכימא וכ׳</span> the leather of these bottles is distinguishable from the leather of those.—Pl. <span dir=\"rtl\">אוּדְרְיָיתָא</span>. <span class=\"citation\">Shebu. 29ᵇ</span> תליסר א׳ דתבנא Ar. (ed. <a href=\"#\" data-headword=\"אוּרְוָותָא\">אורוותא</a>; Ms. F. <span dir=\"rtl\">אדידתא</span>, v. Rashi a. l.) thirteen bagfuls of straw; <span class=\"citation\">Ned. 25ᵃ</span></div>","alt":["אֲדַר","אִדְרָא I","אוּדְרָא"]},"446":{"h":"אֵדֶר II","r":"A00446","html":"<div class=\"sense\"> ch. m. (v. <a href=\"#\" data-headword=\"אָדַר\">אָדַר</a>) [<i>thick-leaved, dark</i>] </div><div class=\"sense\"><b>1)</b> <i>a cedar species</i>, prob. <i>Spanish Juniper</i>. <span class=\"citation\">R. Hash. 23ᵃ</span> <span dir=\"rtl\">מאי קדרוס</span> (<span dir=\"rtl\">ם</span>) <span dir=\"rtl\">אדרא</span> Ms. M. (ed. <a href=\"#\" data-headword=\"קַתְרוֹס I\">קתרוס</a>) what is <i>kedros</i> (κέδρος)? <i>Adara</i>. <span class=\"citation\">Snh. 108ᵇ</span> what is <i>gofer?</i> רב אמר אדרא דבי ר׳ שילא אמר וכ׳ Ar. a Ms. Fl. (v. Rabb. D. S. a. l.); cmp. <span class=\"citation\">Gen. R. s. 31</span>; <span class=\"citation\">Yalk. Gen. 51</span>.—<span class=\"citation\">Bets. 15ᵇ</span> <span dir=\"rtl\">יטע אדר וכ׳</span> let him plant an <i>edar</i> (allud. to <i>addir</i> &amp;c., <span class=\"citation\">Ps. XCIII, 4</span>); <span dir=\"rtl\">א&quot;נ אדרא וכ׳</span> or <i>adara</i> as its (popular or Chald.) name is; as people say, it is called <i>adara</i> because it lasts for generations <span dir=\"rtl\">(א־דרא</span>). <span class=\"citation\">Git. 69ᵇ</span> <span dir=\"rtl\">אטרף א׳</span> leaves of ad. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מיא דא׳</span> decoct thereof.</div><div class=\"sense\"><b>—2)</b>  אִדְרָא <i>fig-tree</i>. Targ. II, <span class=\"citation\">Esth. VII, 9</span> (to which perhaps belongs. Git. l. c.).</div>","alt":["אִדְרָא II","אֲדָרָא I"]},"447":{"h":"אֲדָרָא II","r":"A00447","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אָדַר\">אָדַר</a>, cmp. Ges. H. Dict. s. v.) <i>flag</i> of a ship. <span class=\"citation\">B. Bath. 73ᵃ</span> (for b. h. <a href=\"#\" data-headword=\"נֵס\">נֵס</a>); Ms. M. <span dir=\"rtl\">אֲדָארָא</span> (v. Rabb. D. S. a. l.).</div>","alt":[]},"448":{"h":"אַדְרָא","r":"A00448","html":"<div class=\"sense\"> <span class=\"citation\">Sabb. 67ᵃ</span>, v. <a href=\"#\" data-headword=\"אַדְדָא\">אַדְדָא</a>.—אדרא <span class=\"citation\">B. Mets. 26ᵃ</span>, read with Rashi <a href=\"#\" data-headword=\"אוּדְרָא\">אוּדְרָא</a> v. <a href=\"#\" data-headword=\"אוּדְרָא\">אוּדְרָא</a>.</div>","alt":[]},"449":{"h":"אַדְּרַבָּא","r":"A00449","html":"<div class=\"sense\"> (contr. of <span dir=\"rtl\">על דרבה</span>, v. <a href=\"#\" data-headword=\"אַדְּ־\">אַדְּ־</a>) <i>turn to the stronger side</i>, whence as a dialectic term, <i>on the contrary</i>. <span class=\"citation\">Pes. 28ᵃ</span>, a. fr. <span dir=\"rtl\">א׳ איפכא מסתברא</span> on the contrary, the reverse stands to reason. <span class=\"citation\">Ib. 77ᵃ</span> הוה אמינא א׳ I might have said, ‘On the contrary’ &amp;c.; a. fr. [Not to be confounded with <a href=\"#\" data-headword=\"אַדְּרַבָּא\">אַדְּרָבָא</a>, <a href=\"#\" data-headword=\"אַדְּרַבָּא\">אַדְּרַבָּה</a>, v. <a href=\"#\" data-headword=\"אַדְּ־\">אַדְּ־</a>.]</div>","alt":["אַדְּרַבָּה"]},"450":{"h":"אִדְרַבְלָא","r":"A00450","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ὑδραύλης, hydraula) <i>player on the hydraulis, organist</i>.—Pl. <a href=\"#\" data-headword=\"אִדְרַבְלִיס\">אִדְרַבְלִין</a>. <span class=\"citation\">Gen. R. s. 50</span> <span dir=\"rtl\">א׳ וכרבלין וכ׳</span> there are organists and flute players in the land (or organs and cymbals, v. <a href=\"#\" data-headword=\"אִדְרַבְלִיס\">next w.</a>), and such a land should be destroyed? [Comment.—Perh. to be read <span dir=\"rtl\">אַרְדִּיכְלִין</span>.] <span class=\"citation\">Gen. R. s. 23</span> <span dir=\"rtl\">ארדיכולין וכ׳</span> (<span dir=\"rtl\">ארדיב׳</span>, corr. acc.).</div>","alt":[]},"451":{"h":"אִדְרַבְלִיס","r":"A00451","html":"<div class=\"sense\"> (trnsp.) m. (ὕδραυλις) <i>water-organ</i>. <span class=\"citation\">Y. Succ. V, 55ᶜ</span> bot. <span dir=\"rtl\">עוגב זה ארד׳</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">לא היה א׳ וכ׳</span> there was no organ used in (the) Jerusalem (Temple) because it interferes with the sweetness (melody of the song).—Pl. <a href=\"#\" data-headword=\"אִדְרַבְלִיס\">אִדְרַבְלִין</a>; v. <a href=\"#\" data-headword=\"אִדְרַבְלָא\">foreg.</a> Cmp. <a href=\"#\" data-headword=\"הִרְדַּוְלִיס\">הרדוליס</a>.</div>","alt":["אִרְדַּבְלִיס"]},"452":{"h":"אֲדַרְגָּזְרַיָּא","r":"A00452","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (v. Schr. K. A. T. p. 617 sq.; cmp. <a href=\"#\" data-headword=\"אֵדֶר I\">אדר</a> a. <span dir=\"rtl\">גזר</span>) <i>title of high officers.</i> <span class=\"citation\">Dan. III, 3</span>. <span class=\"citation\">Cant. R. to VII, 9</span> א׳ איפרכיא <i>adarg</i>. means <i>governors</i></div>","alt":[]},"453":{"h":"אַדְרוֹמָא","r":"A00453","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"> gent. <i>Adroma</i> (Southern) for b. h. <a href=\"#\" data-headword=\"תֵּימָא\">תֵּימָא</a>. <span class=\"citation\">Targ. I Chr. I, 30</span>.</div>","alt":[]},"454":{"h":"אֶדְרוֹעָא","r":"A00454","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"דְּרַע III\">דְּרָעָא</a>. <span class=\"citation\">Targ. Y. Num. VI, 19</span>.</div>","alt":[]},"455":{"h":"אִדְרוֹפִּיקוֹס","r":"A00455","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ὑδρωπικός) <i>suffering from dropsy</i>. <span class=\"citation\">Lev. R. s. 15</span> (var. corrup.); <span class=\"citation\">Yalk. Lev. 554</span>. Ib. Job. 916 <span dir=\"rtl\">אִנְדְּר׳</span> (cmp. <a href=\"#\" data-headword=\"אַדְרְיָינוֹס\">אדריינוס</a> a. <span dir=\"rtl\">אנד׳</span>).</div>","alt":[]},"456":{"h":"*אִדְרוּתָא","r":"A00456","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אֵדֶר I\">אדר</a>) <i>glory, distinction</i>. <span class=\"citation\">Ber. 56ᵇ</span> top (oneirocritical play on <i>Adar</i>) <span dir=\"rtl\">בא׳ מיתת</span> thou shalt die in glory. [Cmp. Y. Maas Sh. IV, end, 55ᶜ; <span class=\"citation\">Lam. R. to I, 1</span> <span dir=\"rtl\">(חד מתלמ׳</span>).]</div>","alt":[]},"457":{"h":"*אַדְרַזְדָּא","r":"A00457","html":"<div class=\"sense\"> (= <span dir=\"rtl\">אזדרזדא</span>; <a href=\"#\" data-headword=\"זְרַז I\">זרז</a>) <i>diligently, quickly.</i> <span class=\"citation\">Ezra VII, 23</span>.</div>","alt":[]},"458":{"h":"אַדְרִיאָנוֹס","r":"A00458","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"אַדְרְיָינוֹס\">אַדְרְיָינוֹס</a>. Tanḥ. <span class=\"citation\">B’resh. 7</span>; a. fr.</div>","alt":[]},"459":{"h":"אדריאנטין","r":"A00459","html":"<div class=\"sense\"> <span class=\"citation\">Deut. R. s. 1</span>, interpret. <span dir=\"rtl\">נציבים</span> (<span class=\"citation\">II Sam. VIII, 14</span>) read <span dir=\"rtl\">אִסְטַרְטִיגִין</span>, as Targ. a. l.</div>","alt":[]},"460":{"h":"אַדְרִיאַס","r":"A00460","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Ἀδρίας) <i>Adriatic Sea</i>. Tanḥ. <span class=\"citation\">B’resh. 7</span> <span dir=\"rtl\">בין א׳ לאוקיינוס</span> between the Adriatic Sea and the Mediterranean.</div>","alt":[]},"461":{"h":"אַדְרִיב","r":"A00461","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְדַּב\">אַרְדַּב</a></div>","alt":["אַדְרִיבָא"]},"462":{"h":"אדריבולין","r":"A00462","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִדְרַבְלָא\">אִדְרַבְלָא</a></div>","alt":[]},"463":{"h":"אדריונטוס","r":"A00463","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אַנְדְּרוֹנִיטִין\">אַנְדְּרוֹנִיטִיס</a> a. <a href=\"#\" data-headword=\"אַדְרִיאָנוֹס\"><a href=\"#\" data-headword=\"אַדְרִיאָנוֹס\">אַדְרִיאַנְטוֹס</a>.</a></div>","alt":[]},"464":{"h":"אַדְרְיָינוֹס","r":"A00464","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Hadrian</i>, the Roman emperor (117 to 138) under whom the insurrection of Bar Kokhba occurred; freq. mentioned with the imprecation <span dir=\"rtl\">שחיק עצמות</span>. <span class=\"citation\">Deut. R. s. 3</span>; a. fr. V. <a href=\"#\" data-headword=\"אַדְרִיאָנוֹס\">אַדְרִיאָנוֹס</a>.</div>","alt":["אַנְדַּרְיָנוֹס"]},"465":{"h":"אדריינטיס","r":"A00465","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אַנְדְּרוֹנִיטִין\">אַנְדְּרוֹנִיטִיס</a> a. <a href=\"#\" data-headword=\"אַנְדְּרִיאַנְטוֹס\"><a href=\"#\" data-headword=\"אַנְדְּרִיאַנְטוֹס\">אַנְדְרִיאַנְטוֹס</a>.</a></div>","alt":[]},"466":{"h":"אַדְרְיָינִי","r":"A00466","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>Hadrianic</i>, </div><div class=\"sense\"><b>1)</b>  of the town <i>Adria</i> or <i>Hadria</i> in Venetia. <span class=\"citation\">Ab. Zar. II, 3</span> <span dir=\"rtl\">חרס ה׳</span> (Y. Mish. a. Ib. <a href=\"#\" data-headword=\"א׳\">א׳</a>) earthen ware of Adria (forbidden for use on account of some unknown connection with idolatry, perh. suspected to have been used as wine vessels before they were offered for sale; v. infra).</div><div class=\"sense\"><b>—2)</b> <i>referring to Hadrian, Hadrianic</i>. Ib. 32ᵃ explain. <span dir=\"rtl\">חרס הד׳</span> ‘earthen vessels soaked with wine, and distributed in pieces, by order of Hadrian, among the soldiers to be diluted with water for drinking’.</div><div class=\"sense\"><b>—3)</b>  (genit. of Hadrianus) <i>Hadrian</i>’s (followers). <span class=\"citation\">Lam. R. to I, 17</span>, v. <span dir=\"rtl\">אספסיינוס</span>.</div>","alt":["הַדְרְיָינִי"]},"467":{"h":"אדריכולין","r":"A00467","html":"<div class=\"sense\"> <span class=\"citation\">Gen. R. s. 23</span>, v. <a href=\"#\" data-headword=\"אִדְרַבְלָא\">אִדְרַבְלָא</a></div>","alt":[]},"468":{"h":"אַדְרִיכוּתָא","r":"A00468","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">דרך</span>) <i>treading, stamping</i> the threshing floor. <span class=\"citation\">Targ. Jer. LI, 33</span>.</div>","alt":[]},"469":{"h":"אַדְרִיכָל","r":"A00469","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְדִּיכָל\">אַרְדִיכָל</a></div>","alt":[]},"470":{"h":"אדרינטוס","r":"A00470","html":"<div class=\"sense\"> <span class=\"citation\">Gen. R. s. 8</span> Ar, ed. <a href=\"#\" data-headword=\"אינדרטין\">אינדרטין</a>, v. <a href=\"#\" data-headword=\"*אַנְדְּרוֹנִיטִין\">אַנְדְּרוֹנִיטִיס</a></div>","alt":[]},"471":{"h":"אֲדַרְכֹּון","r":"A00471","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דַּרְכּוֹן\">דַּרְכֹּון</a></div>","alt":[]},"472":{"h":"אֲדַרְכִּיאָן","r":"A00472","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲדַרְכָּן\">אֲדַרְכָּן</a></div>","alt":[]},"473":{"h":"אֲדַרְכָּל","r":"A00473","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְדִּיכָל\">אַרְדִּיכָל</a></div>","alt":[]},"474":{"h":"אֲדַרְכָּן","r":"A00474","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (prob. corrupt. of <a href=\"#\" data-headword=\"אַרְטְבַן\">אַרְטְבַן</a> q. v.) <i>Adarkhan</i>, a Parthian ruler. <span class=\"citation\">Ab. Zar. 10ᵇ</span> (Ms. <span dir=\"rtl\">כין</span>; oth. vers. <span dir=\"rtl\">אדרבך</span>, v. Rabb. D. S. a. l.).—<span class=\"citation\">Esth. R. to I, 3</span> <span dir=\"rtl\">אדרכיאן</span>.</div>","alt":["אֲדַרְכִּיאָן"]},"475":{"h":"אַדְרַכְתָּא","r":"A00475","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (דְּרַךְ Af.) <i>tracing;</i> (law) </div><div class=\"sense\"><b>1)</b> <i>legal permission to a creditor to trace the debtor’s property for the purpose of having it seized, assessed, offered for public sale, and eventually delivered to him</i>. [Order of documents, acc. to <span class=\"citation\">B. Bath. 169ᵃ</span>, vers. of Maim. a. others: 1) <a href=\"#\" data-headword=\"אַדְרַכְתָּא\">אדרכתא</a>; </div><div class=\"sense\"><b>2)</b>  <a href=\"#\" data-headword=\"טִירְפָּא\">טירפא</a> the right of seizure of the debtor’s property sold after the date of the loan (mortgage); </div><div class=\"sense\"><b>3)</b>  <a href=\"#\" data-headword=\"שׁוּמָא\">שומא</a> record of the assessed value for which the creditor took possession;—acc. to vers. in ed. a. Mss. 1) <a href=\"#\" data-headword=\"טִירְפָּא\">טירפא</a> right of seizure &amp;c.; 2) <a href=\"#\" data-headword=\"א׳\">א׳</a> authorization to seize the traced property, defining position &amp;c.; 3) <a href=\"#\" data-headword=\"שׁוּמָא\">שומא</a>.] <span class=\"citation\">B. Bath. 169ᵃ</span>. <span class=\"citation\">B. Kam. 112ᵇ</span>. <span class=\"citation\">B. Mets. 16ᵇ</span>. <span class=\"citation\">Ib. 35ᵇ</span>. <span class=\"citation\">Keth. 104ᵇ. 2</span>) <i>private authorization to collect or take possession of one’s debtordeposit; assignment, transfer</i>. <span class=\"citation\">B. Kam. 70ᵃ</span> Ms. M., At. (ed. <span dir=\"rtl\">אור׳</span>); <span class=\"citation\">Shebu. 33ᵇ</span> (ed. <span dir=\"rtl\">אור׳</span>, v. Rabb. D. S. a. l.); <span class=\"citation\">Bekh. 49ᵃ</span></div>","alt":[]},"476":{"h":"אַדְרַמֶּלֶךְ","r":"A00476","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (<span class=\"citation\">II Kings XVII, 31</span>) <i>Adrammelekh</i>, name of an idol. <span class=\"citation\">Snh. 63ᵇ</span> א׳ וכ׳ Adr. a. Anammelekh signify mule and horse; v. <a href=\"#\" data-headword=\"אֲדַר\">אֲדַר</a>.</div>","alt":[]},"477":{"h":"אֶדְרַע","r":"A00477","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (= h. <span dir=\"rtl\">אֶזְרוֹעַ</span>, v. <a href=\"#\" data-headword=\"זְרוֹעַ\">זְרוֹעַ</a>) <i>arm</i>. <span class=\"citation\">Targ. Jer. XXXII, 21</span>; a. fr.—Y. Ber. I, 4ᶜ top <span dir=\"rtl\">דאֶדְרְעֵיה</span> the Tefillin of his arm. <span class=\"citation\">Koh. R. to XI, 2</span>.—Pl. <span dir=\"rtl\">אֶדְרָעָתָא</span>. <span class=\"citation\">Targ. Job XXII, 9</span>.—<span dir=\"rtl\">אֶדְרָעִין</span>. <span class=\"citation\">Gen. R. s. 65</span>.—V. <a href=\"#\" data-headword=\"דְּרַע III\"><span dir=\"rtl\">דְּרַע</span> III</a>.</div>","alt":["אֶדְרְעָא"]},"478":{"h":"אֶדְרְעָיָיא","r":"A00478","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>of Edreï</i>, a town in Naftali (<span class=\"citation\">Josh. XIX, 37</span>), another in Menasseh (Bashan, <span class=\"citation\">Num. XXI, 33</span>; a. e.).—<span class=\"citation\">Y. Ber. V, 9ᵇ</span> top; a. e.</div>","alt":[]},"479":{"h":"אַדֶּרֶת","r":"A00479","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>cloak, cover</i>. <span class=\"citation\">Gen. R. s. 63</span> (ref. to <span class=\"citation\">Gen. XXV, 25</span>) <span dir=\"rtl\">כולו ראוי לא׳</span> every one (of the Roman people) fit for the purple cloak (may become an emperor).</div><div class=\"sense\"><b>—2)</b>  (homiletically, as if <a href=\"#\" data-headword=\"אַדֶּרֶת\">אִדֶּרֶת</a> = ch. <a href=\"#\" data-headword=\"אִדַּר\">אִדְּרָא</a>, <a href=\"#\" data-headword=\"אִדַּר\">אִדַּר</a>) <i>the threshing floor, the store of grains</i>. Ib. <span dir=\"rtl\">כולו מפוזר ומפורד כא׳</span> entirely destined to be scattered (winnowed) like the grains, <span dir=\"rtl\">לזרותו וכ׳</span> [<span dir=\"rtl\">שעתיד</span>] for the Lord will scatter him (Edom-Rome) like chaff &amp;c. (ref. to <span class=\"citation\">Dan. II, 35</span>).</div>","alt":[]},"480":{"h":"אָדֵשׁ","r":"A00480","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּוּשׁ\">דּוּשׁ</a> ch.</div>","alt":[]},"481":{"h":"אָהַב","r":"A00481","html":"<div class=\"sense\"><i>to love</i>. <span class=\"citation\">Y. Ab. Zar. II beg. 40ᶜ</span> <span dir=\"rtl\">אוֹהֲבָהּ</span> her lover; a. fr. <span dir=\"rtl\">אוהב את הבריות</span> <i>philanthropist.</i> <span class=\"citation\">Aboth I, 12</span>; a. fr.—Part. pass. <span dir=\"rtl\">אָהוּב</span>, f. <span dir=\"rtl\">אֲהוּבָה</span>. <span class=\"citation\">Yeb. 23ᵃ</span> <span dir=\"rtl\">א׳ בנשואיה</span> beloved (worth loving) for her well chosen marriage. [Y. Ab. Zar. l. c. <span dir=\"rtl\">איהבתו</span> read <span dir=\"rtl\">אוֹהַבְתֹּו</span>.]</div><div class=\"sense\"><b>Nif. נֶאֱהַב</b> <div class=\"sense\">, <i>Hithpa</i>. <span dir=\"rtl\">הִתְאָהֵב</span> <i>to be beloved, popular</i>. <span class=\"citation\">Lev. R. s. 32</span>, beg., these blows (of persecution) had the effect <span dir=\"rtl\">להֵאָהֵב וכ׳</span> to make me beloved of my Father in heaven. <span class=\"citation\">Yoma 86ᵃ</span> <span dir=\"rtl\">שיהא ש&quot;ש מִתְאָהֵב וכ׳</span> that the Divine Name may be beloved through thee (that thy doings may favorably reflect on thy religion).—</div></div><div class=\"sense\"><b>Pi. אִהֵב</b> </div><div class=\"sense\"><b>Hif. הֶאֱהִיב</b> <div class=\"sense\"><i>to make beloved, popular</i>. Tan. d’be El. I, 28 <span dir=\"rtl\">תהא מְאָהֵב ש&quot;ש וכ׳</span> make the Divine Name &amp;c. (v. supra).—<i>Part. Pu</i>. <span dir=\"rtl\">מְאוּהָב</span> <i>popular</i>. <span class=\"citation\">Yalk. Deut. 837</span>.—<span class=\"citation\">Cant. R. to I, 1</span> <span dir=\"rtl\"><span dir=\"rtl\">להַאֲהִיבָן</span> (<span dir=\"rtl\">לאָהֲבָן</span>) <span dir=\"rtl\">לקרבן וכ׳</span></span> to make them beloved (of God), draw them nigh (to God) &amp;c. <span class=\"citation\">Ib. to V, 1</span>.—<span class=\"citation\">Yalk. Cant. 981</span> <span dir=\"rtl\">הֶאֱהַבְנוּ לך עלמות הרבה</span> we have made many maiden beloved of thee (converted them).</div></div>","alt":[]},"482":{"h":"אַהֲבָא","r":"A00482","html":"<div class=\"sense\">, const. <span dir=\"rtl\">אַהֲבַת</span> ch. = next. w. <span class=\"citation\">Targ. Cant. VIII, 6</span>.</div>","alt":[]},"483":{"h":"אַהֲבָה I","r":"A00483","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>love, friendship</i>. <span dir=\"rtl\">א׳ שהיא תלויה בדבר</span> love dependent on something extraneous, i.e. sensual, selfish love. <span class=\"citation\">Aboth V, 16</span>.—<span dir=\"rtl\">עשה מא׳</span> (or <a href=\"#\" data-headword=\"עֲבַד I\">עבד</a>) to do good (serve the Lord) from pure motives of love. <span class=\"citation\">Sot. 31ᵃ</span>; <span class=\"citation\">Snh. 61ᵇ</span>; a. fr.—</div>","alt":[]},"484":{"h":"אַהֲבָה II","r":"A00484","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"אַחֲוָוא\">אַחֲוָוא</a> in Y.) pr. n. m. <i>Ahăbah, Aḥava</i>, son of Zera, and father of R. Adda. <span class=\"citation\">R. Hash. 29ᵃ</span>. <span class=\"citation\">Ab. Zar. 30ᵃ</span>; a. fr. Y. Yeb. VIII, 9ᵇᶜ</div>","alt":[]},"485":{"h":"אהדורי","r":"A00485","html":"<div class=\"sense\"> <span class=\"citation\">Y. Ber. II, 4ᵇ</span>, v. <a href=\"#\" data-headword=\"אֲדוּרֵי\">אֲדוּרֵי</a></div>","alt":[]},"486":{"h":"אהו","r":"A00486","html":"<div class=\"sense\"> Y. Ab. Zar. V, 45ᵃ, read <a href=\"#\" data-headword=\"אֲהָן\">אֲהָן</a>.</div>","alt":[]},"487":{"h":"אהוליות","r":"A00487","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אָהֳלִית\">אָהֳלִית</a></div>","alt":[]},"488":{"h":"אהולין","r":"A00488","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֹהֶל\">אֹהֶל</a></div>","alt":[]},"489":{"h":"אהון","r":"A00489","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲהָן\">אֲהָן</a></div>","alt":[]},"490":{"h":"אֲהוּרְיָיר","r":"A00490","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (horrearius, ὁρριάριος; v. Sm. Ant. s. v. Horreum) <i>store-keeper, steward</i>. [Comment.: fr. <span dir=\"rtl\">אֻרְוָוה</span>, v. <a href=\"#\" data-headword=\"אוּרְיָא\">אוּרְיָא</a>, <i>equerry</i>.] <span class=\"citation\">Meg. 12ᵇ</span> <span dir=\"rtl\">בר אהוריירֵיה דאבא</span> thou, son of my father’s steward. <span class=\"citation\">B. Mets. 85ᵃ</span> (Ms. M. <span dir=\"rtl\">אהוריריה</span>); <span class=\"citation\">Sabb. 113ᵇ</span> <span dir=\"rtl\">אהוריריה</span> (v. Rabb. D. S. a. l. note 4) <span dir=\"rtl\">א׳ דרבי</span> Rabbi’s house steward (manager).</div>","alt":["אֲהוּרְיָירָא"]},"491":{"h":"אֲהוּרְמִין","r":"A00491","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Pers. Angra-Mainyus) <i>Ahriman</i>, the evil principle in the Zendavesta (Parsism); opp. <a href=\"#\" data-headword=\"הוֹרְמִיז\">הורמיז</a> Ormuzd. <span class=\"citation\">Snh. 39ᵃ</span> מפלגך לעילאי דהורמיז מפלגך לתתאי דאה׳ Ar. (ed. a. Mss. incorr., v. Rabb. D. S. a. l.; Tosef. a. l. Better vers. Ms. F. <span dir=\"rtl\">מפלגן</span> <i>our</i> half) thy upper half belongs to Ormuzd, thy lower half to Ahriman. Ib. <span dir=\"rtl\">א&quot;כ היכי שביק אהורמין להורמיז למעבר מיא בארעא</span> (ed. corr. acc.) if this be so, why does Ahriman allow Ormuzd to let the water pass (through the former’s dominion) to the ground?</div>","alt":[]},"492":{"h":"אהיי","r":"A00492","html":"<div class=\"sense\"> Y. Shek. V, 48ᵈ, read <a href=\"#\" data-headword=\"הַיי\">הַיי</a>.</div>","alt":[]},"493":{"h":"*אָהִיל","r":"A00493","html":"<div class=\"sense\"> m (<a href=\"#\" data-headword=\"אָהַל\">אָהַל</a>) <i>staying under the same roof</i> with an unclean object. <span class=\"citation\">Naz. VII, 2</span> (<span class=\"citation\">49ᵇ</span>) <span dir=\"rtl\">על אֲהִילָן</span> Talm. ed. (Mish. <span dir=\"rtl\">אָהֳלָן</span>, v. <a href=\"#\" data-headword=\"אֹהֶל\">אֹהֶל</a>) upon staying with them under &amp;c. Ib. 53ᵃ <span dir=\"rtl\">אֲהִילוֹ</span>. [<span class=\"citation\">Sabb. 90ᵃ</span> Ms. M., v. <a href=\"#\" data-headword=\"אֳהָל\">אֲהָל</a>.].—Pl. f. <span dir=\"rtl\">אֲהִילוֹת</span> the laws concerning <i>ahil</i>, whence <i>Ahiloth</i> (also <a href=\"#\" data-headword=\"אָהֳלוֹת\">אָהֳלוֹת</a>), name of a treatise of the Mishnah (of Seder Tahăroth). Y. M. Kat. II, end, 81ᵇ there are things in the Order of Moëd <span dir=\"rtl\">קשיין מן א׳ וכ׳</span> more difficult than Ahiloth &amp;c.—<span class=\"citation\">Ḥag. 14ᵃ</span>, a. fr. <span dir=\"rtl\">אהל׳</span>. <span class=\"citation\">B. Mets. 86ᵃ</span> <span dir=\"rtl\">אהי׳</span>.</div>","alt":[]},"494":{"h":"אָהֵיל","r":"A00494","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֳהָל\">אֳהָל</a></div>","alt":[]},"495":{"h":"אֲהִילָא","r":"A00495","html":"<div class=\"sense\"><i>tent;</i> v. <a href=\"#\" data-headword=\"אָהֳלָא\">אָהֳלָא</a>.</div>","alt":[]},"496":{"h":"אֲהִילַאי","r":"A00496","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Ahilai</i>. <span class=\"citation\">Pes. 30ᵃ</span></div>","alt":[]},"497":{"h":"אֲהִילָה","r":"A00497","html":"<div class=\"sense\"> f., pl. <span dir=\"rtl\">אֲהִילוֹת</span>, v. <a href=\"#\" data-headword=\"*אָהִיל\">אָהִיל</a></div>","alt":[]},"498":{"h":"אֲהִינָא","r":"A00498","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>Ahina</i>, <i>a species of late and inferior dates</i> (cmp. <a href=\"#\" data-headword=\"אַחְוָנַיָּיא\">אַחְיָנַיָּא</a>). <span class=\"citation\">Ḥull. 46ᵇ</span> lungs apparently so peeled as to resemble <span dir=\"rtl\">א׳ סומקא</span> a red Ah. <span class=\"citation\">B. Mets. 113ᵇ</span> <span dir=\"rtl\">א׳ מרירא</span> a bitter Ah.—Pl. <span dir=\"rtl\">אֲהִינֵי</span>. <span class=\"citation\">Tosef. Shebi. VII, 14</span>; <span class=\"citation\">Pes. 53ᵃ</span> (m.!). <span class=\"citation\">Y. B. Kam. VI, 5ᵇ</span> bot. <span dir=\"rtl\">כבשא דא׳</span> a preserve of A. <span class=\"citation\">Y. B. Bath. V, end, 15ᵇ</span> <span dir=\"rtl\">כבשה דאהינו</span> (corr. acc.), v. <span class=\"citation\">Ab. Zar. 38ᵇ</span> <span dir=\"rtl\">א׳ שליקי</span>.</div>","alt":[]},"499":{"h":"אהינו","r":"A00499","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲהִינָא\">foreg.</a></div>","alt":[]},"500":{"h":"אָהַל","r":"A00500","html":"<div class=\"sense\"> (b. h.), <i>Pi</i>. <span dir=\"rtl\">אִיהֵל</span> (deriv. of <a href=\"#\" data-headword=\"אֹהֶל\">אֹהֶל</a>) <i>to spread tent-like, to cover, shade, bend over</i> &amp;c., usu. with refer. to levitical uncleanness arising from being under the same shelter with, or forming a shelter over, a corpse &amp;c. Meïlah 17ᵃ <span dir=\"rtl\">אי׳ על מקצתו</span> if he bent over a portion (of the blood). <span class=\"citation\">Sabb. 17ᵃ</span> <span dir=\"rtl\">אי׳ צדו אחת וכ׳</span> he caused one side of his body <i>to overshadow</i> the grave.—[More freq.]</div><div class=\"sense\"><b>Hif. הֶאֱהִיל</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"אהינו\">same</a>. Ohol. III, 1; 3 sq. <span dir=\"rtl\">הא׳ על המת</span> he formed a tent, i.e. spread himself, or bent, over a corpse. Ib. <span dir=\"rtl\">הבית מַאֲחִיל עליו</span> the house forms a cover over part of it. Y. Sot. IX, 23ᶜ top; a. fr.</div></div>","alt":[]},"501":{"h":"אֹהֶל","r":"A00501","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>tent, shelter</i>. <span class=\"citation\">Succ. 21ᵇ</span> <span dir=\"rtl\">א׳ עראי</span> a temporary dwelling. <span dir=\"rtl\">א׳ קבע</span> a permanent dwelling.—<span class=\"citation\">Naz. 55ᵃ</span> <span dir=\"rtl\">א׳ זרוק</span> a movable cover, e.g. a person carried in a vehicle over a grave, v. foreg.—<span class=\"citation\">B. Bath. 27ᵇ</span>, a. fr. <span dir=\"rtl\">א׳ הטומאה</span> something spread over an unclean object, e.g. a tree shading a corpse; v. <a href=\"#\" data-headword=\"אָהַל\">foreg.</a> <span class=\"citation\">Naz. VII, 2</span>, v. <a href=\"#\" data-headword=\"*אָהִיל\">אָהִיל</a>.—Pl. <span dir=\"rtl\">אוֹהֳלִים</span>, <span dir=\"rtl\">(<a href=\"#\" data-headword=\"אהולין\">אָהֳולִין</a>) <span dir=\"rtl\">אוֹהֳלִין</span></span>. Y. Sabb. XX, beg. 17ᶜ <span dir=\"rtl\">נטע א׳</span> to spread sheets over poles &amp;c. (<span class=\"citation\">Tosef. ib. XII</span> (<span class=\"citation\">XIII), 14</span>, a. e. <span dir=\"rtl\">עשה א׳</span>). <span class=\"citation\">Y. Erub. I, 19ᵈ</span> <span dir=\"rtl\">א׳ בשיירה</span> tents in a caravan, <span dir=\"rtl\">א׳ שבמחנה</span> in a camp. <span class=\"citation\">Tosef. Kil. V, 25</span> <a href=\"#\" data-headword=\"אהולין\">אהולין</a> ed. Zuck.</div>","alt":["אוֹהֶל"]},"502":{"h":"אֳהָל","r":"A00502","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Syr. <span dir=\"rtl\">אחלא</span> P. Sm. 125; <a href=\"#\" data-headword=\"הל\">הל</a>, <a href=\"#\" data-headword=\"חל\">חל</a>, v. <span dir=\"rtl\">הלל</span>, <a href=\"#\" data-headword=\"חָלַל\">חלל</a>, cmp. <span dir=\"rtl\">מוהל</span>, <a href=\"#\" data-headword=\"מוֹחַל\">מוחל</a>) </div><div class=\"sense\"><b>1)</b> <i>an alcalic plant</i>, used as <i>soap</i>. <span class=\"citation\">Sabb. 90ᵃ</span>; <span class=\"citation\">Nidd. 62ᵃ</span> (counted among plants subject to the laws of the Sabbath year).</div><div class=\"sense\"><b>—2)</b> <i>a mineral substance</i> of the <a href=\"#\" data-headword=\"אֹהֶל\">same</a> use (in connection with <a href=\"#\" data-headword=\"נָתַר I\">נתר</a>; v. however Maim. to <span class=\"citation\">Nidd. IX, 6</span>). Nidd. l. c. <span dir=\"rtl\">והתניא הבורית והאהל</span>; (Sabb. l. c. first time <a href=\"#\" data-headword=\"חוּל\">חול</a> ed., Ms. M. <a href=\"#\" data-headword=\"אָהֵיל\">אָהֵיל</a>; sec. time <span dir=\"rtl\">אהלא</span> ed., Ms. M. <span dir=\"rtl\">אהיל</span>). <span class=\"citation\">M. Kat. 17ᵇ</span>; a, e. [The biblical <span dir=\"rtl\">אהלים</span> a. <a href=\"#\" data-headword=\"אָהֳלוֹת\">אהלות</a> have no connection of meaning with our w.]</div>","alt":["(אוֹהָל)"]},"503":{"h":"אָהֳלָא","r":"A00503","html":"<div class=\"sense\"><i>tent, sheet</i>. <span class=\"citation\">Targ. Y. Num. XII, 12</span> (Var. <a href=\"#\" data-headword=\"אֲהִילָא\">אֲהִילָא</a>, <a href=\"#\" data-headword=\"אֲהִילָא\">אָהֵילָא</a>). <span class=\"citation\">Bets. 30ᵇ</span> <span dir=\"rtl\">קא סתר א׳</span> he breaks the tent up (by removing portions of the cover). <span class=\"citation\">Ib. 32ᵇ</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"הֲלִי\">אָהֳלֵי</a>. <span class=\"citation\">Sabb. 137ᵇ</span> <span dir=\"rtl\">אוסופי א׳</span> extending the spread sheets (by opening a door or window over which they were spread).</div>","alt":[]},"504":{"h":"אַהֲלָא","r":"A00504","html":"<div class=\"sense\"><b>1)</b>  = h. <a href=\"#\" data-headword=\"אֳהָל\">אֳהָל</a>. <span class=\"citation\">Targ. Job. IX, 30</span> (h. text <span dir=\"rtl\">בור</span>). <span class=\"citation\">Sabb. 90ᵃ</span>, v. <a href=\"#\" data-headword=\"אֳהָל\">אֳהָל</a>.</div><div class=\"sense\"><b>—2)</b>  (= b. h. <span dir=\"rtl\">אהלים</span>, <a href=\"#\" data-headword=\"אָהֳלוֹת\">אהלות</a>?) <i>aloë</i> (used for medicinal purposes, v. Sm. Ant. s. v. Aloë). Ib. 110ᵇ <span dir=\"rtl\">א׳ תולענא</span>; <span class=\"citation\">Git. 69ᵇ</span> <span dir=\"rtl\">א׳ תולאנא</span> purple-colored aloë.</div>","alt":["אוֹהֳלָא"]},"505":{"h":"אָהֳלוֹיָא","r":"A00505","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אַהֲלָא\">foreg.</a>) <i>dealer in aloë</i> (prob. in b. h. , <i>perfumes</i>). . <span class=\"citation\">Ned. 91ᵇ</span>. <span class=\"citation\">B. Mets. 81ᵃ</span></div>","alt":[]},"506":{"h":"אָהֳלוֹת","r":"A00506","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אָהִיל\">אָהִיל</a></div>","alt":[]},"507":{"h":"אָהֳלַיָּא","r":"A00507","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Oholaya</i> (tents) <span class=\"citation\">Eduy. VII, 4</span> <span dir=\"rtl\">אה׳</span>. <span class=\"citation\">Zeb. 25ᵇ</span> <span dir=\"rtl\">אוה׳</span>.</div>","alt":["אוֹהֳלַיָּיא"]},"508":{"h":"אָהֳלִית","r":"A00508","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">אהל</span>) <i>a group of tents, encampment;</i> only in Pl. <span dir=\"rtl\">אָהֳלִיֹּות</span> (= <i>castra</i>) <i>camps</i>. (Always in connection with <a href=\"#\" data-headword=\"בְּצוֹצְרִיּוֹת\">בצוצריות</a> or <a href=\"#\" data-headword=\"קַסְטְרָא\">קסטרא</a> fortifications). <span class=\"citation\">Cant. R. to II, 13</span>. <span class=\"citation\">Yalk. Ps. 624</span> <span dir=\"rtl\">אהו׳</span>. <span class=\"citation\">Lev. R. s. 1</span>; a. e. [Cmp. <a href=\"#\" data-headword=\"בְּצוֹצְרִיּוֹת\">בְּצוֹצְרִיֹּות</a> a. <a href=\"#\" data-headword=\"גַּסְטְרָא\">גַּסְטְרָא</a> as to versions.]</div>","alt":["(אָהֳולִית)"]},"509":{"h":"אהמרא","r":"A00509","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַחְמְרָא\">אַחְמְרָא</a></div>","alt":[]},"510":{"h":"אֲהָן","r":"A00510","html":"<div class=\"sense\"> or <a href=\"#\" data-headword=\"אֲהָן\">אֲהֵן</a>, <a href=\"#\" data-headword=\"אהון\">אֲהוֹן</a> m. (= <a href=\"#\" data-headword=\"הָן\">הָן</a>, <a href=\"#\" data-headword=\"הַהֵין\">הֲהָן</a>, √<span dir=\"rtl\">ה־</span>) </div><div class=\"sense\"><b>1)</b> <i>this, that, he who</i>. <span class=\"citation\">Y. Ber. II, 4ᶜ</span> bot. <span dir=\"rtl\">א׳ חזירא</span> that swine. Ib. VI, 10ᵃ bot. <span dir=\"rtl\">א׳ דמר</span> he who says. <span class=\"citation\">Y. Yoma VI, 43ᵈ</span> bot. <span dir=\"rtl\">כא׳ דתנינן</span> as that (Mishnah) which we have been taught. <span class=\"citation\">Y. Shek. II, 47ᵃ</span> top <span dir=\"rtl\">א׳ דהכא</span> the subject just quoted. Y. B. Mets. II, 8ᶜ <span dir=\"rtl\">(<a href=\"#\" data-headword=\"אהון\">אהון</a>) <span dir=\"rtl\">אהין להן לי אהן מהו חשוב</span></span> of what use is this to me? of what value is it to me?—<span class=\"citation\">Y. Shebu. III, 34ᵈ</span> bot. <span dir=\"rtl\">וא׳ אפילו</span> and this ‘even’—i.e. why do you use the word ‘even’?—a. fr.</div><div class=\"sense\"><b>—2)</b> <i>this place, where</i>. <span class=\"citation\">Y. Ber. IX, 13ᵇ</span> top <span dir=\"rtl\">כל א׳ דאת אזיל</span> wherever thou goest. </div><div class=\"sense\"><b>*3)</b>  (adv. of time = <span dir=\"rtl\">על־הן</span>, v. <a href=\"#\" data-headword=\"אַ־\">אַ־</a>) <i>thereupon, then</i>. <span class=\"citation\">Y. Taan. IV, 69ᵇ</span> top <span dir=\"rtl\">אכלון ואהון וכ׳</span> eat ye and then drink.</div>","alt":[]},"511":{"h":"אהנייתא","r":"A00511","html":"<div class=\"sense\"> <span class=\"citation\">Keth. 67ᵇ</span> <span dir=\"rtl\">מקרבן אהנייתי</span>, v. <a href=\"#\" data-headword=\"הֲנָיָיה\">הֲנָיָיה</a> ch.</div>","alt":[]},"512":{"h":"אַהֲרוֹן","r":"A00512","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (b. h.) <i>Aaron</i>, the brother of Moses. <span class=\"citation\">Meg. 25ᵇ</span>; a. fr.</div>","alt":["אַהֲרֹן"]},"513":{"h":"אַהֲרוֹנִית","r":"A00513","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (deriv. of <a href=\"#\" data-headword=\"אַהֲרוֹן\">foreg.</a>) <i>of priestly parentage, Aaronide</i>. <span class=\"citation\">Erub. 53ᵇ</span> <span dir=\"rtl\">נערה א׳ אחרונית</span> (play on words) an Aaronide maiden, a second wife (in Ms. M. our w. is missing).</div>","alt":[]},"514":{"h":"אַהֲרֹן","r":"A00514","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַהֲרוֹן\">אַהֲרוֹן</a></div>","alt":[]},"515":{"h":"או־","r":"A00515","html":"<div class=\"sense\"><b>1)</b>  prefix, esp. for verbal nouns, e.g. 1) prefix, esp. for verbal nouns, e.g. <a href=\"#\" data-headword=\"אוֹדִיצוּתָא\">אודיצותא</a> fr. <a href=\"#\" data-headword=\"דִּיץ I\">דיץ</a>. </div><div class=\"sense\"><b>2)</b>  <a href=\"#\" data-headword=\"אוֹ I\">או</a>, <span dir=\"rtl\">אוו</span> = εὐ-αὐ, v. <a href=\"#\" data-headword=\"אָב I\">אב</a></div>","alt":[]},"516":{"h":"אוֹ I","r":"A00516","html":"<div class=\"sense\"> , v. Ges. H. Dict. s. v.) <i>or;</i> או … או <i>either</i> … <i>or</i>. <span class=\"citation\">Shebu. 27ᵃ</span> <span dir=\"rtl\">או … לחלק</span> the word <a href=\"#\" data-headword=\"אוֹ\">אוֹ</a> in the Bible text is necessary as a disjunctif, (one <i>or</i> the other), contrad. from <span dir=\"rtl\">ו־</span> which is conjunctive (one <i>and</i> the other). <span class=\"citation\">Men. 91ᵃ</span>; <span dir=\"rtl\">או לדרשא</span> the word <a href=\"#\" data-headword=\"אוֹ\">אוֹ</a> intimates something not explicitly stated in the text; a. fr.—Pl. <a href=\"#\" data-headword=\"אוֹיִים\">אוֹאִין</a> <span class=\"citation\">Shebu. 33ᵇ</span>.—<a href=\"#\" data-headword=\"אוֹיִים\">אוֹיִין</a>, <a href=\"#\" data-headword=\"אוֹיִים\">אוֹיִים</a>, const. <span dir=\"rtl\">אוֹיֵי</span> <i>the word</i> <a href=\"#\" data-headword=\"אוֹ\">אוֹ</a> in <i>the biblical passages</i>. Y. ibid. IV, 35ᶜᵈ</div>","alt":[]},"517":{"h":"אוֹ","r":"A00517","html":"<div class=\"sense\"><span class=\"citation\">Targ. Ex. XXI, 20</span>; a. e. <span class=\"citation\">Targ. Prov. VI, 28</span> Ms. (ed. <span dir=\"rtl\">אי</span>).—<span class=\"citation\">Ber. 2ᵇ</span>, v. <a href=\"#\" data-headword=\"דילמא\">דילמא</a>; a. v. fr.</div>","alt":[]},"518":{"h":"אוֹ II","r":"A00518","html":"<div class=\"sense\"> (ὁ) <i>the</i>. <span class=\"citation\">Y. R. Hash. I, 57ᵃ</span> bot. (in a Greek sentence), v. <a href=\"#\" data-headword=\"*אַגְרָפוֹס\">אגרפוס</a>.</div>","alt":[]},"519":{"h":"אוּ","r":"A00519","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (contr. of <a href=\"#\" data-headword=\"אהו\">אֲהוּ</a>, <span dir=\"rtl\">אֲהִי</span> v. <a href=\"#\" data-headword=\"הוּ\">הוּ</a>, <a href=\"#\" data-headword=\"הוּא ²\"><a href=\"#\" data-headword=\"הוּא ²\">הִי</a>)</a><i>he, that, this</i> (only in Y. Dial). [Y. Ber. II, 5ᵇ top <span dir=\"rtl\">או מקשי</span>, read <span dir=\"rtl\">הוה מ׳</span>; ed. Amst. <a href=\"#\" data-headword=\"בעי\">בעי</a>.] Y. B. Bath. III, 14ᵇ I was jesting <span dir=\"rtl\">באו גברא</span> with that man. <span class=\"citation\">Y. Snh. XI, beg. 30ᵃ</span> <span dir=\"rtl\">באו ד</span>(<a href=\"#\" data-headword=\"א\">א</a>)<span dir=\"rtl\">מר</span> with him who says—<i>Fem</i>. <a href=\"#\" data-headword=\"אִי IV\">אִי</a>.—<span class=\"citation\">Y. Erub. III, 21ᵇ</span> bot. <span dir=\"rtl\">אי אידא אי אידא</span> it is all the same; v. <a href=\"#\" data-headword=\"אִידָא II\"><span dir=\"rtl\">אִידָא</span> II</a>.</div>","alt":[]},"520":{"h":"אַוָּארָא","r":"A00520","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אוֹר\">אור</a>; cmp. h. form <a href=\"#\" data-headword=\"צַוָּאר\">צַוָּאר</a>), only in <span dir=\"rtl\">א׳ דליבני</span> <i>a pile of loose bricks with openings between</i>, opp. to solid wall. <span class=\"citation\">Bets. 31ᵇ</span>; <span class=\"citation\">36ᵃ</span>; <span class=\"citation\">Erub. 34ᵇ</span> Ms. Rashi (v. Rabb. D. S. a. l.; ed. <a href=\"#\" data-headword=\"אַוָּארָא\">אַוִּירָא</a>, cmp. <a href=\"#\" data-headword=\"אָוֵירָא\">אָוֵירָא</a>; Ar. <a href=\"#\" data-headword=\"אֲאָרָא\">אארא</a>, derives fr. Pers.).</div>","alt":["(אַוִּירָא)"]},"521":{"h":"אוֹב","r":"A00521","html":"<div class=\"sense\"><i>shoots</i>, v. <a href=\"#\" data-headword=\"אֵב\">אֵב</a>.</div>","alt":[]},"522":{"h":"אוֹב ²","r":"A00522","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>cited ghost</i>.—בעל א׳ <i>necromancer</i>. <span class=\"citation\">Snh. 65ᵃ</span>; a. fr.</div>","alt":[]},"523":{"h":"אוֹב ³","r":"A00523","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Is. XXIX, 4</span>; a. e.—<span dir=\"rtl\">א׳ טמיא</span> necromancy over bones, sculls, also for <i>necromancer</i>. <span class=\"citation\">Targ. Y. I Deut. XVIII, 11</span>. <span class=\"citation\">Ber. 59ᵃ</span> <span dir=\"rtl\">א׳ טמיא כדיב וכ׳</span> the necromancer is a liar (necromancy is false), and his (its) words are lies. <span class=\"citation\">Sabb. 152ᵇ</span> bot. (of the woman of En-Dor, <span class=\"citation\">I Sam. XXVIII, 7</span>). [<span class=\"citation\">Yeb. 103ᵃ</span> <a href=\"#\" data-headword=\"אמוראי\">בר א׳</a>, v. <a href=\"#\" data-headword=\"אַבְיוּ\">אַבְיוּ</a>.]</div>","alt":["אוּבָא"]},"524":{"h":"אוֹבְדָן","r":"A00524","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אָבְדָּן\">אָבְדָּן</a>, <a href=\"#\" data-headword=\"אַבְדָּנָא\"><a href=\"#\" data-headword=\"אַבְדָּנָא\">אַבְדָּנָא</a>.</a></div>","alt":["אוֹבְדָנָא"]},"525":{"h":"אובינות","r":"A00525","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֶבְיוֹנָה\">חֶבְיוֹנָה</a></div>","alt":[]},"526":{"h":"אוֹבִיסוֹס","r":"A00526","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Ephesus</i>, city of Ionia in Asia Minor. <span class=\"citation\">Targ. I Chr. I, 5</span> <a href=\"#\" data-headword=\"אוֹב\">אוֹב׳</a> (var. lect.); Y. Meg. I, 71ᵇ <span dir=\"rtl\">אוו׳</span> bot. (rendit. of <span dir=\"rtl\">יון</span>); v. <span dir=\"rtl\">מַקְדֹּונְיָא</span>.</div>","alt":["אֶוְוסוֹס"]},"527":{"h":"אוּבָל","r":"A00527","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"יוֹבֵל\">יוּבָל</a>) </div><div class=\"sense\"><b>1)</b> <i>river.</i> <span class=\"citation\">Dan. VIII, 2</span>; <span class=\"citation\">3</span>; <span class=\"citation\">6</span>.</div><div class=\"sense\"><b>—2)</b>  as a pr. n. <i>Ubal</i> (The River). <span class=\"citation\">Gen. R. s. 16</span> (referring to Dan. l. c.) <span dir=\"rtl\">א׳ אוותנטין וכ׳</span> Ubal is the source of all the other rivers.</div>","alt":["אֻבָל"]},"528":{"h":"אוּבְלָא I","r":"A00528","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"אֶבְלָא\">אֶבְלָא</a>. <span class=\"citation\">Targ. Y. Gen. VII, 10</span>; a. e.</div>","alt":[]},"529":{"h":"אוּבְלָא II","r":"A00529","html":"<div class=\"sense\"> m. (<a href=\"#\" data-headword=\"יְבַל\">יבל</a>) <i>vessel made of willow twigs; basket</i>, or <i>perforated trough</i>; (as to shape v. Sm. Ant. s. v. <i>Călathus</i>). <span class=\"citation\">Bekh. 43ᵇ</span>, v. <a href=\"#\" data-headword=\"בִּילוֹן\">בִּילוֹן</a> a. <a href=\"#\" data-headword=\"כִּילוֹן\">כִּילוֹן</a>. Sab. 123ᵇ; <span class=\"citation\">Snh. 92ᵃ</span>, a. e. <span dir=\"rtl\">א׳ דקצרי</span> Ar. (ed. <span dir=\"rtl\">אוכ׳</span>) the fuller’s trough. Ib. 28ᵇ the father of the husband and the father of the wife are no more kinsmen <span dir=\"rtl\">אלא כי א׳ לדנא</span> (ed. <span dir=\"rtl\">אכלא</span>) than is a basket related to a barrel. [For <span dir=\"rtl\">אכלא</span>, <a href=\"#\" data-headword=\"אוּבְלָא II\">אוכלא</a> cmp. <span dir=\"rtl\">כְּלִיל</span>, <a href=\"#\" data-headword=\"כַּלְכָּלָה\">כַּלְכָּלָה</a>.]</div>","alt":["(אוּכְלָא","אָכְלָא)"]},"530":{"h":"אוּבְלִים","r":"A00530","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אֲבֵילִין\">אֲבֵילִין</a>) <i>Ub’lim, Ub’lin</i>. <span class=\"citation\">Erub. 12ᵃ</span> top (var. v. Rabb. D. S. a. l. note 1). <span class=\"citation\">Ḥull. 55ᵇ</span> <a href=\"#\" data-headword=\"אוּבְלִים\">אובלים</a> (ed. <a href=\"#\" data-headword=\"אִסְקְרִיטִין\">אי׳</a>).</div>","alt":["אוּבְלִין"]},"531":{"h":"אוֹבַנְתָּא","r":"A00531","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲבַנְתָּא\">אֲבַנְתָּא</a></div>","alt":[]},"532":{"h":"אוּבְצָנָא","r":"A00532","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">אבץ</span>. cmp. <span dir=\"rtl\">חָבַץ II</span>, a. <a href=\"#\" data-headword=\"חָבַץ\">חבץ</a> P. Sm. 1181 sq.) <i>heavy pressure, overload, prostration from heavy load</i>. <span class=\"citation\">Targ. Y. Num. XIX, 2</span>.—<span class=\"citation\">B. Mets. 36ᵇ</span> <span dir=\"rtl\">א׳ דהר</span> the prostration from carriyng a load up hill. <span class=\"citation\">Ib. 78ᵃ</span> <span dir=\"rtl\">מתה מחמת א׳</span> died from fatigue. <span class=\"citation\">Sabb. 106ᵇ</span>. [Ar. reads <a href=\"#\" data-headword=\"אוכצנא\">אוכצנא</a>, cmp. Syr. <span dir=\"rtl\">אכץ</span> P. Sm. 190—corr. acc.]</div>","alt":[]},"533":{"h":"אוֹבְרִיזָא","r":"A00533","html":"<div class=\"sense\"> f., <span dir=\"rtl\">אוֹבְרִיזוֹן</span>, <span dir=\"rtl\">אוֹבְרִיזִין</span> m. (ὄβρυζον) <i>pure gold, unalloyed</i>. <span class=\"citation\">Targ. Ps. CXIX, 127</span>; <span class=\"citation\">Targ. Prov. VIII, 19</span>; a. e.</div>","alt":[]},"534":{"h":"אוּבְשִׁין","r":"A00534","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"><i>a species of inferior grapes.</i> <span class=\"citation\">Maasr. I, 2</span> הענבים והאו׳ משיבאישו Ar. (ed. Talm. B. <span dir=\"rtl\">והאב׳ משה׳</span>; Talm. Y. <span dir=\"rtl\">הבאושין</span>) grapes and <i>ubshin</i> are subject to tithes from the time they are called <a href=\"#\" data-headword=\"בְּאוּשָׁה\">בְּאוּשָׁה</a> q. v.—Y. Ter. VIII, 45ᵈ top <span dir=\"rtl\">ענבים ואו׳ וכ׳</span> grapes or ubshin for a sick person.</div>","alt":["אֻבְשִׁין"]},"535":{"h":"אוֹג","r":"A00535","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"אֵגֶה\">אֵגֶה</a>; Syr. <span dir=\"rtl\">אוגא</span> P. Sm. 53) (rhus coriaria), <i>red berry of the Venus’ summachtree.</i> <span class=\"citation\">Peah I, 5</span>. <span class=\"citation\">Dem. I, 1</span>. <span class=\"citation\">Maasr. I, 2</span>. <span class=\"citation\">Kel. XXVI, 3</span>.—Pl. <span dir=\"rtl\">אוֹגִין</span>. Tosef. Maas. I, 4 <span dir=\"rtl\">אובין אדומים</span> (<span dir=\"rtl\">איבין</span>, corr. acc.; cmp. Maasr. l. c. V. Löw Aram. Pfl. p. 44).</div>","alt":[]},"536":{"h":"אוּגָד","r":"A00536","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֵגֶד\">אֵגֶד</a></div>","alt":[]},"537":{"h":"אוגדויי","r":"A00537","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹגְדוֹיִיקוֹנְטָא\">next w.</a></div>","alt":[]},"538":{"h":"אוֹגְדוֹיִיקוֹנְטָא","r":"A00538","html":"<div class=\"sense\"> (ὀγδοήκοντα) <i>eighty</i>. Y. B. Bath. X, 17ᶜ (corrected text) <span dir=\"rtl\">שטר נפיק מר׳ חונה לר׳ שמיי אוגדויי מחיק קונטא לא מחיק</span>. <span dir=\"rtl\">א&quot;ר שמיי לר׳ חונה פוק חזי עם ההן אהן קונטא משמש</span>. <span dir=\"rtl\">ומר עם טרייאקונטא</span>. <span dir=\"rtl\">כי נפק אמר הדא בעי מתגרא תלתין אפסד עשרין</span>. A bill of indebtedness passed from R. Ḥuna (who could not decide or on whose decision the party would not rely) to R. Sh.—on which bill <i>ogdoë</i> was blurred (showing an erasure), and <i>conta</i> was clear. Said R. Sh. to R. Ḥ., Go and see what is the lowest numeral in Greek that <i>conta</i> is combined with. Said he, It is <i>triaconta</i> (thirty).—When the party had left, he said, That man intended to make thirty (by the erasure) and lost twenty (the original having been fifty, <i>penteconta</i>).</div>","alt":[]},"539":{"h":"אוֹגְדוֹר","r":"A00539","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Ogdor</i> (Zigdor) in Samaria. <span class=\"citation\">Y. Ab. Zar. V, 44ᵈ</span>. Bab. <span class=\"citation\">Ab. Zar. 31ᵃ</span> <span dir=\"rtl\">זג׳</span> (Ms. M. <span dir=\"rtl\">זגרור</span>).</div>","alt":["(זגדור)"]},"540":{"h":"אוֹגְדוּתָא","r":"A00540","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (אֲגַד II) <i>prolongation</i>. <span class=\"citation\">Targ. Y. Deut. XXX, 20</span>, const. <a href=\"#\" data-headword=\"אוֹגְדוּתָא\">אוֹגְדוּת</a> (Var. <span dir=\"rtl\">אוֹגְרוּת</span>).</div>","alt":[]},"541":{"h":"אוגורי","r":"A00541","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֵגוֹר\">אֵגוֹר</a> end.</div>","alt":[]},"542":{"h":"אוּגְיָא","r":"A00542","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">אגי</span>, sec. r. of <a href=\"#\" data-headword=\"אוֹג\">אוג</a>, v. <a href=\"#\" data-headword=\"אָוֶן\">אָוֶן</a>; cmp. <a href=\"#\" data-headword=\"עוּגָּה\">עוּגָה</a>) <i>rounded off</i>, whence <i>a field</i> or <i>fields surrounded with a ridge or ditch</i>. <span class=\"citation\">Ned. 6ᵇ</span>. <span class=\"citation\">Ber. 6ᵃ</span> <span dir=\"rtl\">כי כסלא לא׳</span> like the ridge surrounding the field.</div>","alt":["(אֻגְיָא)"]},"543":{"h":"אוּגְיָה","r":"A00543","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אוּגְיָא\">foreg.</a>) <i>rounded ditch, hole dug around the grape-vine</i>. <span class=\"citation\">M. Kat. I, 1</span> (Rashi to <span class=\"citation\">Ber. 6ᵃ</span>, Asheri to <span class=\"citation\">Ned. 6ᵇ</span> expl. <a href=\"#\" data-headword=\"אוּגְיָא\">foreg. w.</a>; ed. <span dir=\"rtl\">עוּגְיוֹת</span>).</div>","alt":[]},"544":{"h":"אוֹגֶן","r":"A00544","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אוֹג\">אוג</a>; v. <a href=\"#\" data-headword=\"אוּגְיָה\">foreg.</a>) <i>border of a vessel, rim</i>. <span class=\"citation\">Ḥull. 25ᵃ</span>; <span class=\"citation\">25ᵇ</span>; <span class=\"citation\">Tosef. Kel. B. Mets. II, 17</span> <a href=\"#\" data-headword=\"ה׳\">ה׳</a>. <i>Ḥag</i>. 22ᵇ <span dir=\"rtl\">אוֹגנוֹ</span> its border. Pl. <span dir=\"rtl\">אוֹגְנִים</span>, <span dir=\"rtl\">אוֹגְנִין</span>, <span dir=\"rtl\">הוֹ׳</span>. <span class=\"citation\">Nidd. 3ᵇ</span>. <span class=\"citation\">Erub. 87ᵇ</span> (banks). <span class=\"citation\">Kel. XXV, 6</span>; a. e. [<span class=\"citation\">Ḥull. II, 9</span> (<span class=\"citation\">41ᵃ</span>) <span dir=\"rtl\">אוּגָן של מים</span> Ar., <i>a little pool</i>, ed. <a href=\"#\" data-headword=\"עוּגָּה\">עוּגָה</a> q. v.]</div>","alt":["הוֹגֶן"]},"545":{"h":"אוֹגָנָא","r":"A00545","html":"<div class=\"sense\">(v. <a href=\"#\" data-headword=\"אוֹגֶן\">foreg.</a>) <i>something rounded basin, disk</i>. <span class=\"citation\">Targ. Cant. VII, 3</span> <span dir=\"rtl\">א׳ דסיהרא</span> the disk of the moon.—<span class=\"citation\">B. Mets. 69ᵇ</span> <span dir=\"rtl\">א׳ דקירא</span> (some ed. <span dir=\"rtl\">אוֹגְנֵי</span> pl., v. Rashi a. l., Ms. M. <a href=\"#\" data-headword=\"גְּנֵי\">אַגָּנֵי</a>, v. <a href=\"#\" data-headword=\"אַגָּנָא\">אַגָּנָא</a>) cake of wax. Cmp. <a href=\"#\" data-headword=\"*אַגֵּין\">אַגֵּין</a>.</div>","alt":[]},"546":{"h":"אֶוְגְּנֵס","r":"A00546","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֶבְגִּינוֹס\">אֶבְגִּינוֹס</a></div>","alt":[]},"547":{"h":"אוֹגַר","r":"A00547","html":"<div class=\"sense\"> Af. of <a href=\"#\" data-headword=\"אֲגַר I\">אֲגַר</a>.</div>","alt":[]},"548":{"h":"אוֹגַר ²","r":"A00548","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אָגַר I\">אָגַר</a>, <a href=\"#\" data-headword=\"גְּרַר\">גְּרַר</a>) <i>heap of stones, stone-hill</i> (h. <a href=\"#\" data-headword=\"גַּל\">גַּל</a>). <span class=\"citation\">Targ. Y. Gen. XXXI, 46</span> (Bab. <a href=\"#\" data-headword=\"דְּגוֹרָא\">דְּגוֹרָא</a>); a. fr. V. <a href=\"#\" data-headword=\"אֱגוֹרָא I\"><span dir=\"rtl\">אֱגוֹרָא</span> I</a>.</div>","alt":["אוֹגְרָא"]},"549":{"h":"אוגרוי","r":"A00549","html":"<div class=\"sense\">, read <a href=\"#\" data-headword=\"אוגדויי\">אוגדויי</a>.</div>","alt":[]},"550":{"h":"אוגרים","r":"A00550","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּרַם I\">גְּרַם</a> Af.</div>","alt":[]},"551":{"h":"אוגרנא","r":"A00551","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַגְדָּנָא\">אַגְדָּנָא</a></div>","alt":[]},"552":{"h":"אוֹגֶרֶת","r":"A00552","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>a knife having notches</i>, v. <a href=\"#\" data-headword=\"אָגַר II\"><span dir=\"rtl\">אָגַר</span> II</a>.</div>","alt":[]},"553":{"h":"אוּד","r":"A00553","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. Ges. H. Dict. s. v.; cmp. <a href=\"#\" data-headword=\"אֵיד\">אֵיד</a>) <i>wooden poker</i>. <span class=\"citation\">Bets. 33ᵃ</span>; <span class=\"citation\">Sabb. 143ᵃ</span></div>","alt":[]},"554":{"h":"אוּד ²","r":"A00554","html":"<div class=\"sense\">, also <i>fire-brand</i>. <span class=\"citation\">Targ. Am. IV, 11</span>; a. e.—Pl. <a href=\"#\" data-headword=\"יְדִי\">אוּדֵי</a>, <a href=\"#\" data-headword=\"אוּדְיָא\">אוּדַיָּא</a>. <span class=\"citation\">Targ. Is. VII, 4</span>.—<span class=\"citation\">Snh. 93ᵃ</span> (prov. concerning bad company) <span dir=\"rtl\">תרי א׳ וכ׳</span></div>","alt":["אוּדָא"]},"555":{"h":"אוֹדָאָה","r":"A00555","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"ודי\">ודי</a>, Af. <a href=\"#\" data-headword=\"יְדִי\">אודי</a>) <i>thanksgiving</i>. <span class=\"citation\">Targ. Ps. XLV, 1</span> (var. <span dir=\"rtl\">אוֹדֵאָתָא</span>); a. e.</div>","alt":["אוֹדָאוּתָא","אוֹדוּתָא"]},"556":{"h":"אוּדְדָא","r":"A00556","html":"<div class=\"sense\"> ed. m. (<span dir=\"rtl\">אדד</span>, <a href=\"#\" data-headword=\"אֵדֶר I\">אדר</a>, v. <a href=\"#\" data-headword=\"אָדַר\">אָדַר</a>: Syr. <a href=\"#\" data-headword=\"אוּדְדָא\">אודדא</a>; cmp. <a href=\"#\" data-headword=\"אַדְדָא\">אַדְדָא</a>, <a href=\"#\" data-headword=\"אַדְרָא\">אַדְרָא</a> as to dial. var.) <i>upholsterer’s stuffing material, tow-cotton, wool</i>. <span class=\"citation\">Sabb. 48ᵃ</span> <span dir=\"rtl\">לאהדורי א׳</span> (Ms. M. <span dir=\"rtl\">אוּדְדֵי</span> <i>Pl.</i>) to put the stuffing back into the mattress. <span class=\"citation\">Ib. 141ᵃ</span> (Ms. M. <a href=\"#\" data-headword=\"אוּדְדָא\">אודדא</a>); v. <a href=\"#\" data-headword=\"אֲשִׁישָׁא\">אֲשִׁישָׁא</a>.—<span class=\"citation\">B. Bath. 58ᵃ</span> <span dir=\"rtl\">חביתא דא׳</span> (Mss. <span dir=\"rtl\">דאודד׳</span>) a vessel full of stuffings (enigmatical for bolsters). <span class=\"citation\">Ab. Zar. 28ᵇ</span> <span dir=\"rtl\">א׳ דנדא וכ׳</span> (Ms. M. <span dir=\"rtl\">ארדא דנורא</span>) tow cotton which has been dyed but not combed. <span class=\"citation\">B. Mets. 26ᵃ</span>; a. fr.—Pl. <span dir=\"rtl\">אוּדְדֵי</span>. <span class=\"citation\">Kidd. 12ᵃ</span> <span dir=\"rtl\">זוודא דאורדי</span> (corr. acc.) a bundle of tow-cotton. [Cmp. <a href=\"#\" data-headword=\"עוּדְדָא\">עוּדְדָא</a>, <a href=\"#\" data-headword=\"עוּדְרָא\">עוּדְרָא</a>; also <a href=\"#\" data-headword=\"אִירָא\">אִירָּא</a> a. <a href=\"#\" data-headword=\"*אִידָּן\">אִידָּן</a>; v. Fuerst, H. Dict. lit. <a href=\"#\" data-headword=\"ר\">ר</a>.]</div>","alt":[]},"557":{"h":"אוּדְיָא","r":"A00557","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"ידי\">ידי</a>, <span dir=\"rtl\">אדי</span>; cmp. funda = sling and purse) <i>purse</i>. <span class=\"citation\">B. Mets. 28ᵇ</span> <span dir=\"rtl\">א׳ דדינרי</span> (ed. <a href=\"#\" data-headword=\"אודייא\">אוּדְיָיא</a>) a purse of denars.</div>","alt":[]},"558":{"h":"אודיאר","r":"A00558","html":"<div class=\"sense\">, <span class=\"citation\">Toh. VII, 7</span>, v. <a href=\"#\" data-headword=\"אוֹרְיָיר\">אוֹרְיָיר</a></div>","alt":[]},"559":{"h":"אודייא","r":"A00559","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוּדְיָא\">אוּדְיָא</a></div>","alt":[]},"560":{"h":"אודיין","r":"A00560","html":"<div class=\"sense\">, read <a href=\"#\" data-headword=\"אוֹרְיָין\">אוֹרְיָין</a>.</div>","alt":[]},"561":{"h":"אוּדְיָינִי","r":"A00561","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"ידי\">ידי</a>, <a href=\"#\" data-headword=\"נדי\">נדי</a>) <i>whatever appertains to irrigation, sprinkling arrangements</i>; hence <i>the field cistern with its purtenances</i>. <span class=\"citation\">B. Bath. 144ᵃ</span> (Ms. <a href=\"#\" data-headword=\"אִידְיָנִי\">אִידְיָנִי</a>, <span dir=\"rtl\">אִידְיָי׳</span>; v. Rashi a. l.) if a father left nothing <span dir=\"rtl\">אלא א׳ וכ׳</span> but a sprinkling business, what is earned with it belongs to all heirs alike. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שאני א׳ דלנטירותא וכ׳</span> it is different with a sprinkling business, since all the attendance it requires, is watching (which minors can do just as well as adults). [Tossaf. ib. Var. <span dir=\"rtl\">אידווני</span>, <i>watching pedestal</i>, fr. <a href=\"#\" data-headword=\"דוי\">דוי</a> q. v. Cmp. however <a href=\"#\" data-headword=\"אוּדְנָא III\"><span dir=\"rtl\">אוּדְנָא</span> III</a>.—<span class=\"citation\">M. Kat. 21ᵃ</span>, read <a href=\"#\" data-headword=\"*אוּרְיָינִי\">אוּרְיָינִי</a>.]</div>","alt":[]},"562":{"h":"*אוּדְיָיתָא I","r":"A00562","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אוּדְיָינִי\">foreg.</a>) <i>irrigated fields</i>. <span class=\"citation\">Targ. Jer. XXXI, 40</span> Ar. ed. pr. (ed. <a href=\"#\" data-headword=\"אֲרִיתָא\">אֲרִיתָא</a> q. v. ed. Ven. <span dir=\"rtl\">אֵדִיתָא</span>).</div>","alt":[]},"563":{"h":"*אוּדְיָיתָא II","r":"A00563","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">דוע</span>, v. <a href=\"#\" data-headword=\"אַדְווּתָא\">אַדְווּתָא</a>) <i>attendant</i>, or <i>superintendent of the vapor bath;</i> cmp. <a href=\"#\" data-headword=\"אֲזִי\">אֲזִי</a></div>","alt":[]},"564":{"h":"אוֹדִיצוּתָא","r":"A00564","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דִּיץ I\">דיץ</a>) <i>joy</i>. <span class=\"citation\">Targ. Ps. LI, 10</span> (ed. Vien. <a href=\"#\" data-headword=\"אֲדִי\">אֲדִי׳</a>).</div>","alt":[]},"565":{"h":"אוֹדִיקוּתָא","r":"A00565","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> prop. <i>outlook</i> (v. <a href=\"#\" data-headword=\"דִּיק\">דִּיק</a>) hence pr. n. pl. <i>Odikutha</i>(h. . <span class=\"citation\">Targ. II Chron. XX, 16</span>.</div>","alt":[]},"566":{"h":"אוֹדִיתָא","r":"A00566","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"ודי\">ודי</a>) <i>confession</i>, esp. <i>document stating a debtor’s admission of his indebtedness in presence of witnesses</i>. <span class=\"citation\">Snh. 29ᵇ</span></div>","alt":[]},"567":{"h":"אוֹדֶם","r":"A00567","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">אדם</span>) <i>red substance, fleshy substance</i> [cmp. <a href=\"#\" data-headword=\"אֲדָמָה\">אֲדָמָה</a>, <a href=\"#\" data-headword=\"אָדָם\">אָדָם</a>; b. h. <a href=\"#\" data-headword=\"אוֹדֶם\">אֹדֶם</a> <i>rubin</i>]. <span class=\"citation\">Y. Kil. VIII, 31ᶜ</span> bot. <span dir=\"rtl\">הא׳ מן האשה</span> from the mother the embryo receives the substance for forming skin, flesh, and blood; opp. <a href=\"#\" data-headword=\"לוֹבֶן\">לוֹבֶן</a> white, sticky substance. <span class=\"citation\">Nidd. 32ᵇ</span> <span dir=\"rtl\">למעוטי איש מא׳</span> to exempt man from being unclean from a red (blood) discharge, opp. to <a href=\"#\" data-headword=\"לוֹבֶן\">לובן</a> white gonorrhoeic discharge.</div>","alt":[]},"568":{"h":"אוֹדֶן","r":"A00568","html":"<p class=\"morphology\">f.</p><div class=\"sense\">(= h. <a href=\"#\" data-headword=\"אֹזֶן\">אֹזֶן</a>, v. Ges. H. Dict. s. v.; √<span dir=\"rtl\">אד</span>, v. <a href=\"#\" data-headword=\"אָדַר\">אָדַר</a>) <i>ear</i>. <span class=\"citation\">Targ. Is. LXIV, 3</span>. <span class=\"citation\">Targ. Ps. XVIII, 45</span> <a href=\"#\" data-headword=\"אוֹדֶן\">אוּדַן</a> (ed. Vien. <span dir=\"rtl\">אוּדִין</span>?, Ms. <span dir=\"rtl\">אוזן</span>). <span class=\"citation\">Targ. Ex. XXIX, 20</span>; a. fr.—<span class=\"citation\">Y. Sabb. VI, 8ᶜ</span> bot. <span dir=\"rtl\">טב לא׳</span> good for ear-ache; v. Bab. <span class=\"citation\">Sabb. 67ᵃ</span>; a. fr.—Pl. <span dir=\"rtl\">אוּדְנִין</span>, <span dir=\"rtl\">אוֹדְנִין</span>, <span dir=\"rtl\">אוּדְנַיָּא</span>, <span dir=\"rtl\">אוּדְנֵי</span>. <span class=\"citation\">Targ. Deut. XXIX, 3</span>; a. fr. (also <span dir=\"rtl\">אֻדְנִין</span>).—<span class=\"citation\">Snh. 106ᵃ</span>. <span class=\"citation\">Y. Maas. Sh. IV, 55ᵇ</span> bot.; <span class=\"citation\">Lam. R. to I, 1</span> (חד כותאי 1), v. <a href=\"#\" data-headword=\"אוּדְנָא II\">next w.</a></div>","alt":["אוּדַן","אוּדָן","אוּדְנָא I"]},"569":{"h":"אוּדְנָא II","r":"A00569","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (from its shape, v. <a href=\"#\" data-headword=\"אוֹדֶן\">foreg.</a> a. P. Sm. 40) </div><div class=\"sense\"><b>1)</b> <i>leather-bottle, jar</i> (a liquid measure). Pl. <span dir=\"rtl\">אוּדְנִין</span>. <span class=\"citation\">Y. Maas. Sh. IV, 55ᵇ</span> bot. (to one who had dreamt he had four <i>udnin</i> = ears, v. <a href=\"#\" data-headword=\"אוֹדֶן\">foreg.</a>) <span dir=\"rtl\">מלוי את תרתי אֻדְנָיךְ ותרתי אוּדְנוֹי דגרבא</span> thou shalt have wine enough to fill thy own two <i>udnin</i> (wine jars), and two <i>udnin</i> (measures) of a garba (v. <a href=\"#\" data-headword=\"גְּרַב ²\"><span dir=\"rtl\">גַּרְבָּא</span> I</a>) besides.</div><div class=\"sense\"><b>—2)</b>  (Syr. <a href=\"#\" data-headword=\"אוּזְנָא\">אוזנא</a>, <span dir=\"rtl\">וזנא</span> P. Sm. 49, 1061) <i>bath-tub</i>. <span class=\"citation\">Ber. 22ᵃ</span> was sitting <span dir=\"rtl\">בא׳ דמיא</span> Ar. (ed. <a href=\"#\" data-headword=\"*בָּאגָנָא\">באגנא</a>, Ms. Beth. Nath. <span dir=\"rtl\">באוזנא</span>) in a tub filled with an <i>udna</i> of water. <span class=\"citation\">Sabb. 157ᵇ</span> א׳ דמיא … Ar. (ed. <span dir=\"rtl\">באוונא</span>, Ms. M. <span dir=\"rtl\">אַדָּנָא</span>) by a bath-tub.</div>","alt":[]},"570":{"h":"אוּדְנָא III","r":"A00570","html":"<div class=\"sense\"> (f.?) (= h. <a href=\"#\" data-headword=\"אֶדֶן\">אֶדֶן</a>; cmp. b. h. <a href=\"#\" data-headword=\"הֲדוֹם\">הֲדֹם</a>; √<a href=\"#\" data-headword=\"דָּא I\">דא</a>, <span dir=\"rtl\">דנא</span>; cmp. <a href=\"#\" data-headword=\"דּוּךְ\">דּוּךְ</a>) <i>foot-stool, camp-chair, folding stool</i>. <span class=\"citation\">Targ. Jer. XLIII, 10</span> אוּדְנֵיה Ar. (ed. <span dir=\"rtl\">אפדניה</span>).—Pl. <span dir=\"rtl\">אוּדְנַיָּא</span>, <a href=\"#\" data-headword=\"אֲדִינַיָּא\">אֲדִינַיָּא</a>. Targ. II <span class=\"citation\">Est. I, 2</span> <span dir=\"rtl\">תרתין אוּדְנוֹי</span> (תרין?) the double footstool of king Solomon. <span class=\"citation\">Tosef. Kel. B. Mets. VIII, 6</span> <span dir=\"rtl\">מָטָה וישן וכ׳</span> (not <span dir=\"rtl\">מיטה</span>) when it bends in (under the weight) but one can sleep on it; if it was originally so made, <a href=\"#\" data-headword=\"טָמֵא II\">טמאה</a> (not <a href=\"#\" data-headword=\"טָהוֹר\">טהורה</a>) it is unclean <span dir=\"rtl\">מפני שהיא כאו׳</span> ed. Zuck. (Var. <a href=\"#\" data-headword=\"אֲדִינַיָּא\">אדיניא</a>, ed. <a href=\"#\" data-headword=\"אדוניא\">אדוניא</a>) because it is made like a double footstool.</div>","alt":["אֲדִינָא"]},"571":{"h":"אוּדְרָא","r":"A00571","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוּדְרָא\">אוּדְרָא</a>, a. <a href=\"#\" data-headword=\"אֵדֶר I\"><span dir=\"rtl\">אֵדֶר</span> I</a>.</div>","alt":[]},"572":{"h":"*אוּדְרָךְ","r":"A00572","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">דרך</span>) <i>a crushing tool, pestle, pounding club</i>. <span class=\"citation\">Targ. Prov. XXVII, 22</span> ed. Buxt. (better, like oth. ed. <a href=\"#\" data-headword=\"*אוּרְדָּךְ\">אוּרְדָּךְ</a>).</div>","alt":[]},"573":{"h":"אָוָה","r":"A00573","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוי\">אוי</a></div>","alt":[]},"574":{"h":"אוֹהֶל","r":"A00574","html":"<div class=\"sense\">, v. <span dir=\"rtl\">אהל׳</span></div>","alt":["אוֹהָל","אוֹהָלָא","אוֹהֳלַיָּיא"]},"575":{"h":"אוֹהֲרָא","r":"A00575","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <span dir=\"rtl\">חוחרא</span>, redupl. of <a href=\"#\" data-headword=\"חרי\">חרי</a> Ar.) <i>net-work</i>, esp. <i>loose fisher’s net</i>, contrad. to <a href=\"#\" data-headword=\"אִיזְלָא\">אִיזְלָא</a>. Y. M. Kat. III, 81ᵇ top <span dir=\"rtl\">הו׳</span>.—Pl. <span dir=\"rtl\">אוֹהֲרֵי</span>. <span class=\"citation\">M. Kat. 11ᵃ</span> <span dir=\"rtl\">למיגדל א׳</span> (Alf. <span dir=\"rtl\">אוחרי</span>) to plait nets. <span class=\"citation\">Git. 60ᵇ</span> bot.</div>","alt":["(הוֹהֲרָא)"]},"576":{"h":"אֶוְוגִּינִיסְטָאטֵי","r":"A00576","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֶבְגְּנִיסְטֵי\">אבגניסטי</a></div>","alt":[]},"577":{"h":"אָוָוז","r":"A00577","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (√<span dir=\"rtl\">אוו</span>, v. <a href=\"#\" data-headword=\"אֲוַשׁ\">אְוַשׁ</a>; cmp. Syr. <span dir=\"rtl\">וזא</span>, a. <span dir=\"rtl\">וזוז</span> <i>bombum edit</i>, P. Sm. 1060) [the noisy], <i>goose</i>. <span class=\"citation\">Ber. 57ᵃ</span> <span dir=\"rtl\">הרואה א׳ וכ׳</span> he who sees a goose in his dream, may hope for wisdom (with ref. to <span class=\"citation\">Prov. I, 20</span>, ‘wisdom cries’ &amp;c.). <span class=\"citation\">Y. B. Kam. V, end 5ᵃ</span> <span dir=\"rtl\">אֲוַוז ים וא׳ יישוב וכ׳</span> the water goose (bernicle) and the domestic goose are two diff. species <a href=\"#\" data-headword=\"כִּלְאַיִם\">(כלאים</a>); <span class=\"citation\">Y. Kil. VIII, 31ᶜ</span> bot. <span dir=\"rtl\">א׳ עם א׳ מדבר וכ׳</span> the (domestic) goose and the goose of the steppes (wild g.); <span dir=\"rtl\">א׳ עם א׳ הים</span> the domestic and the water goose; <span class=\"citation\">B. Kam. 55ᵃ</span> <span dir=\"rtl\">א׳ וא׳ הבר</span> (Ms. M. marg. <span dir=\"rtl\">אֲוַוז בית וא׳ בר</span>) the domestic and the wild g.; <span class=\"citation\">Bekh. 8ᵃ</span></div>","alt":[]},"578":{"h":"אַוְוזָא","r":"A00578","html":"<div class=\"sense\"> <span class=\"citation\">Git. 86ᵃ</span>.—בר א׳ <i>duck</i>. <span class=\"citation\">Bets. 33ᵃ</span>. Pl. <span dir=\"rtl\">אֲוָוזִין</span>, <span dir=\"rtl\">אַוְוזֵי</span>. Targ. II Esth. III, 8. <span class=\"citation\">Pes. 114ᵃ</span>. <span class=\"citation\">B. Bath. 73ᵇ</span>. <span class=\"citation\">Ḥull. 56ᵇ</span> <span dir=\"rtl\">הנהו א׳ דידן וכ׳</span> our (Babylonian) geese are considered as water fowls.</div>","alt":["אֲוָוזָא"]},"579":{"h":"אֲוַול","r":"A00579","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲוַל\">אֲוַל</a></div>","alt":["אַוְולָא"]},"580":{"h":"אוולם","r":"A00580","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אַבְלַס\">אַבְלַס</a></div>","alt":["אוולס"]},"581":{"h":"אָוֶון","r":"A00581","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אָוֶן\">אָוֶן</a></div>","alt":[]},"582":{"h":"אַוָּונָא","r":"A00582","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַוָּונָא\">אַוְנָא</a> a. <a href=\"#\" data-headword=\"אוּדְנָא II\"><span dir=\"rtl\">אוּדְנָא</span> II</a></div>","alt":["אַוְונָא"]},"583":{"h":"אֲוַונְכַּר","r":"A00583","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲוַונְכַּר\">אֲוַנְכַּר</a></div>","alt":[]},"584":{"h":"אֶוְוסוֹס","r":"A00584","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹבִיסוֹס\">אוֹבִיסוֹס</a></div>","alt":[]},"585":{"h":"אווקי","r":"A00585","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אוקיי\">אוקיי</a></div>","alt":[]},"586":{"h":"*אַוְורָא","r":"A00586","html":"<p class=\"morphology\">m.</p><div class=\"sense\">; pl. <span dir=\"rtl\">אַוְורֵי</span> (<a href=\"#\" data-headword=\"אוֹר\">אֲוַר</a> dial. for <a href=\"#\" data-headword=\"עֵבֶר I\">עבר</a>, v. Nœld. Mand. Gr. p. 48 sq.; v. Ar. s. v. where <span dir=\"rtl\">אוברים</span> = <span dir=\"rtl\">עוברים</span> [not <span dir=\"rtl\">אובדים</span> as in ed. Koh.] is twice used to account for the etymol. of our w.) <i>crossers of rivers, travelers</i>. <a href=\"#\" data-headword=\"*אֶבְיוֹנֵי\">בֵּי א׳</a> </div><div class=\"sense\"><b>1)</b> <i>crossing, ford</i>. <span class=\"citation\">B. Mets. 103ᵇ</span> אריסא עביד בי א׳ Ar. (ed. <span dir=\"rtl\">בי יאורי</span>; Ms. H. <span dir=\"rtl\">בי אוריא</span>, marg. <span dir=\"rtl\">יאורי</span>) the tenant must entertain the crossings (of the dykes, ed. <i>the channels</i>) in the farm. <span class=\"citation\">M. Kat. 28ᵇ</span> רהיט ונפיל בי א׳ ואמברי יזיפתא יזיף Ar. (ed. <span dir=\"rtl\">ונפיל אמעברא ויזיפתא וכ׳ …</span>, Ms. M. <span dir=\"rtl\">ונפיל בר זיירא אמברא …</span>, v. Rabb. D. S. a. l. note) one runs and rushes to the ford, and on the ferry he makes a loan (to pay the ferry-man; allegory of man’s carelessness in providing for the life to come).</div><div class=\"sense\"><b>—2)</b> <i>among the crossing passengers</i>. Ib. (according to a second interpretation, v. Ar. s. v.) one runs and rushes among those ready to cross (mortals) &amp;c. Cmp. <a href=\"#\" data-headword=\"עֵיבַר II\">עִיבְּרָא</a> <span class=\"citation\">B. Bath. 91ᵃ</span> bot.</div>","alt":[]},"587":{"h":"אֲוַורְדִּימָס","r":"A00587","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"וַרְדִּימוֹס\">וַרְדִּימוֹס</a></div>","alt":[]},"588":{"h":"אוורוס","r":"A00588","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אִבְרוֹסִי\">אִבְרוֹסִי</a></div>","alt":[]},"589":{"h":"*אַוְורַקְסִין","r":"A00589","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"אַפְקַרְסִין\">אפקרסין</a>, a. <a href=\"#\" data-headword=\"אַבְרְקִין\">אַבְרְקִין</a>) <i>trowsers</i>. <span class=\"citation\">Targ. Y. I Ex. XXVIII, 42</span>, a. <span class=\"citation\">Targ. Y. II, Ex. XXVIII, 42</span>; <span class=\"citation\">Targ. Y. I Ex. XXXIX, 28</span> <span dir=\"rtl\">אוורקסי</span>. Ib. <span class=\"citation\">Lev. VI, 3</span> (ed. Vien. <span dir=\"rtl\">אורקטין</span>, II <a href=\"#\" data-headword=\"אברסקין\">אברסקין</a>). <span class=\"citation\">Ib. XVI, 4</span>. [For <span dir=\"rtl\">וו</span> = <a href=\"#\" data-headword=\"פ\">פ</a> v. <a href=\"#\" data-headword=\"אֶוְושַׁר\">אֶוְושַׁר</a>.]</div>","alt":["אברסקין"]},"590":{"h":"אַוְורַשְׁנָא","r":"A00590","html":"<div class=\"sense\">(ed. <span dir=\"rtl\">אוּרְשִׁינָה</span>) m. name of a <i>mythical bird, Phœnix</i>. <span class=\"citation\">Snh. 108ᵇ</span></div>","alt":[]},"591":{"h":"אַוַּושׁ","r":"A00591","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲוַשׁ\">אֲוַשׁ</a></div>","alt":[]},"592":{"h":"אֶוְושַׁר","r":"A00592","html":"<div class=\"sense\">= <a href=\"#\" data-headword=\"אֶפְשַׁר\">אֶפְשַׁר</a> <span class=\"citation\">Targ. Y. I Gen. XVIII, 2</span>; <span class=\"citation\">17</span>; a. e.</div>","alt":["אֶוְשַׁר"]},"593":{"h":"אֶוְותִּיאוֹס","r":"A00593","html":"<div class=\"sense\"> (εὐθέως) <i>forthwith, immediately after.</i> <span class=\"citation\">Nidd. II, 2</span> (<span class=\"citation\">14ᵃ</span>) <span dir=\"rtl\">נמצא על שלה א׳</span> Ar. (ed. <a href=\"#\" data-headword=\"אותיום\">אותיום</a>, corr. acc.) if a stain is found on her bedclothes immediately after (the coïtion). Ib. 12ᵇ; 14ᵇ איזהו שיעור אוו׳ Ar. ed. Koh. (ed. <span dir=\"rtl\">ותס</span>, <a href=\"#\" data-headword=\"וֶסֶת\">וסת</a>, corr. acc.) what is the interval designated by <i>evthios?</i> <span class=\"citation\">Y. Nidd. II, 49ᵈ</span> bot. repeatedly <a href=\"#\" data-headword=\"היותאיוס\">הֶיוְתִּיאוֹס</a> or <a href=\"#\" data-headword=\"הַוָּן\">הֶוְו׳</a>.</div>","alt":["אֶוְתִּיוֹס","(אותיום)"]},"594":{"h":"אוותיננייה","r":"A00594","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַוותֶּנְטְיָא\">אוותנטיא</a></div>","alt":[]},"595":{"h":"*אַוְותָּן","r":"A00595","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= h. <a href=\"#\" data-headword=\"אֵיתָן\">אֵיתָן</a>, r. <span dir=\"rtl\">אית</span>) <i>full, proud, bright</i>. <span class=\"citation\">Targ. Job XXXI, 26</span> Ms. (ed. <a href=\"#\" data-headword=\"זִיוְתָן\">זִיוְתָן</a>).—Pl. <span dir=\"rtl\">אִיוְתָּנַיָּא</span> <span class=\"citation\">Ib. IX, 13</span> (ed. Buxt. a. oth. <span dir=\"rtl\">גֵּיוְתָנַיָּא</span>)</div>","alt":["אִיוְתָּן"]},"596":{"h":"אוותנטי","r":"A00596","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַוְותֶּנְטִי\">אַוְותֶּנְטִין</a></div>","alt":[]},"597":{"h":"אַוותֶּנְטְיָא","r":"A00597","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (αὐθεντία) <i>origin, reality;</i> v. next w.—<span dir=\"rtl\">עיקר א׳</span> the <i>very reality, virtuality</i>. <span class=\"citation\">Gen. R. s. 25</span> <span dir=\"rtl\">עיקר א׳ וכ׳</span> the real famine was destined to be in the days of Saul. <span class=\"citation\">Cant. R. to I, 1</span> <span dir=\"rtl\">עיקר א׳ וכ׳</span> the real, authentic, among the several names of Solomon &amp;c. <span class=\"citation\">Koh. R. to I, 1</span> <span dir=\"rtl\">אית׳</span> (corr. acc.). <span class=\"citation\">Num. R. s. 10</span> <a href=\"#\" data-headword=\"אוותיננייה\">אוותיננייה</a> (corr. acc.).</div>","alt":["אַוְתֶּ׳","אַוְותֶּנְטְיָיה"]},"598":{"h":"אַוְותֶּנְטִי","r":"A00598","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (αὐθέντης) <i>originator, author</i>. <span class=\"citation\">Gen. R. s. 16</span> <span dir=\"rtl\">פרת א׳ של וכ׳</span> the Euphrates is the originator (ultimate source) of the rivers (mentioned <span class=\"citation\">Gen. II, 10</span> sq.).—Pl. m. <a href=\"#\" data-headword=\"אַוְותֶּנְטִי\">אַוְותֶּנְטִין</a>. Y’lamd. to Num. XI, 16 (quot. in Ar. s. v. <span dir=\"rtl\">אמתנטין</span>) <span dir=\"rtl\">כנגד אפת׳ של ישראל וכ׳</span> (corr. <span dir=\"rtl\">אוו׳</span>) corresponding to the number of the originators of Israel, for with seventy souls &amp;c.—Fem. <span dir=\"rtl\">אַוְותֶּנְטִיֹּות</span>, <span dir=\"rtl\">אַוְותֶּנְטִיאוֹת</span>. Pesik. Sh’kal. p. 16ᵇ <span dir=\"rtl\">אומות א׳</span> (seventy) original nations.</div>","alt":["(אפתנטי)"]},"599":{"h":"אוּזְיָא","r":"A00599","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (√<span dir=\"rtl\">אז</span>, v. <a href=\"#\" data-headword=\"אֲזַד\">אֲזַד</a>; cmp. <a href=\"#\" data-headword=\"קָצָה\">קָצֶה</a>) <i>a piece</i>, <i>part, uzya</i>, a market term for a certain portion (quarter &amp;c.) of meat. <span class=\"citation\">Bets. 29ᵃ</span> in Pumb. they call it <span dir=\"rtl\">א׳ ופלגא א׳</span> Ms. M. (ed. <span dir=\"rtl\">ופלגו א׳</span> corr. acc.; Var. <a href=\"#\" data-headword=\"אוסיא\">אוסיא</a>) an uzya and half an uzya.</div>","alt":["*(אוּסְיָא)"]},"600":{"h":"אוּזִילָא","r":"A00600","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוּרְזִילָא\">אוּרְזִילָא</a></div>","alt":[]},"601":{"h":"אוּזִילְתָּא","r":"A00601","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיזְלָא\">אִיזְלָא</a></div>","alt":[]},"602":{"h":"*אוּזִּינְקָא","r":"A00602","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <span dir=\"rtl\">אונז׳</span>; <span dir=\"rtl\">נזק</span>, v. <a href=\"#\" data-headword=\"*אַנְזִיקָא\">אַנְזִיקָא</a>) (<i>compensation for</i>) <i>loss, expense</i> of money and time. <span class=\"citation\">B. Bath. 6ᵇ</span> <span dir=\"rtl\">שקול א׳ וכ׳</span> (Ms. R. <span dir=\"rtl\">עבדיה כוליה ויהיבנא לך א׳</span></div>","alt":[]},"603":{"h":"אוּזְלָא","r":"A00603","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיזְלָא\">אִיזְלָא</a></div>","alt":["אוּזַלְתָּא"]},"604":{"h":"*אוּזְמְיָאוֹת","r":"A00604","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זְמֵי I\">זמי</a>, <span dir=\"rtl\">יזם</span>; comp. <a href=\"#\" data-headword=\"זְמָם I\">זְמָם</a>, <a href=\"#\" data-headword=\"צָמַם\">צמם</a>) <i>knots, fringes</i> (in the weaver’s work). <span class=\"citation\">Tosef. Kel. B. Bath. ch. V</span>, end <span dir=\"rtl\">שְׁיָרֵי … והא׳</span> the remnants &amp;c. and the fringes (cut off for finishing).</div>","alt":[]},"605":{"h":"אוּזְמֵל","r":"A00605","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיזְמֵיל\">אִיזְמֵל</a></div>","alt":[]},"606":{"h":"אוֹזֶן","r":"A00606","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֹזֶן\">אֹזֶן</a></div>","alt":[]},"607":{"h":"אוּזְנָא","r":"A00607","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹדֶן\">אוּדְנָא</a></div>","alt":[]},"608":{"h":"*אוּזְנִיֹּות","r":"A00608","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (?) pl. (= <span dir=\"rtl\">חזניות</span>, v. <a href=\"#\" data-headword=\"חִזָּיוֹן I\">חִזָּיוֹן</a> 2, a. <a href=\"#\" data-headword=\"חָזִיז\">חָזִיז</a>; cmp. <a href=\"#\" data-headword=\"אֶבְיוֹנוּת\">אֶבְיוֹנוֹת</a> = <span dir=\"rtl\">חֶבְיוֹנוֹת</span>) <i>lichen-dishes</i>. <span class=\"citation\">Tosef. Shebi. VII, 13</span>. [El. Wil. emends <span dir=\"rtl\">אהיניות</span> = <span dir=\"rtl\">אהיני</span> whereas the context intimates a vegetable.]</div>","alt":["אָזְנִיֹּות"]},"609":{"h":"אוֹזָפוּתָא","r":"A00609","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">יזף</span>) <i>loan</i>. <span class=\"citation\">Targ. Y. Deut. XV, 2</span>.</div>","alt":[]},"610":{"h":"*(אוזפיה)","r":"A00610","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (= <span dir=\"rtl\">זיפין</span>, v. <a href=\"#\" data-headword=\"יִזַף\">זִיף</a>) <i>a species of bees, wasps</i>. <span class=\"citation\">Targ. Y. Lev. XI, 20</span>.</div>","alt":["אוֹזְפֵי"]},"611":{"h":"אוזרד","r":"A00611","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"(עוּזְרָד\">עוּזְרָר</a> a. <a href=\"#\" data-headword=\"חִיזְרָר\"><a href=\"#\" data-headword=\"חִיזְרָר\">חִיזְרָר</a>.</a></div>","alt":[]},"612":{"h":"*אוֹחֲדָנָא","r":"A00612","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">אחד</span> = <a href=\"#\" data-headword=\"אָחַז\">אחז</a>) <i>possession, power</i> (h. <a href=\"#\" data-headword=\"חֹסֶן\">חֹסֶן</a>). <span class=\"citation\">Targ. Prov. XXVII, 24</span> (ed. corrupt <span dir=\"rtl\">אחרנא</span>; ed. Walt. <a href=\"#\" data-headword=\"אַחְסָנָא\">אַחֲסָנָא</a>).</div>","alt":[]},"613":{"h":"אוֹחַדְתָּא","r":"A00613","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"*אוֹחֲדָנָא\">foreg.</a>) prop. <i>locking up</i>, hence, <i>trap, snare</i>. <span class=\"citation\">Targ. Job. XVIII, 10</span>.</div>","alt":[]},"614":{"h":"אוּחַדְתָּא","r":"A00614","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>enigma, epigram</i>. <span class=\"citation\">Targ. Ps. XLIX, 5</span> (Ms. <span dir=\"rtl\">אחדותא</span>).</div>","alt":["(אוֹחַדְתָּא)"]},"615":{"h":"אוֹחִיִין","r":"A00615","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"><i>howling animals, owls</i> &amp;c. <span class=\"citation\">Targ. Is. XIII, 21</span>.</div>","alt":[]},"616":{"h":"אוֹחֲרִי","r":"A00616","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲחוֹרִי\">אֲחוֹרִי</a></div>","alt":[]},"617":{"h":"אוֹחֲרַיָא","r":"A00617","html":"<div class=\"sense\"> c. (<span dir=\"rtl\">אחר</span>) <i>last, outmost</i>. Targ. Y. II. <span class=\"citation\">Lev. XIX, 9</span>; v. <a href=\"#\" data-headword=\"אוֹמַן\">אוֹמַן</a>.</div>","alt":[]},"618":{"h":"אוּחֲרָן","r":"A00618","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אָחֳרָן\">אָחֳרָן</a></div>","alt":["אוּחֲרָנָא","אוּחֲרַנְתָּא"]},"619":{"h":"אוֹטָבוּתָא","r":"A00619","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">יטב</span>) <i>doing good, propriety</i>. <span class=\"citation\">Targ. Koh. IV, 4</span>.</div>","alt":[]},"620":{"h":"אוטימוס","r":"A00620","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֱטִימוֹס\">אֱטִימוֹס</a></div>","alt":[]},"621":{"h":"אוטיפיטא","r":"A00621","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַנְטִיפִּיטָא\">אַנְטִיפִּיטָא</a></div>","alt":[]},"622":{"h":"אוֹטֶם","r":"A00622","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אָטַם\">אטם</a>) </div><div class=\"sense\"><b>1)</b> <i>obstruction; something closed, plugged up</i>. <span class=\"citation\">Ḥull. 47ᵇ</span> א׳ בריאה Ar. (ed. <span dir=\"rtl\">אָטוּם</span>) an obstruction in the lungs, a spot imperviable to air when blown up. Ohol. VI, 5 we regard the levitical uncleanness between the rafters <span dir=\"rtl\">כאילו הוא א׳</span> as if it was locked up (and could not affect what is in the house).</div><div class=\"sense\"><b>—2)</b> <i>substructure</i> (filled with earth), <i>foundation.</i> Mid. IV, 6. <span class=\"citation\">Par. III, 6</span>.</div>","alt":[]},"623":{"h":"אוטם","r":"A00623","html":"<div class=\"sense\"> <span class=\"citation\">Tosef. Kil. III, 14</span> ed. Zuck., v. <a href=\"#\" data-headword=\"אִיטָּן\">אִיטָּן</a></div>","alt":[]},"624":{"h":"אוטנס","r":"A00624","html":"<div class=\"sense\"> <span class=\"citation\">Ab. Zar. 39ᵃ</span>, v. <a href=\"#\" data-headword=\"אֲטוּנָס\">אֲטוּנָס</a></div>","alt":[]},"625":{"h":"אוטפיטא","r":"A00625","html":"<div class=\"sense\"> <span class=\"citation\">Koh. R. to XI, 1</span>, read <a href=\"#\" data-headword=\"אַנְטִיפִּיטָא\">אנטיפיטא</a>.</div>","alt":[]},"626":{"h":"אוי","r":"A00626","html":"<div class=\"sense\"> , <i>Pi.</i> אִיוָּה <i>to desire, covet</i>. <span class=\"citation\">Snh. 63ᵃ</span> <span dir=\"rtl\">אִיוּוּ אלוהות וכ׳</span> (<span class=\"citation\">Ab. Zar. 53ᵇ</span> <span dir=\"rtl\">לאלוהות</span>, v. Rabb. D. S. a. l. note 8) they had a desire for many deities. Denom. <a href=\"#\" data-headword=\"תַּאֲוָה\">תַּאֲוָה</a>. Cmp. <a href=\"#\" data-headword=\"אוֹת I\">אוּת</a>.</div><div class=\"sense\"><b>Hithpa. הִתְאַוֶּה</b> <div class=\"sense\"> (b. h.), <i>Nithpa</i>. <a href=\"#\" data-headword=\"אני\">נִתְאַוֶּה</a> (denom. of <a href=\"#\" data-headword=\"תַּאֲוָה\">תַּאֲוָה</a>) <i>to desire, to be seized with a desire</i>. <span class=\"citation\">Num. R. s. 10</span> (play on <span dir=\"rtl\">י̇ת̇א̇ד̇ם̇</span> <span class=\"citation\">Prov. XXIII, 31</span>) the drunken man <span dir=\"rtl\">וכ׳ לד̇ם̇ יִ֗תְ֗אַ֗וֶּה</span> will covet blood (forbidden intercourse). <span class=\"citation\">Gen. R. s. 51</span>. <span class=\"citation\">Ex. R. s. 24</span>, end.—<span class=\"citation\">Num. R. s. 2</span> <span dir=\"rtl\">התחילו מִתְאַוִּים וכ׳</span> they began to express a desire for standards (in imitation of the angelic hosts). Ib. divide them into standards <span dir=\"rtl\">כמו שנִתְאַוּוּ</span> as they desired.</div></div>","alt":["אָוָה I"]},"627":{"h":"אוי ²","r":"A00627","html":"<div class=\"sense\"> , a. Ges. H. Dict. s. v. <a href=\"#\" data-headword=\"אוי ²\"><span dir=\"rtl\">אָוָה</span> III</a>) <i>to point, mark</i>. Denom. <a href=\"#\" data-headword=\"אוֹת II\"><span dir=\"rtl\">אוֹת</span> II</a>, <span dir=\"rtl\">תְּאָו</span>, <a href=\"#\" data-headword=\"תַּאֲוָה\">תַּאֲוָה</a>.</div><div class=\"sense\"><b>Hithpa. הִתְאַוֶּה</b> <div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"תַּאֲוָה\">תַּאֲוָה</a>, <span dir=\"rtl\">תְּאָו</span>) <i>to mark, to mark out</i>. <span class=\"citation\">Koh. R. to XII, 7</span> <span dir=\"rtl\">התחיל מִתְאַוֶּה תאוים</span> he began to put up marks.</div></div>","alt":["אָוָה II"]},"628":{"h":"אוֹי","r":"A00628","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <span dir=\"rtl\">אוי I</span>) [pressure] <i>woe, sorrow</i>. <span class=\"citation\">Gen. R. s. 46</span> <span dir=\"rtl\">בי לא אוי</span> there is no (cause for) woe with me. <span class=\"citation\">Num. R. s. 10</span> (play on <i>ăboy</i>, <span class=\"citation\">Prov. XXIII, 29</span>) <span dir=\"rtl\">אַב אוי</span> father of woe.—2) interj. <i>woe! alas!</i> <span class=\"citation\">Kel. XVII, 16</span>; a. v. fr.</div>","alt":[]},"629":{"h":"אִוְיָא I","r":"A00629","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חִיוֵי\">חִיוְיָא</a>) <i>serpent</i>. <span class=\"citation\">Gen. R. s. 26</span> <span dir=\"rtl\">בגלילא וכ׳</span> in Galilee they call <i>ḥivya, ivya</i></div>","alt":["אִיוְיָא"]},"630":{"h":"אִוְיָא II","r":"A00630","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אִוְיָא I\">foreg.</a>) <i>Ivya</i>, a Babyl. Amora. <span class=\"citation\">B. Bath. 19ᵃ</span> R. Ḥiya son of R. Iv.—<span class=\"citation\">Men. 78ᵃ</span>; a. e.</div>","alt":["אִיוְיָא"]},"631":{"h":"אוֹיִים","r":"A00631","html":"<div class=\"sense\"> pl. of <a href=\"#\" data-headword=\"אוֹ I\"><span dir=\"rtl\">אוֹ</span> I</a>.</div>","alt":["אוֹיִין"]},"632":{"h":"אֱוִילָא","r":"A00632","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲוַל\">אֲוַל</a></div>","alt":[]},"633":{"h":"אוֹיָם","r":"A00633","html":"<div class=\"sense\"> (?) an interjection (cmp. εὔαν, εὖα) <i>ho! hallo!</i> <span class=\"citation\">Y. Ḥag. II, 78ᵃ</span> top; <span class=\"citation\">Snh. V</span>I, 23ᶜ bot. <span dir=\"rtl\">א׳ א׳ פתחון לי וכ׳</span> ho, ho! Open, for I am one of yours.</div>","alt":["אוֹיָים"]},"634":{"h":"אָוִיר","r":"A00634","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אוֹר\">אור</a>; cmp. <a href=\"#\" data-headword=\"רִיחַ\">רוּחַ</a> a. <a href=\"#\" data-headword=\"רָוַח\">רֶוַח</a>); <i>space</i> corresp. to <a href=\"#\" data-headword=\"חָלָל I\">חָלָל</a>, esp. </div><div class=\"sense\"><b>1)</b> <i>open, empty space, blank.</i> Ohol. IV, 1 a tower <span dir=\"rtl\">שעומד בא׳</span> standing isolated. Ib. XVIII, 10 <span dir=\"rtl\">אוירָהּ של חצר</span> the open space in the court-yard.—<span class=\"citation\">B. Bath. 163ᵃ</span></div><div class=\"sense\"><b>—2)</b>  (cmp. b. h. <span dir=\"rtl\">מְאוּרָה</span>) <i>hollow, cavity of a vessel.</i> <span class=\"citation\">Kel. II, 1</span> <span dir=\"rtl\">מיתטמאין ומטמאין בא׳</span> become unclean and make unclean by contact with the hollow (of the vessel).—<span class=\"citation\">Yeb. 67ᵇ</span> <span dir=\"rtl\">נפק לא׳ העולם</span> came forth into the lighted space of the world, i.e. was born; a. fr.</div><div class=\"sense\"><b>—3)</b>  (cmp. ἀήρ, aër) <i>air, atmosphere, climate, weather</i>. <span class=\"citation\">Num. R. s. 14</span> <span dir=\"rtl\">הא׳ שממנו וכ׳</span> (as one of the elements of nature) out of which the wind was made.—<span class=\"citation\">Gen. R. s. 34</span> א׳ יפה <i>fine weather</i>; a. fr.—Pl. <span dir=\"rtl\">אֲוִירִין</span> <i>blank spaces in writings</i>. <span class=\"citation\">B. Bath. 163ᵃ</span>.—אֲוִירוֹת <i>climates</i>. <span class=\"citation\">Gen. R. s. 34</span> <span dir=\"rtl\">ברית נחלקה לא׳</span> a covenant has been made in favor of climates, i.e. God has implanted in man a love of his native soil even in bad climates.</div>","alt":["אֲוִיר"]},"635":{"h":"אָוֵירָא","r":"A00635","html":"<div class=\"sense\"><b>1)</b> <i>empty space, air</i>. <span class=\"citation\">Targ. Y. Ex. XIX, 17</span>; a. fr.—<span class=\"citation\">Git. 20ᵇ</span> <span dir=\"rtl\">א׳ דמגילתא</span> the blank in a scroll (margin &amp;c.). <span class=\"citation\">Men. 35ᵃ</span> <span dir=\"rtl\">חזי א׳</span> to face the inside of the T’fillin.</div><div class=\"sense\"><b>—2)</b> <i>air, weather</i>. <span class=\"citation\">Pes. 30ᵇ</span> <span dir=\"rtl\">שליט בהו א׳</span> the air strikes them. <span class=\"citation\">Y. R. Hash. II, 58ᵃ</span> bot. <span dir=\"rtl\">א׳ מעונן</span> cloudy weather; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>pile of bricks with openings between</i>, v. <a href=\"#\" data-headword=\"אַוָּארָא\">אַוָּארָא</a>.</div>","alt":["אֲוִירָא","אַוֵּיר","אַוֵּירָא"]},"636":{"h":"אוירא","r":"A00636","html":"<div class=\"sense\"> <span class=\"citation\">Y. M. Kat. I, 80ᵇ</span> bot., v. <a href=\"#\" data-headword=\"*אֲיָירָא\">אַיְירָא</a></div>","alt":[]},"637":{"h":"אֲוִירְטָא","r":"A00637","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (averta, ἀβερτή) <i>knapsack</i>.—Pl. <span dir=\"rtl\">אֲוִירְטִין</span>. <span class=\"citation\">Tosef. Kel. B. Bath. IV, 10</span>.</div>","alt":[]},"638":{"h":"*אֲוִירְיָא","r":"A00638","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Avirya</i>. <span class=\"citation\">Shebu. 24ᵇ</span> (v. Rab. D. S. a.).</div>","alt":[]},"639":{"h":"אוֹכָחוּתָא","r":"A00639","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יָכַח\">יכח</a>) <i>reproof</i>. <span class=\"citation\">Targ. Y. I Deut. I, 1</span>; a. e.</div>","alt":["אוֹכַחְתָּא"]},"640":{"h":"אוֹכְטָא","r":"A00640","html":"<div class=\"sense\"><i>eight</i>, v. <a href=\"#\" data-headword=\"אָכְטָא\">אָכְטָא</a>.</div>","alt":[]},"641":{"h":"*אוּכַּיְיפָא","r":"A00641","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כּוּף\">כוף</a>) <i>bending, suppression</i>. <span class=\"citation\">Esth. R. to I, 1</span>ᵇ (ref. to <span class=\"citation\">Lam. III, 13</span> <span dir=\"rtl\">בני אשפתו</span>, the quotation being omitted by clerical error), [read] <span dir=\"rtl\">ר׳ ברכי׳ ורבנן ר׳ בני</span>. <span dir=\"rtl\">ברכי׳ אמר בני אוּכַּיְיפֵיה ורבנן אמרי בני אמורייה אוכייפיה שהיו מרוצין וכ׳</span> <i>B’ne Ashpatho</i> means ‘the children of his pressure’ &amp;c., v. <a href=\"#\" data-headword=\"*אֲמוּרְיָא\">אֲמוּרְיָא</a>.</div>","alt":[]},"642":{"h":"אוכל","r":"A00642","html":"<div class=\"sense\"> <span class=\"citation\">Pes. 53ᵃ</span> <span dir=\"rtl\">של א׳</span>, read <a href=\"#\" data-headword=\"אָבֵל I\">אָבֵל</a>; v. <span class=\"citation\">Tosef. Shebi. VII, 15</span>.</div>","alt":[]},"643":{"h":"אוֹכֶל","r":"A00643","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>food, edible</i>. <span class=\"citation\">Bets. I, 8</span> <span dir=\"rtl\">בורר א׳ ואוֹכֵל</span> (Y. ed. <span dir=\"rtl\">בורר אוכל אוכל</span>) he selects singly what is edible and eats immediately; a. fr.—<span dir=\"rtl\">א׳ נפש</span> the necessary food for the day. <span class=\"citation\">Meg. I, 5</span> <span dir=\"rtl\">אלא א׳ נ׳ בלבד</span> except the preparation of food (cooking &amp;c., permitted on Holy Days, <span class=\"citation\">Ex. XII, 16</span>).—Pl. <span dir=\"rtl\">אוֹכְלִים</span>, <span dir=\"rtl\">אוֹכְלִין</span> <i>food, eatables</i>. <span class=\"citation\">Ber. 50ᵇ</span>; a. fr. <span class=\"citation\">Ab. Zar. 52ᵇ</span> <span dir=\"rtl\">תקרובת ע&quot;ז של א׳</span> an idolatrous offering consisting of edibles; Y. ib. IV, 43ᵈ <span dir=\"rtl\">אֹכְ׳</span>.</div>","alt":[]},"644":{"h":"אוּכְלָא I","r":"A00644","html":"<div class=\"sense\"></div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"אוֹכֶל\">same</a>. <span class=\"citation\">Targ. Ps. LXXVIII, 18</span> (Ms. <a href=\"#\" data-headword=\"מֵיכַל\">מֵיכְלָא</a>).—<span class=\"citation\">Yoma 80ᵇ</span> <span dir=\"rtl\">כל אכשורי א׳ א׳ הוא</span> whatever is used for seasoning food, is considered as food.</div><div class=\"sense\"><b>—2)</b> <i>the digested food found in the entrails, excrements</i>, cmp. <a href=\"#\" data-headword=\"רעי\">רעי</a>.—<span class=\"citation\">Targ. Lev. I, 16</span>; a. e.</div><div class=\"sense\"><b>—3)</b> <i>an eye-disease, itching</i> (cmp. <a href=\"#\" data-headword=\"חוּרְשָׁא\">חוּרְשָׁא</a>). <span class=\"citation\">Ab. Zar. 28ᵇ</span> <span dir=\"rtl\">תחלת א׳</span> the incipiency of &amp;c., <span dir=\"rtl\">סוף א׳</span> last stage (near recovery).</div>","alt":[]},"645":{"h":"אוּכְלָא II","r":"A00645","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אֲכַל\">אכל</a> = <a href=\"#\" data-headword=\"כּוּל\">כּוּל</a>) prop. <i>measure</i>, hence (cmp. <a href=\"#\" data-headword=\"כַּיְילָא\">כַּיְילָא</a>) </div><div class=\"sense\"><b>1)</b> <i>a certain measure, Ukhla</i>, (basket); cmp. <a href=\"#\" data-headword=\"*כְּלָה\">כְּלָה</a>.—<span class=\"citation\">Y. Sot. I, 17ᵃ</span> <span dir=\"rtl\">תומן וחצי ת׳ וא׳</span> one Tuman (one eighth of a kab), and half a T. and one Ukhla; cmp. <a href=\"#\" data-headword=\"עוּכְלָא\">עוּכְלָא</a>.</div><div class=\"sense\"><b>—2)</b> <i>basket</i>, v. <a href=\"#\" data-headword=\"אוּבְלָא II\"><span dir=\"rtl\">אוּבְלָא</span> II</a>.</div>","alt":[]},"646":{"h":"אוֹכְלָה","r":"A00646","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אָכְלָה I\">אָכְלָה</a></div>","alt":[]},"647":{"h":"אוֹכְלוֹזא","r":"A00647","html":"<div class=\"sense\"> (perh. fr. r. <span dir=\"rtl\">כלז</span>, cmp. Arab. ḳalaza, <i>collegit</i>, a. <span dir=\"rtl\">כרז</span>, <a href=\"#\" data-headword=\"קָלַס I\">קלס</a>; v. Ges. H. Dict. s. v. <span dir=\"rtl\">כרשׂ</span>; var. forms: <a href=\"#\" data-headword=\"אָכְלוֹזָא\">אָכְלוֹזָא</a>, <span dir=\"rtl\">אוֹכְלוֹסָא</span>, <span dir=\"rtl\">אוֹכְלָסָא</span>, <a href=\"#\" data-headword=\"כְּלוֹזָא\">כְּלוֹזָא</a>; h. form only in pl. <span dir=\"rtl\">אוֹכְלוֹסִין</span>, const. <span dir=\"rtl\">אוֹכְלוֹסֵי</span>, <span dir=\"rtl\">אוֹכְלָסִין</span>) <i>levy of troops</i> or <i>forced laborers</i> (corresp. to h. <a href=\"#\" data-headword=\"צָבָא\">צָבָא</a>). <span class=\"citation\">Targ. I Chr. XI, 6</span>; <span class=\"citation\">XX, 1</span>.—<span class=\"citation\">B. Bath. 8ᵃ</span>; <span class=\"citation\">B. Mets. 108ᵃ</span> <span dir=\"rtl\">נפקי בא׳</span> (Ms. M. <a href=\"#\" data-headword=\"כְּלוֹזָא\">כלוזא</a>) they have to go out themselves to do public labors (not permitted to hire substitutes). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">לאו בני א׳ וכ׳</span> are exempt from the levy. <span class=\"citation\">Ber. 58ᵃ</span>; <span class=\"citation\">Yeb. 76ᵇ</span> <span dir=\"rtl\">יצא בא׳</span> went out with the army; [strike out <span dir=\"rtl\">ודרש בא׳</span> Ber. l. c., v. Rabb. D. S. a. l. note 40]; a. fr.—Pl. <span dir=\"rtl\">אוֹכְלוֹזִין</span>, <span dir=\"rtl\">אוֹכְלוֹסִין</span>, <span dir=\"rtl\">אוֹכְלָסִין</span> (v. supra). <span class=\"citation\">Targ. I Chr. XII, 22</span>; a. fr.—Tosef. Ber. VII (VI), 2 <span dir=\"rtl\">אוכלסין</span>. <span class=\"citation\">Ber. 58ᵃ</span>; <span dir=\"rtl\">אוֹכְלוֹסֵי ישראל</span> a Jewish army. Y. Ber. IX, 13ᶜ top.; Y. Snh. X, 29ᵇ top. … <span dir=\"rtl\">אוֹכלוֹסַיָּיא ד</span> the armies of students; a. fr.—Cmp. <a href=\"#\" data-headword=\"*אָכְלוֹשֵׂי\">אָכְלוֹשֵׁי</a>. [Y. Ber. IX, 13ᵃ; <span class=\"citation\">Midr. Till. to Ps. IV</span>, v. <a href=\"#\" data-headword=\"אִסְכּוֹלִי\">אִסְכֹּולִי</a>].</div>","alt":[]},"648":{"h":"אוּכָּם","r":"A00648","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אָכַם\">אכם</a>) <i>black, dark-complected, freckled, ungainly</i>. <span class=\"citation\">Targ. Lev. XIII, 31</span>; a. fr.—<span class=\"citation\">Pes. 88ᵃ</span>.—<span class=\"citation\">M. Kat. 9ᵇ</span> הוה ליה ברתא א׳ Ms. M. (ed. our w. omitted) had an ungainly (freckled) daughter; <span class=\"citation\">Sabb. 80ᵇ</span>. Git. 67ᵇ <span dir=\"rtl\">תרנגולתא אוּכַּמְתִּי</span> a black (checkered?) hen. <span class=\"citation\">Ib. 68ᵃ</span><span class=\"citation\">Git. 67ᵇ</span> <span dir=\"rtl\">תרנגולתא אוּכַּמְתִּי</span> a black (checkered?) hen. <span class=\"citation\">Ib. 68ᵃ</span> <span dir=\"rtl\">אוכמא בחיורא</span> a black spot on a white skin. Pl. masc. <span dir=\"rtl\">אוּכָּמִין</span>, <span dir=\"rtl\">אוּכָּמֵי</span>, <span dir=\"rtl\">אוּכָּמַיָּא</span>, <span dir=\"rtl\">אוּכְמַיָּא</span>. <span class=\"citation\">Targ. Jer. VIII, 21</span>; a. e.—<span class=\"citation\">Ḥull. 46ᵇ</span> <span dir=\"rtl\">א׳ א׳</span> covered with black spots.—Fem. <span dir=\"rtl\">אֻכָּמָתָא</span> <span class=\"citation\">Sabb. 129ᵃ</span>. <span class=\"citation\">Ib. 20ᵇ</span> אוכמוותא Ar. (ed. <span dir=\"rtl\">אוכמתא</span>) the black (greenish) moss on ships or puddles.</div>","alt":["אוּכָּמָא","אוּכָּמָא","אוּכַּמְתָּא"]},"649":{"h":"אוּכְמָא","r":"A00649","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אוּכָּם\">foreg.</a>) <i>black color, darkness; distress</i>. <span class=\"citation\">Targ. Y. Lev. XXII, 22</span>. <span class=\"citation\">Targ. Lam. IV, 8</span>.</div>","alt":["אוּכְמְתָא"]},"650":{"h":"אוּכָּמוּתָא","r":"A00650","html":"<div class=\"sense\"> f. <a href=\"#\" data-headword=\"אוּכְמָא\">same</a>. <span class=\"citation\">Targ. Koh. XI, 10</span> dark hair, youth.</div>","alt":[]},"651":{"h":"אוכמנא","r":"A00651","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוּסְמָנָא\">אוּסְמָנָא</a></div>","alt":[]},"652":{"h":"אוּכַּמְתָּא","r":"A00652","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוּכָּם\">אוּכָּמָא</a>, <a href=\"#\" data-headword=\"אוּכְמָא\"><a href=\"#\" data-headword=\"אוּכְמָא\">אוּכְמָא</a>.</a></div>","alt":["אוּכְמְתָא"]},"653":{"h":"*אוּכַּמְתִּי","r":"A00653","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוּכָּם\">אוּכָּמָא</a></div>","alt":[]},"654":{"h":"אוּכָּף","r":"A00654","html":"<div class=\"sense\"> c. (<a href=\"#\" data-headword=\"אָכַף\">אכף</a>) <i>saddle.</i> <span class=\"citation\">Kel. XXIII, 1</span>; <span class=\"citation\">2</span>; a. e.—<span class=\"citation\">Y. Sabb. V, 7ᵇ</span> bot. <a href=\"#\" data-headword=\"*אימיקנטרון\">או׳</a> a. <a href=\"#\" data-headword=\"אִסְקְרִיטִין\">אי׳</a>.—<span class=\"citation\">Y. Erub. I, 19ᵇ</span> bot. <span dir=\"rtl\">בין אי׳ לאי׳</span>; Bab. <span class=\"citation\">Erub. 16ᵃ</span> <span dir=\"rtl\">בין או׳ לאו׳</span>. <span class=\"citation\">Sabb. 53ᵃ</span>.—Pl. <span dir=\"rtl\">אוּכָּפוֹת</span>. <span class=\"citation\">Erub. 15ᵇ</span> ed. (Ar. <span dir=\"rtl\">אִכּוּפִין</span>). Y. Erub. l. c. <span dir=\"rtl\">אִיכּוּפִין</span>.</div>","alt":["אִיכּוּף"]},"655":{"h":"אוּכָּפָא","r":"A00655","html":"<div class=\"sense\"><span class=\"citation\">B. Mets. 27ᵇ</span>. <span class=\"citation\">B. Kam. 92ᵇ</span> (prov.) <span dir=\"rtl\">חברא קרייך חמרא א׳ וכ׳</span> if thy neighbor calls thee an ass, put a saddle on. <span class=\"citation\">Erub. 27ᵃ</span> <span dir=\"rtl\">גבא דא׳</span> the upper part of the saddle (Ar., besides other var., <span dir=\"rtl\">גברא דא׳</span> man’s figure on the upper part of the saddle) used as a handle by the rider.</div>","alt":[]},"656":{"h":"אוכפייה","r":"A00656","html":"<div class=\"sense\"> <span class=\"citation\">Esth. R. to I, 1</span>ᵇ <span dir=\"rtl\">(<span dir=\"rtl\">איכ׳</span>) <span dir=\"rtl\">בני או׳</span></span>, v. <a href=\"#\" data-headword=\"*אוּכַּיְיפָא\">אוּכַּיְיפָא</a></div>","alt":[]},"657":{"h":"אוכצנא","r":"A00657","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוּבְצָנָא\">אוּבְצָנָא</a></div>","alt":[]},"658":{"h":"אֲוַל","r":"A00658","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (אול <i>to circle</i>, v. <a href=\"#\" data-headword=\"חוּל\">חוּל</a>, <span dir=\"rtl\">עול</span>, cmp. <a href=\"#\" data-headword=\"עוֹלָם\">עוֹלָם</a>, <a href=\"#\" data-headword=\"תְּחִלָּה\">תְּחִלָּה</a>) <i>beginning, early season</i>. <span class=\"citation\">Targ. Hos. IX, 10</span>; a. e.—<span dir=\"rtl\">מן א׳</span> from the beginning (of the world). <span class=\"citation\">Targ. Job. XX, 4</span>; a. fr.—לאויל <i>to</i> (<i>its</i>) <i>previous condition</i>. <span class=\"citation\">Targ. Ez. XVI, 55</span> (some ed. <span dir=\"rtl\">לְאַוְלְהַן</span>). Cmp. <span dir=\"rtl\">אלל</span>.</div>","alt":["אָוָול","(אֲוַול)","אֱוִילָא"]},"659":{"h":"אוּלְבָּנָא","r":"A00659","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, pl. <a href=\"#\" data-headword=\"*אוּרְבָּנִין\">אוּלְבָּנִין</a> (denom. of <a href=\"#\" data-headword=\"לְבוּנְתָּא\">לְבוּנְתָּא</a>) <i>unguent made of incense</i>. <span class=\"citation\">Targ. Cant. IV, 11</span>; (h. text <a href=\"#\" data-headword=\"לְבָנוֹן\">לבנון</a>, LXX ἀρώματα, as if <a href=\"#\" data-headword=\"לִבְנִין\">לְבֹנִין</a>).</div>","alt":[]},"660":{"h":"*אוֹלָד","r":"A00660","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">ולד</span>, <span dir=\"rtl\">ילד</span>) <i>a tool for hollowing out and cutting the writing reed</i> (scalprum), a sort of <i>pen-knife</i>. Tosef. Kel. B. Bath. end. <span class=\"citation\">Kel. XII, 8</span> <a href=\"#\" data-headword=\"אולר\">אולר</a> (corr. acc.; v. Ar. ed. Koh. s. v.).</div>","alt":[]},"661":{"h":"אוֹלוֹ־","r":"A00661","html":"<div class=\"sense\"> (ὅλο-) a prefix, sometimes separately printed, <i>whole, entirely of</i>. Pesik. Vay. B’yom p. 4ᵇ <span dir=\"rtl\">א׳ מרגליטין</span> trimmed all over with pearls. <span class=\"citation\">Lev. R. s. 32</span>, end <span dir=\"rtl\">אילו כורסין</span> (corr. acc.) all gold, v. <a href=\"#\" data-headword=\"אוֹלוֹכְרוּסוֹן\">אוֹלוֹכְרוּסוֹן</a>.</div>","alt":[]},"662":{"h":"אולוגלוגין","r":"A00662","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֵילוֹגִין\">אִילוֹגִין</a></div>","alt":[]},"663":{"h":"אולוותא","r":"A00663","html":"<div class=\"sense\"> <span class=\"citation\">Y. Taan. III, 66ᶜ</span> top, read <span dir=\"rtl\">מוּלְוָותָא</span>, v. <a href=\"#\" data-headword=\"מוּלָא I\">מוּלָא</a><i>mule</i>.</div>","alt":[]},"664":{"h":"אולוכורסין","r":"A00664","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹלוֹכְרוּסוֹן\">next w.</a></div>","alt":[]},"665":{"h":"אוֹלוֹכְרוּסוֹן","r":"A00665","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ὁλόχρυσον) <i>all gold</i>. <span class=\"citation\">Lev. R. s. 32</span> (variously corrupted, v. <a href=\"#\" data-headword=\"אוֹלוֹ־\">אוֹלוֹ־</a>.—Ar. <span dir=\"rtl\">אולון כרוסא</span>); <span class=\"citation\">Cant. R. to IV, 7</span> (corr. acc.).</div>","alt":[]},"666":{"h":"אוֹלוֹן","r":"A00666","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹלוֹכְרוּסוֹן\">foreg.</a></div>","alt":[]},"667":{"h":"אוֹלוֹסֵירִיקָא","r":"A00667","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ὁλοσήρικος) <i>all silk.</i> <i>—</i> Pl. <span dir=\"rtl\">אוֹלוֹסֵירִיקִין</span>, mostly <span dir=\"rtl\">אוֹלוֹסְרִיקִין</span> <i>pure-silken garments</i>. <span class=\"citation\">Koh. R. to I, 7</span>. <span class=\"citation\">Y. Sabb. VI, 8ᵇ</span> bot., <span class=\"citation\">Yalk. Prov. 935</span>.—[Koh. R. l. c. second time some ed. <a href=\"#\" data-headword=\"אוֹלוֹסְרִיקָא\">אולוסתיקין</a>, corr. acc.]</div>","alt":[]},"668":{"h":"אוֹלוֹסְרִיקָא","r":"A00668","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹלוֹסֵירִיקָא\">foreg.</a></div>","alt":["אולוסתיקין"]},"669":{"h":"אולורין","r":"A00669","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹלְיָאר\">אוֹלְיָיר</a></div>","alt":[]},"670":{"h":"אוליאוס","r":"A00670","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אִילִיאוֹס\">אִילִיאוֹס</a></div>","alt":[]},"671":{"h":"אוֹלְיָאר","r":"A00671","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (olearius, ὀλεάριος S.) <i>keeper of clothes at the baths</i>. <span class=\"citation\">Y. Maas. Sh. I, 52ᵈ</span> top <span dir=\"rtl\">מעות הנתונות לא׳</span> tokens (in place of small change) given to the olearius; cmp. <span class=\"citation\">Tosef. Maas. Sh. I, 4</span>.—<span class=\"citation\">Pesik. R. s. 22</span>; a. e.—Pl. <span dir=\"rtl\">אוֹלְיָארִין</span>, <span dir=\"rtl\">אוֹלְיָירִין</span>. <span class=\"citation\">Tosef. Kel. B. Mets. II, 12</span> <span dir=\"rtl\">מגררות של אוּלְיָרִין</span> ed. Zuck. (oth. ed. <span dir=\"rtl\">אולו׳</span> corr. acc.) the brushes (strigils) of the bathing attendants. <span class=\"citation\">Sabb. 147ᵇ</span>. <span class=\"citation\">Y. Ber. II, 4ᶜ</span> top; cmp. Pesik. R. l. c.; a. e. V. <a href=\"#\" data-headword=\"אוֹרְיָיר\">אוֹרְיָיר</a>. [<span class=\"citation\">Sabb. 144ᵃ</span> <span dir=\"rtl\">כלים הא׳</span>, <span class=\"citation\">Nidd. 20ᵃ</span> <span dir=\"rtl\">האולירין …</span>, v. <a href=\"#\" data-headword=\"אוֹלָרִין\">אוֹלָרִין</a>.]</div>","alt":["אוֹלְיָיר"]},"672":{"h":"אולירין","r":"A00672","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹלְיָאר\">foreg.</a> a. <a href=\"#\" data-headword=\"אוֹלָרִין\">אוֹלָרִין</a>.</div>","alt":[]},"673":{"h":"אוּלְלָא","r":"A00673","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַלְלָא\">אַלְלָא</a></div>","alt":[]},"674":{"h":"אוּלָם I","r":"A00674","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> אלם <i>in front of, opposite</i>, Schr. K. A. T. glossary, a. b. h. conj. <a href=\"#\" data-headword=\"אוּלָם I\">אוּלָם</a>) <i>entrance, hall, </i>esp<i>. Ulam</i>, the hall leading to the interior of the Temple. Mid. IV, 7; a. e.</div>","alt":[]},"675":{"h":"אוּלָם II","r":"A00675","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אוּלָם I\">foreg.</a>, Οὐλαμμοῦς Euseb. Euseb. Onom.; Neub. Géogr. p. 18; 261) <i>Ulam</i> (Porta) a place in Gilead, and one in Galilee. Y. Snh. X, 28ᵈ</div><div class=\"sense\"><b>—2)</b>  in Cilicia; v. <a href=\"#\" data-headword=\"*אַבְלַס\">אַבְלַס</a></div>","alt":[]},"676":{"h":"אוּלָמָא","r":"A00676","html":"<div class=\"sense\"> <span class=\"citation\">Targ. I Kings VII, 6</span>; a. fr.—<span class=\"citation\">Targ. II Chr. III, 4</span> <span dir=\"rtl\">אילם</span>, Var. <a href=\"#\" data-headword=\"אוּלְמָנָא\">אוּלְמָנָא</a>.—Pl. <span dir=\"rtl\">אוּלַמַּיָּא</span>. <span class=\"citation\">Targ. Ez. XL, 22</span>; a. e.</div>","alt":["אוּלַמָּא"]},"677":{"h":"אוּלְמָא","r":"A00677","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אֲלַם\">אֲלַם</a>) <i>strength, strong side</i>. <span class=\"citation\">Sabb. 134ᵃ</span> <span dir=\"rtl\">מא׳ לקוטנא</span> from the thick to the thinner side.—<span class=\"citation\">Nidd. 8ᵃ</span>, a. fr. <span dir=\"rtl\">מאי אוּלְמֵיה</span></div>","alt":[]},"678":{"h":"אוּלְמָנָא","r":"A00678","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוּלָמָא\">אוּלָמָא</a></div>","alt":[]},"679":{"h":"אולפין","r":"A00679","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוּלְפָן\">next w.</a></div>","alt":[]},"680":{"h":"אוּלְפָן","r":"A00680","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יְלֵף\">ילף</a>, <a href=\"#\" data-headword=\"אֲלַף I\">אלף</a>) <i>custom, training, instruction; the Law</i>. <span class=\"citation\">Targ. Y. Gen. XXXIII, 14</span>. <span class=\"citation\">Targ. Is. XXXII, 6</span>; a. fr.—Y. R. Hash. IV, beg. 59ᵇ for it is impossible for one to go through his Bible lesson <span dir=\"rtl\">דלא א׳</span> (read <span dir=\"rtl\">בלא</span>; cmp. <span class=\"citation\">Ḥag. 3ᵃ</span> <span dir=\"rtl\">בלא חדוש</span>) without some instructive observation. <span class=\"citation\">Y. Meg. I, 71ᵈ</span> top <span dir=\"rtl\">דלא מן א׳</span> not according to the Law. <span class=\"citation\">Gen. R. s. 80</span> וא׳ קבל Mat. Keh. (ed. <span dir=\"rtl\">ואולפין קביל</span>) and has he received traditions from teachers? <span class=\"citation\">Lev. R. s. 19</span> <span dir=\"rtl\">אולפני מה נהיר באפי</span> how my learning shines in my face! <span class=\"citation\">Y. Ber. VI, 10ᶜ</span> bot. <span dir=\"rtl\">נישבוק אולפנה וכ׳</span> let us drop discussion and return to the Mishnah. [<span class=\"citation\">Erub. 67ᵃ</span> bot. <span dir=\"rtl\">משמיה דא׳</span>, read with Ms. M. <span dir=\"rtl\">דאִילְפָא</span>.]—<a href=\"#\" data-headword=\"אמוראי\">בר א׳</a> a scholar of traditional law. <span class=\"citation\">Lev. R. s. 3</span>, beg.—Pl. <span dir=\"rtl\">אוּלְפָנַיָּיא</span> <i>instructive narratives, stories</i>. Y. Kidd. 61ᵇ; <span class=\"citation\">Y. Peah I, 15ᶜ</span> bot.</div>","alt":["אוּלְפָנָא"]},"681":{"h":"אוּלְצָן","r":"A00681","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">אלץ</span>) <i>distress</i>, esp. <i>famine</i>. <span class=\"citation\">Targ. Job V, 11</span>; a. e.</div>","alt":["אוּלְצָנָא"]},"682":{"h":"אולר","r":"A00682","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אוֹלָד\">אוֹלָד</a></div>","alt":[]},"683":{"h":"*אולרייא","r":"A00683","html":"<div class=\"sense\"> <span class=\"citation\">Y. Sabb. VI, 8ᵇ</span> bot., read <span dir=\"rtl\">קוֹרוֹלַרְיָיא</span> m. pl. (pl. of corollarium) <i>gilt</i>, or <i>silvered wreaths</i>, a rendition of <span dir=\"rtl\">צניפות</span> (<span class=\"citation\">Is. III, 23</span>); v. bibl. quot. ibid., a. Targ. Is. l. c.</div>","alt":[]},"684":{"h":"אוֹלָרִין","r":"A00684","html":"<div class=\"sense\"> or <a href=\"#\" data-headword=\"אוֹלָרִין\">אוֹלָרְיִין</a> m. pl. (pl. of aularis or aularius = aulicus, D. C. Lat.) <i>belonging to the royal court, court-</i>, only in connect. with <span dir=\"rtl\">כלים</span> or <span dir=\"rtl\">בגדים</span>. <span class=\"citation\">Sabb. 114ᵃ</span> בגדי הא׳ Ms. M. (ed. <span dir=\"rtl\">כלים האוליירין</span>); <span class=\"citation\">Nidd. 20ᵃ</span> <span dir=\"rtl\">כלים האולרין</span> court clothes, including white cloaks <span dir=\"rtl\">(גלימי</span>), and red home or table dresses (<span dir=\"rtl\">לבושי</span>, <span dir=\"rtl\">פתורי</span>); v. Luebk. Alterth. s. v. Kleidung; Becker Gallus, ed. Gœll I, 16. Cmp. <a href=\"#\" data-headword=\"חִימּוּצָתָא\">חִימּוּצָתָא</a> a. <a href=\"#\" data-headword=\"*בּוּרדִּיקָא\">בּוּרְדִּיקָא</a>.</div>","alt":[]},"685":{"h":"אוּם","r":"A00685","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אֵם\">אֵם</a>; cmp. <a href=\"#\" data-headword=\"שׁוּם\">שׁוּם</a>, <a href=\"#\" data-headword=\"שֵׁם\">שֵׁם</a>) </div><div class=\"sense\"><b>1)</b> <i>mother</i>. <span class=\"citation\">Y. Yeb. XI, 11ᵈ</span> top. <span dir=\"rtl\">א׳ זכר</span> the mother of the male side, father-in-law’s mother; <span dir=\"rtl\">א׳ נקבה</span> mother-in-law’s mother.</div><div class=\"sense\"><b>—2)</b> <i>substance, bulk, </i>as<i> the cluster of olives</i> (contrad. to leaves); <i>the starting point</i> of leprosy. <span class=\"citation\">Toh. IX, 8</span> <span dir=\"rtl\">אם היה נוגע בא׳</span> if the reptile touched the cluster. <span class=\"citation\">Neg. I, 5</span> <span dir=\"rtl\">הלכה לה הא׳</span> the original leprosy has disappeared.</div><div class=\"sense\"><b>—3)</b> <i>womb</i>. <span class=\"citation\">Lev. R. s. 14</span> end, Ar. (ed. <a href=\"#\" data-headword=\"אֵם\">אֵם</a>).</div>","alt":[]},"686":{"h":"*אוּמָא","r":"A00686","html":"<p class=\"morphology\">f.</p><div class=\"sense\">(v. <a href=\"#\" data-headword=\"אוּם\">foreg.</a>) <i>the leaven, flour used for leaven</i>. <span class=\"citation\">Pes. 42ᵃ</span> <span dir=\"rtl\">קומניתא דא׳</span> (Ms. O. <span dir=\"rtl\">דנהמא</span>) the decay of the flour-substance; v. <a href=\"#\" data-headword=\"כּוּתָּח\">כּוּתָּח</a>. [V. also <a href=\"#\" data-headword=\"אוּנָא\">אוּנָא</a> end.]</div>","alt":[]},"687":{"h":"אוּמָּא","r":"A00687","html":"<div class=\"sense\"><i>nation</i>, v. <a href=\"#\" data-headword=\"אוּמָּת\">אוּמָּתָא</a>.</div>","alt":[]},"688":{"h":"אוֹמָאָה","r":"A00688","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">ימי</span>, Af. <a href=\"#\" data-headword=\"אוֹמִי\">אוֹמִי</a>) <i>the act of administering an oath, swearing, imprecation</i>. <span class=\"citation\">Targ. Y. Lev. V, 1</span>; <span class=\"citation\">4</span>.—*<span class=\"citation\">Targ. Y. II, Deut. XXVII, 15</span> <span dir=\"rtl\">פתחו הוּמְהוֹם וכ׳</span> (Var. <span dir=\"rtl\">פומהום</span>, ed. Vien. <span dir=\"rtl\">קתחו</span> corr. acc.) they opened their imprecation with a blessing.</div>","alt":["אוֹמָתָא","הוֹמָאָה"]},"689":{"h":"אוּמָד","r":"A00689","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אָמַד\">אָמַד</a>) <i>estimate, guess, measuring by mere sight, approximate assessment; medical opinion</i> as to the nature of injuries. <span class=\"citation\">Men. 54ᵇ</span> <span dir=\"rtl\">ניטלת בא׳</span> may be set apart (for the priest) by estimating (without measuring) the quantity. <span class=\"citation\">Snh. IV, 5</span> <span dir=\"rtl\">מא׳ ומשמועה</span> from mere supposition or hear-say. <span class=\"citation\">Ib. 78ᵇ</span> <span dir=\"rtl\">אין א׳ אחר א׳</span> the first estimate (medical opinion declaring an inflicted injury fatal) cannot be upset by a second more favorable opinion (if erroneously formed under the resemblance of recovery); v. <a href=\"#\" data-headword=\"אָמַד\">אָמַד</a>.—<span class=\"citation\">Ib.</span> <span dir=\"rtl\">א׳ האמצעי</span> the (second) opinion intermediate between the first opinion and the actual fatal result.</div>","alt":[]},"690":{"h":"אוּמָדוּת","r":"A00690","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"אוּמָד\">same</a>, adv. <i>by guess-work</i>. <span class=\"citation\">Y. Taan. IV, 68ᶜ</span> top <span dir=\"rtl\">שלא … דן א׳</span> that one must not judge from mere guess (appearance). <span class=\"citation\">Aboth I, 16</span> <span dir=\"rtl\">אל תרבה לעשר א׳</span> in giving tithes do not give (even) too much by guessing (but measure accurately).</div>","alt":[]},"691":{"h":"אוּמְדָּנָא","r":"A00691","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <span class=\"citation\">B. Kam. 41ᵃ</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"אוּמְדָּנָא\">אוּמְדָּנֵי</a> <span class=\"citation\">Snh. 78ᵇ</span></div>","alt":[]},"692":{"h":"אוּמָּה","r":"A00692","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> , v. <a href=\"#\" data-headword=\"אֵם\">אֵם</a>) <i>people, nation, government</i>. <span class=\"citation\">Ab. Zar. 18ᵃ</span> <span dir=\"rtl\">א׳ זו</span> this (Roman) government; a. fr.—Pl. <span dir=\"rtl\">אוּמּוֹת</span> <i>nations; gentiles</i> (contrad. to Israel); freq. <span dir=\"rtl\">א׳ העולם</span> (abbr. <span dir=\"rtl\">או&quot;הע</span>, <span dir=\"rtl\">א&quot;ה</span>). <span class=\"citation\">Gen. R. s. 39</span> <span dir=\"rtl\">שבעים א׳</span> the seventy nations (in the Noachidic genealogy), v. <span dir=\"rtl\">אֶוְותַּנְטִין</span>. <span class=\"citation\">Ab. Zar. 3ᵇ</span> <span dir=\"rtl\">באין אוה&quot;ע וכ׳</span> the gentiles shall come and be converted; a. fr.—<span dir=\"rtl\">דיני א׳</span> (freq. <a href=\"#\" data-headword=\"עכ\">עכ&quot;ום</a>, <a href=\"#\" data-headword=\"גּוֹי\">גוי</a>) gentile (not Israelitish) law. <span class=\"citation\">Y. Kidd. I, 58ᵇ</span> bot.; a. fr.—</div>","alt":[]},"693":{"h":"*אוֹמוֹלוֹגְיָיא","r":"A00693","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (ὁμολογία) [<i>agreement, admission</i>] <i>receipt, discharge</i>. [This meaning of ὁμολογία as <i>receipt</i> cannot be proven from Greek literature; cmp. however, Sm. Dict. Ant. s. v. Acceptilatio.] <span class=\"citation\">Y. M. Kat. III, 82ᵃ</span> bot., explaining <span dir=\"rtl\">שוברים</span> (v. <a href=\"#\" data-headword=\"שׁוֹבֵר\">שׁוֹבֵר</a>, receipt) <a href=\"#\" data-headword=\"אימולוגים\">אימולוגים</a> (corr. acc., De Lara <a href=\"#\" data-headword=\"אומולוגין\">אוֹמוֹלוֹגִין</a> pl. m. fr. ὁμόλογον). <span class=\"citation\">Y. Keth. IX, end, 33ᶜ</span> <span dir=\"rtl\">ולית רב או׳</span> (= <span dir=\"rtl\">ולית ליה לרב</span> is it Rab’s opinion that the divorced woman is not bound to write a receipt (for her dowry)?</div>","alt":[]},"694":{"h":"אומולוגין","r":"A00694","html":"<div class=\"sense\"> <span class=\"citation\">Pesik. R. s. 44</span>, read <a href=\"#\" data-headword=\"אֵילוֹגִין\">אִילוֹגִין</a>, v. ed. Friedm. p. 183ᵃ</div>","alt":["אמלוגין"]},"695":{"h":"אומוניאה","r":"A00695","html":"<div class=\"sense\">, read <span dir=\"rtl\">אֶגְמוֹנִיאָה</span>, v. <a href=\"#\" data-headword=\"הֶגְמוֹנְיָא\">הֶגְמוֹנְיָא</a></div>","alt":[]},"696":{"h":"אוֹמִי","r":"A00696","html":"<div class=\"sense\"> Af. of <a href=\"#\" data-headword=\"יְמֵי\">יְמִי</a>.</div>","alt":[]},"697":{"h":"אומיקטרון","r":"A00697","html":"<div class=\"sense\">, v. <span dir=\"rtl\">אימ׳</span></div>","alt":[]},"698":{"h":"אוּמְלָל","r":"A00698","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>broken down, crushed, low.</i> <i>—</i> Pl. <span dir=\"rtl\">אוּמְלָלִים</span>. <span class=\"citation\">Snh. 66ᵃ</span> (ref. to <span class=\"citation\">Lev. XIX, 14</span>) <span dir=\"rtl\">בא׳ שבעמך וכ׳</span> here the Bible speaks of the lowest among thy people (not <span dir=\"rtl\">נשיא בעמך</span> as <span class=\"citation\">Ex. XXII, 27</span>). [Ms. M. a. Ar. <span dir=\"rtl\">במֵילָלִין</span>.]</div>","alt":[]},"699":{"h":"אוֹמָן","r":"A00699","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אָמַן\">אמן</a>, <span dir=\"rtl\">ימן</span>) prop. <i>straight line, leader</i>, hence (agric.) <i>the border-bed, outmost furrow.</i> <span class=\"citation\">Peah IV, 5</span>. <span class=\"citation\">B. Mets. VII, 4</span>. <span class=\"citation\">Ned. IV, 4</span> (<span class=\"citation\">41ᵇ</span>) <span dir=\"rtl\">לא יעשה עמו בא׳</span> he must not work with him together in the border bed.—Pl. <span dir=\"rtl\">אוֹמָנִיּוֹת</span>, [fr. <a href=\"#\" data-headword=\"אוֹמָנִית\">אוֹמָנִית</a>, sub. <a href=\"#\" data-headword=\"עֲרוּגָה\">ערוגה</a>, f.]. <span class=\"citation\">B. Mets. 89ᵇ</span></div>","alt":[]},"700":{"h":"אוֹמַן","r":"A00700","html":"<div class=\"sense\"><span class=\"citation\">Targ. Y. I Lev. XIX, 9</span> (h. text <a href=\"#\" data-headword=\"פֵּאָה\">פאה</a>); <span class=\"citation\">Targ. Y. II ib.</span> <span dir=\"rtl\">אוֹ מִן</span> (read <a href=\"#\" data-headword=\"אוֹמַן\">אוֹמַן</a>). Ib. v. 27 Ar. (ed. <span dir=\"rtl\">צדדי</span>), XXI, 5 (of the beard, h. text <span dir=\"rtl\">פאת זקנך</span>).</div>","alt":["אוּמְנָא"]},"701":{"h":"אוּמָן","r":"A00701","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>skilled, artist, artisan, professional cook, architect</i> &amp;c. <span class=\"citation\">Ab. Zar. 34ᵇ</span> <span dir=\"rtl\">מורייס א׳</span> brine prepared by a professional manufacturer and dealer. <span class=\"citation\">Gen. R. s. 1</span> <span dir=\"rtl\">מדעת א׳</span> after the plan of an architect. <span class=\"citation\">Pesik. R. s. 11</span> <span dir=\"rtl\">שאינו א׳ וכ׳</span> who is not skilled in climbing up.; a. fr.—Pl. <span dir=\"rtl\">אוּמָנִין</span> <span class=\"citation\">Ber. 16ᵃ</span>; a. fr.</div>","alt":[]},"702":{"h":"אוּמַן","r":"A00702","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Is. XXI, 10</span> (adj.). <span class=\"citation\">Targ. Ex. XXVI, 1</span>; a. e.—<span class=\"citation\">Snh. 29ᵃ</span> (prov.) <span dir=\"rtl\">שב שני וכ׳</span> seven years a famine may last, but the artisan’s gate it will not cross. <span class=\"citation\">Sabb. 133ᵇ</span> <span dir=\"rtl\">האי א׳</span> the surgeon (who circumcises). <span class=\"citation\">B. Mets. 97ᵃ</span> <span dir=\"rtl\">טבחא וא׳</span> the butcher and the surgeon (of the community).—Pl. <span dir=\"rtl\">אוּמָנִין</span>, <span dir=\"rtl\">אוּמָנַיָּא</span>. <span class=\"citation\">Targ. I Chr. IX, 30</span>. <span class=\"citation\">Targ. II Kings XXIV, 14</span>; a. e. Y. Ber. IV, 13ᵃ top, as one uses promiscuously the words <span dir=\"rtl\">אומנון בניין וכ׳</span> (read <span dir=\"rtl\">אומנין</span>) artisans, builders, architects.</div>","alt":["אוּמָנָא","(אוּמָנָה)"]},"703":{"h":"אוּמְנָא","r":"A00703","html":"<div class=\"sense\"><i>front bed</i>, v. <a href=\"#\" data-headword=\"אוֹמַן\">אוֹמַן</a>.</div>","alt":[]},"704":{"h":"אוּמָנָה","r":"A00704","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוּמָן\">אוּמָן</a> ch.</div>","alt":[]},"705":{"h":"אוֹמָנוּ","r":"A00705","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוּמָנוּתָא\">אוֹמָנוּתָא</a></div>","alt":[]},"706":{"h":"אומנון","r":"A00706","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוּמַן\">אוּמַן</a></div>","alt":[]},"707":{"h":"אומנוס","r":"A00707","html":"<div class=\"sense\">, read <a href=\"#\" data-headword=\"אֲמָנוֹן\">אֲמָנוֹס</a>, v. <a href=\"#\" data-headword=\"אֲמָנָה II\"><span dir=\"rtl\">אֲמָנָה</span> II</a></div>","alt":[]},"708":{"h":"אוּמָנוּת","r":"A00708","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אוּמָן\">אוּמָן</a>) </div><div class=\"sense\"><b>1)</b> <i>skill, handicraft, trade.</i> <span class=\"citation\">Kidd. IV, 14</span>.—בעל א׳ <i>mechanic</i>. <span class=\"citation\">Ḥull. 54ᵇ</span>.—בן אומנותוֹ <i>one’s fellow-tradesman, competitor</i>. <span class=\"citation\">Gen. R. s. 32</span>, beg.—<span class=\"citation\">Ber. 43ᵇ</span> <span dir=\"rtl\">כל אחד ואחד יִפָּה לו וכ׳</span> to each man the Lord made his trade appear nice. <span class=\"citation\">Y. Succ. V, end, 55ᵈ</span> (play on <i>be-ĕmunatham</i> <span class=\"citation\">I Chron. IX, 22</span>) <span dir=\"rtl\">באומנותם</span> through their skill; a. fr.— <i>the workmanship</i> (or its equivalent) to be furnished the (Roman) government. <span class=\"citation\">B. Bath. IX, 4</span>. <span class=\"citation\">Y. Dem. VI, end, 26ᵃ</span>; <span class=\"citation\">Tosef. Dem. VI, 4</span>; cmp. <a href=\"#\" data-headword=\"אוֹצָר\">אוֹצָר</a>.—Pl. <span dir=\"rtl\">אוּמָנִיּוֹת</span>. <span class=\"citation\">Gen. R. s. 24</span>. <span class=\"citation\">Num. R. s. 15</span> <span dir=\"rtl\">קורא א׳</span> invited people by trades (each day another trade); Tanḥ. B’haăl., 3 <span dir=\"rtl\">קורא בכל יום א׳</span>.—Trnsf. <i>arts, devices</i>. <span class=\"citation\">Ex. R. s. 47</span>, end <span dir=\"rtl\">כל הצדיקים באו בא׳</span></div>","alt":[]},"709":{"h":"אוּמָנוּתָא","r":"A00709","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Ex. XXXV, 33</span>; a. e.—<span class=\"citation\">Macc. 8ᵇ</span>; a. e.—<span class=\"citation\">Koh. R. to III, 9</span> <span dir=\"rtl\">מאי מהני אומנה באוּמָנוּתֵיה</span> what does the artist profit by his skill? <span class=\"citation\">Y. Git. V, 47ᵇ</span> bot. <span dir=\"rtl\">יהבין בניהון לא׳</span> indenture their children as apprentices; <span class=\"citation\">Y. B. Bath. X, 17ᶜ</span> bot. <span dir=\"rtl\">לאומנתה</span> (corr. acc.). <span class=\"citation\">Sabb. 103ᵃ</span> <span dir=\"rtl\">חזי א׳ וכ׳</span> sees a mechanical contrivance on a Sabbath and learns it. <span class=\"citation\">Y. Keth. IV, 28ᵈ</span> <a href=\"#\" data-headword=\"אמנותא\">אמנותא</a> (corr acc.), v. <a href=\"#\" data-headword=\"טְרִיקְלִין\">טְרִיקְלֵין</a>.—Pl. <span dir=\"rtl\">אוּמַנְוָותָא</span>, <a href=\"#\" data-headword=\"אומנון\">אוּמַנְוָן</a>; <span dir=\"rtl\">אוּמַנְוָון</span>. Targ. Ex. l. c. Targ. II Esth. VI, 12; a. fr. [Y. Ber. IV, 13ᵃ top, v. <a href=\"#\" data-headword=\"אוּמַן\">אוּמַן</a>.]</div>","alt":["אוּמָנוּ"]},"710":{"h":"אוֹמָנִית","r":"A00710","html":"<div class=\"sense\"><i>, </i> pl. <span dir=\"rtl\">אוֹמָנִיּוֹת</span>, v. <a href=\"#\" data-headword=\"אוֹמָן\">אוֹמָן</a>.</div>","alt":[]},"711":{"h":"אומפירטור","r":"A00711","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִמְפְּרָטוֹר\">אִמְפְּרָטוֹר</a></div>","alt":[]},"712":{"h":"אוּמְצָא","r":"A00712","html":"<div class=\"sense\"> com. (<a href=\"#\" data-headword=\"אָמַץ\">אמץ</a>) <i>a thick piece of meat, a piece which can be eaten raw after pressing</i> &amp;c. <span class=\"citation\">Sabb. 128ᵃ</span> <span dir=\"rtl\">חזי לא׳</span> fit to be eaten raw. <span class=\"citation\">Ḥull. 44ᵇ</span> <span dir=\"rtl\">א׳ מעלייתא</span> a fine piece &amp;c.; a. fr.—Pl. <span dir=\"rtl\">אוּמְצֵי</span>. <span class=\"citation\">Git. 69ᵃ</span> <span dir=\"rtl\">שב א׳</span> seven pieces.</div>","alt":[]},"713":{"h":"אוּמְרִית","r":"A00713","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>fringe, border</i>, v. <a href=\"#\" data-headword=\"אִימְּרָה\">אִימְרָה</a> h.</div>","alt":[]},"714":{"h":"אוּמָּת","r":"A00714","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>people</i>. <span class=\"citation\">Targ. Y. Deut. XXIX, 12</span>; a. e. <span class=\"citation\">Midr. Prov. to XXX, 28</span>; a. e.—<i>Pl</i>. <span dir=\"rtl\">אוּמִּין</span>. <span class=\"citation\">Targ. Y. Gen. XXV, 3</span>. <span class=\"citation\">Gen. R. s. 61</span>. <span dir=\"rtl\">אוּמַּיָּא־</span>, <span dir=\"rtl\">אוּמַּיָּיא</span>; <span dir=\"rtl\">אוּמֵּי</span>. <span class=\"citation\">Targ. Ps. CXVIII, 1</span>.—<span class=\"citation\">Midr. Till. to Ps. IX, 6</span> <span dir=\"rtl\">שנאיהון דא׳</span> those hated by the nations.—<span class=\"citation\">Sabb. 32ᵃ</span>.—<a href=\"#\" data-headword=\"אוּמָּת\">אוּמָּאתָא</a>, <a href=\"#\" data-headword=\"אוּמָּת\">אוּמָּתָא</a>. <span class=\"citation\">Targ. Prov. XXIV, 24</span>.</div>","alt":["אוּמָּתָא","אוּמָּא"]},"715":{"h":"אוֹמָתָא","r":"A00715","html":"<div class=\"sense\"><i>oath</i>, v. <a href=\"#\" data-headword=\"אוֹמָאָה\">אוֹמָאָה</a>.</div>","alt":[]},"716":{"h":"אָוֶן","r":"A00716","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> √<a href=\"#\" data-headword=\"אוֹ I\">או</a> = <span dir=\"rtl\">עו</span> <i>to curve, be curved, hollow; to press, be pressed;</i> v. <a href=\"#\" data-headword=\"אוי\">אוי</a>, </div><div class=\"sense\"><b>1)</b> <i>oppression, wrong</i> (= <a href=\"#\" data-headword=\"עָוֹן\">עָוֹן</a>)</div><div class=\"sense\"><b>—2)</b> <i>falsehood, vanity</i> (= <a href=\"#\" data-headword=\"הֶבֶל\">הֶבֶל</a>). <span dir=\"rtl\">א׳ גִּלְיוֹן</span> a cacophemistic adaptation of εὐαγγέλιον (v. <a href=\"#\" data-headword=\"גִּלָּיוֹן\">גליון</a>). <span class=\"citation\">Sabb. 116ᵃ</span> bot. (after <span dir=\"rtl\">לסכוניה</span>, omitted in ed.) <span dir=\"rtl\">דר׳ מאיר א׳ ג׳ ר׳ יוחנן קרי ליה עון גליון</span> (Rashi Ms. <span dir=\"rtl\">ר׳ מאיר</span>, v. Rabb. D. S. a. l. note) R. Meïr called the gospel falsehood of blank paper (or <i>of revelation</i>), R. Yoḥ. called it <i>sin of</i> &amp;c. [Ib. several times <span dir=\"rtl\">עון גליון</span> or <span dir=\"rtl\">און ג׳</span> in Ms. a. older editions, for <span dir=\"rtl\">אירייתא אחריתי</span> &amp;c. in recent ed., v. Rabb. D. S. a. l.]</div>","alt":["אָוֶון"]},"717":{"h":"אוֹן","r":"A00717","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>possession, power</i>. <span class=\"citation\">Tosef. Ab. Zar. III, 16</span> (<span class=\"citation\">IV</span>, beg.) <span dir=\"rtl\">כתב לו או̇נו̇</span> if he (the seller of the slave) wrote to him (gave him in writing) the liberty of his disposal of himself, i.e. that the slave, if he should run away from the buyer, would not be claimed by him who sold him; <span class=\"citation\">Git. 43ᵇ</span> <span dir=\"rtl\">כתב עליו אונו</span> (read <span dir=\"rtl\">אליו</span> or <span dir=\"rtl\">לו</span>). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מאי אונו</span> what means ‘his own possession’? Ans. He wrote to him this, ‘If thou run away from him (the purchaser), I have nothing to do with thee. <span class=\"citation\">Ib. 85ᵇ</span>.—[<span class=\"citation\">Y. B. Mets. I, end, 8ᵃ</span>; <span class=\"citation\">Y. Kidd. I, 60ᶜ</span> <span dir=\"rtl\">אונו</span>, v. <a href=\"#\" data-headword=\"אוֹנִי I\">אוֹנִי</a>.] V. <a href=\"#\" data-headword=\"אוני\">אוֹנָה</a>.</div>","alt":[]},"718":{"h":"אַיְנָא I","r":"A00718","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אוֹן\">foreg. ws.</a>; cmp. <span dir=\"rtl\">גנן</span>, <a href=\"#\" data-headword=\"חָנָה\">חָנָה</a>, <a href=\"#\" data-headword=\"חוּן\">חוּן</a>, a. <a href=\"#\" data-headword=\"עוֹנָה IV\">עוֹנָה</a>, <a href=\"#\" data-headword=\"מָעוֹן I\">מָעוֹן</a>) [circle], <i>night-lodging, station</i> for travellers (v. Sm. Ant. s. v. Mansio). <span class=\"citation\">Naz. 7ᵃ</span> <span dir=\"rtl\">כל אוו׳ וא׳</span> every station. <span class=\"citation\">B. Mets. 79ᵇ</span>; <span class=\"citation\">Ab. Zar. 65ᵃ</span> <span dir=\"rtl\">מא׳ לא׳</span> from station to station.—<span class=\"citation\">Deut. R. s. 6</span> she dared to bring disorder into <span dir=\"rtl\">אוננא של מלך</span> (read <span dir=\"rtl\">אוונא</span> or <a href=\"#\" data-headword=\"אַוָּונָא\">אַוְונָה</a>, v. infra) the royal head quarters. Pl. <span dir=\"rtl\">אַוְונִין</span>, <span dir=\"rtl\">אֲוָונִין</span>. <span class=\"citation\">Targ. Is. X, 32</span> (ed. Vien. <a href=\"#\" data-headword=\"*אוּנִין\">אַוְנִין</a>). [<span class=\"citation\">Sabb. 157ᵇ</span> <span dir=\"rtl\">אוונא</span>, v. <a href=\"#\" data-headword=\"אוּדְנָא II\"><span dir=\"rtl\">אוּדְנָא</span> II</a>.] [Comment. use h. forms <a href=\"#\" data-headword=\"אַוָּונָא\">אַוְונָה</a>, pl. <span dir=\"rtl\">אַוְונוֹת</span>.]</div>","alt":["אַוְונָא","אֲוָונָא"]},"719":{"h":"אֲוָנָא II","r":"A00719","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אַיְנָא I\">foreg.</a>) <i>Avana</i>, on the Tigris. <span class=\"citation\">Kidd. 71ᵇ</span> אכברא וא׳ Ar. ed. Koh. (oth. ed. Ar. <a href=\"#\" data-headword=\"אכבדא\">אכבדא</a>); Talm. ed. <span dir=\"rtl\">בגדא ואוונא</span> [Var. <a href=\"#\" data-headword=\"בַּגְדַּת\">בגדת</a>] Okhbara and Avana as bordertowns of Babylonia (v. De Sacy Chrest. Ar. I, p. 358 sq.; Koh. in Ar. s. v.).</div>","alt":["אֲוָונָא"]},"720":{"h":"*אונא","r":"A00720","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Nakis Una</i>(?), a gentile name. <span class=\"citation\">Git. 11ᵃ</span></div>","alt":["נקיס א׳"]},"721":{"h":"אוּנָא","r":"A00721","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (contr. of <a href=\"#\" data-headword=\"אוֹדֶן\">אוּדְנָא</a>, cmp. however <a href=\"#\" data-headword=\"אָוֶן\">אָוֶן</a>) </div><div class=\"sense\"><b>1)</b> <i>ear</i>, v. pl.</div><div class=\"sense\"><b>—2)</b> <i>handle</i> of a vessel. <span class=\"citation\">Git. 69ᵇ</span>. <span class=\"citation\">Sabb. 108ᵃ</span> top.</div><div class=\"sense\"><b>—3)</b> <i>lobe</i> of a lung. <span class=\"citation\">Ḥull. 59ᵇ</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"אוֹנִי I\">אוּנֵי</a>. <span class=\"citation\">Ib. 38ᵃ</span> <span dir=\"rtl\">אזוזי א׳</span> moving the ears (as a sign of life in the last stages). <span class=\"citation\">Yeb. 60ᵇ</span> <span dir=\"rtl\">מפיקנא … מאוניך</span> we shall get R. … out of thy ears, i.e. we shall make thee give up thy authority (a threat of excommunication). <span class=\"citation\">Gen. R. s. 45</span> <span dir=\"rtl\">אוניך דחמר</span> thy ears are those of an ass.—<span class=\"citation\">Ḥull. 47ᵃ</span> <span dir=\"rtl\">ה׳ אוני וכ׳</span> the lungs have five lobes; a. fr. [Later Rabb. literature uses <a href=\"#\" data-headword=\"*אוּמָא\">אוּמָא</a>, v. <a href=\"#\" data-headword=\"אוּם\">אוּם</a>, for the large lump from which the lobes branch off.] V. <a href=\"#\" data-headword=\"*אוּנִין\">אוּנִין</a>.</div>","alt":[]},"722":{"h":"אוֹנָאָה","r":"A00722","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יני\">יני</a>; cmp. <a href=\"#\" data-headword=\"הוֹנָאָה\">הוֹנָאָה</a>) </div><div class=\"sense\"><b>1)</b> <i>oppression, wrong</i>. <span class=\"citation\">B. Mets. 58ᵇ</span> <span dir=\"rtl\">גדולה אוֹנָאַת דברים מא׳ ממון</span> the wrong you do by means of words (wounding one’s feelings) is worse than that by pecuniary imposition. <span class=\"citation\">Ib. 59ᵃ</span> <span dir=\"rtl\">לעולם יהא … באוֹנָאַת אשתו וכ׳</span> one should always be on his guard not to wound his wife’s feeling, for as her tears are frequent <span dir=\"rtl\">אוֹנָאָתָהּ מרובה</span> so is her sense of wrong (sensibility) deep.</div><div class=\"sense\"><b>—2)</b>  (law) <i>imposition, overreaching, fraudulent representation</i> (which invalidates the transaction or requires redress); hence, <i>redress in case of overreaching</i>. <span class=\"citation\"><span class=\"citation\">Y. B. Mets. IV, 9ᵈ</span></span> top, a. fr. whoever concludes a bargain <span dir=\"rtl\">במנת שאין לו א׳ וכ׳</span> with the provision that no legal redress shall be resorted to, is notwithstanding entitled to redress.—<i>Denomin. Verb</i> <a href=\"#\" data-headword=\"אוני\">(אוֹנָה</a>), Hithpa. <span dir=\"rtl\">הִתְאוֹנֶה</span> <i>to be imposed upon, to feel one’s self overreached</i>. <span class=\"citation\"><span class=\"citation\">Y. B. Mets. IV, 9ᵈ</span></span> top. <span dir=\"rtl\">בשעה שהמוכר מִתְאוֹנֶה וכ׳</span> if the seller sues for undue advantage taken of him, he has the privilege of redress, provided the advantage amounts to one fifth or more of the price charged; if the buyer sues &amp;c. [In Babli the denomin. verb is <span dir=\"rtl\">אִינָּה</span>, v. <a href=\"#\" data-headword=\"אני\">אני</a>.]</div>","alt":[]},"723":{"h":"אוֹנָאוּתָא","r":"A00723","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אוֹנָאִיתָא\">אוֹנָאִיתָא</a></div>","alt":[]},"724":{"h":"אונאי","r":"A00724","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹסָאֵי\">אוֹסָאֵי</a></div>","alt":[]},"725":{"h":"*אוֹנָאִיתָא","r":"A00725","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> , <i>oppression, tyranny</i>. <span class=\"citation\">Targ. Ps. LXXIV, 20</span> (ed. Ven. <a href=\"#\" data-headword=\"אוֹנָאוּתָא\">אוֹנִאוּתָא</a>; h. text <a href=\"#\" data-headword=\"נֵאוֹת\">נְאוֹת</a>!). V. <a href=\"#\" data-headword=\"אוֹנָיָתָא\">אוֹנָיָתָא</a>.</div>","alt":["אוֹנָאוּתָא"]},"726":{"h":"אונדפא","r":"A00726","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אַנְדִּיפֵי\">אַנְדִּיפֵי</a></div>","alt":["אונדפי"]},"727":{"h":"אוֹנָה I","r":"A00727","html":"<div class=\"sense\"><i>to oppress</i>, v. <a href=\"#\" data-headword=\"אני\">אני</a>, and <a href=\"#\" data-headword=\"אוֹנָאָה\">אוֹנָאָה</a>.</div>","alt":[]},"728":{"h":"אוֹנָה II","r":"A00728","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אוֹן\">אוֹן</a>) <i>possession, title of possession, deed</i>. <span class=\"citation\">Gen. R. s. 79</span> (ref. to the letters <a href=\"#\" data-headword=\"יָהּ\">יה</a> in <a href=\"#\" data-headword=\"קְשִׂיטָה\">קשיֹטהֹ</a> <span class=\"citation\">Gen. XXXIII, 19</span>) <span dir=\"rtl\">יו&quot;ד ה&quot;א כותב הא׳ וכ׳</span> <i>Yod He</i> (i.e. the Lord) writes the deed; the Lord bears witness to the deed.—Pl. <span dir=\"rtl\">אוֹנוֹת</span>. <span class=\"citation\">B. Bath. 52ᵃ</span> <span dir=\"rtl\">א׳ ושטרות וכ׳</span> deeds of purchase and other documents were issued in his name.</div>","alt":[]},"729":{"h":"אוֹנוּ","r":"A00729","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹנִי I\"><span dir=\"rtl\">אוֹנִי</span> I</a></div>","alt":[]},"730":{"h":"אוֹנוֹ","r":"A00730","html":"<div class=\"sense\"> (b. h.) pr. n. pl. <i>Ono</i>, W. N. W. of Jerusalem. <span class=\"citation\">Cant. R. to II, 2</span>; <span class=\"citation\">Lam. R. to I, 17</span>. <span class=\"citation\">Snh. 11ᵇ</span> איש א׳ Ms. M. (ed. <a href=\"#\" data-headword=\"אוני\">אוני</a>); a. fr. V. <a href=\"#\" data-headword=\"אוֹנִי II\"><span dir=\"rtl\">אוֹנִי</span> II</a>.</div>","alt":[]},"731":{"h":"אונוס","r":"A00731","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹנֵיס\">אוֹנֵיס</a></div>","alt":[]},"732":{"h":"אוֹנוֹס","r":"A00732","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"*אָנְקִטְמִין\">אָנְקִטְמִין</a>; ὄνος) <i>the pulley of the crippled</i>. <span class=\"citation\">Y. Sabb. VI, 8ᶜ</span>. (Var. <span dir=\"rtl\">הוניס</span>.).</div>","alt":["א׳ קִטְמִין"]},"733":{"h":"אוֹנְטוֹס","r":"A00733","html":"<div class=\"sense\"> (ὄντως) <i>really! verily!</i> <span class=\"citation\">Lev. R. s. 33</span>, explain. <span dir=\"rtl\">הצדא</span> (<span class=\"citation\">Dan. III, 14</span>); (Ar. <a href=\"#\" data-headword=\"אָנְטוֹס\">אנטוס</a>, some ed. <span dir=\"rtl\">אונטיס</span>, corr. acc.); <span class=\"citation\">Num. R. s. 15</span> <a href=\"#\" data-headword=\"אָנְטוֹס\">אנטוס</a> (Tanḥ. Noah 11 <span dir=\"rtl\">האמת</span>).</div>","alt":[]},"734":{"h":"אונטלית","r":"A00734","html":"<div class=\"sense\"> <span class=\"citation\">Tosef. Kel. B. Bath. IV, 6</span> ed. Zuck., ed. <a href=\"#\" data-headword=\"אצטלוס\">אצטלוס</a>, Var. <span dir=\"rtl\">אצטלו׳</span> prob. <a href=\"#\" data-headword=\"*אִצְטַלּוּת\">אִצְטַלּוּת</a> q. v.</div>","alt":[]},"735":{"h":"אוני","r":"A00735","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹנָאָה\">אוֹנָאָה</a></div>","alt":["אוֹנָה"]},"736":{"h":"אוֹנִי I","r":"A00736","html":"<div class=\"sense\"> <span dir=\"rtl\">(<a href=\"#\" data-headword=\"אוֹנוּ\">אוֹנוּ</a>) <span dir=\"rtl\">אוֹנִית</span></span> f. = <a href=\"#\" data-headword=\"אוני\">אוֹנָה</a>, cmp. <a href=\"#\" data-headword=\"אוֹנִיתָא\">אוֹנִיתָא</a>. [The phonetic coïncidence with ὠνή produced the peculiar use of our w. in connection with Greek terms, in the Palest. literature.] <span class=\"citation\">Gen. R. s. 2</span> beg. <span dir=\"rtl\">בא׳ אחת ובטימי וכ׳</span> in one bill of sale and for the same price. <span class=\"citation\">Y. Pes. IV, 31ᵇ</span> bot. <span dir=\"rtl\">מיסתיוסיס בא׳ היא וכ׳</span> (read <span dir=\"rtl\">מיסתוס׳</span>) it is a lease with a title of possession (for the term), and is (for the time being) an acquisition like a purchase. <span class=\"citation\">Y. Kidd. I, 60ᶜ</span> (<a href=\"#\" data-headword=\"אוני\">אוני</a> a. <span dir=\"rtl\">אונו</span>); a. e.—Pl. <span dir=\"rtl\">אוֹנִיוֹת</span>. <span class=\"citation\">Gen. R. s. 84</span>, end <span dir=\"rtl\">כמה א׳ וכ׳</span> how many deeds were written for him (how many times was he sold)?, cmp. <a href=\"#\" data-headword=\"אוֹן\">אוֹן</a>. [<span class=\"citation\">Midr. Till. to Ps. CIV, 24</span>; Pesik. Rosh. Hash. p. 151ᵃ, v. <a href=\"#\" data-headword=\"אוֹנָיָה\">אוֹנָיָה</a>.]</div>","alt":["אוֹנִי"]},"737":{"h":"אוֹנִי II","r":"A00737","html":"<div class=\"sense\"> <a href=\"#\" data-headword=\"אֶבֶן\">בית א׳</a> pr. n. pl. (<i>Beth</i>) <i>Oni</i> in Palestine, prob. identic with <a href=\"#\" data-headword=\"אוֹנוֹ\">אוֹנוֹ</a>. <span class=\"citation\">Tosef. Shebi. VII, 14</span> <span dir=\"rtl\">פגי בית א׳</span> (ed. Zuckerm. <span dir=\"rtl\">בֵיתְיַאנֵי</span>, <span dir=\"rtl\">בֵיתְיַינֵי</span>, Var. <span dir=\"rtl\">ביתיני</span>) the unripe grapes of B. O. (Beth Yanai).—<span class=\"citation\">Y. Git. IV, 46ᵃ</span> <span dir=\"rtl\">א׳ אסור וכ׳</span> if a slave fled to Oni, he must not be extradited (because O. is a Palestinean place). V. <a href=\"#\" data-headword=\"הִינִי\">הִינִי</a> 3.</div>","alt":[]},"738":{"h":"אוֹנְיָא","r":"A00738","html":"<div class=\"sense\"> m. (prob.) <i>of Oni</i>, v. <a href=\"#\" data-headword=\"אוֹנִי II\">foreg.</a>, or pr. n. m. <i>Onya</i> (= Onias?). <span class=\"citation\">Y. Orl. I, 61ᵃ</span> top; <span class=\"citation\">Y. Sabb. I, 3ᶜ</span>; ib.ᵈ אנייא R. Joshua Onia, an Amora.</div>","alt":["אוֹנְיָיא","אָנְיָיא"]},"739":{"h":"אוֹנִיאוּתָא","r":"A00739","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אוֹנָאִיתָא\">אוֹנָאִיתָא</a></div>","alt":[]},"740":{"h":"אוֹנָיָה","r":"A00740","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"אוֹנָאָה\">אוֹנָאָה</a>; cmp. <span class=\"citation\">Ezek. XLVI, 18</span>) prop. <i>oppression, wrong</i>, hence <i>confiscation, dispossession. </i> Pl. <span dir=\"rtl\">אוֹנָיוֹת</span><i>.</i> <span class=\"citation\">Midr. Till. to Ps. CIV, 24</span> (play on <i>oniyoth</i> ibid.) <span dir=\"rtl\">אלו הא׳ וכ׳</span> those are the oppressive measures which they inflict upon Israel, which they order to be written out eveny day. *Pesik. R. Hash. p. 151ᵃ; <span class=\"citation\">Yalk. Jer. 312</span> <span dir=\"rtl\">הוֹנָיוֹת וזמיות</span> confiscations and fines (<span class=\"citation\">Yalk. Gen. 121</span>; <span class=\"citation\">Lev. R. s. 29</span>, a. e. <span dir=\"rtl\">ארנוניות</span>, v. Buber Pesik. l. c. note).</div>","alt":[]},"741":{"h":"אוֹנְיָיא","r":"A00741","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹנְיָא\">אוֹנְיָא</a></div>","alt":[]},"742":{"h":"אוּנְיָיקִי","r":"A00742","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Beth-Unyaki, Bithynia</i>, in Asia Minor (cmp. Neub. Géogr. pp. 262; 422). <span class=\"citation\">Yoma 10ᵃ</span> <span dir=\"rtl\">תובל זה בית א׳</span> (Ms. M. <a href=\"#\" data-headword=\"אוּנְקַי\">אונקי</a> indistinct; oth. Var., v. Rabb. D. S. a. l. note) <i>Tubal</i> means B. <span class=\"citation\">Ab. Zar. II, 4</span> (<span class=\"citation\">29ᵇ</span>) cheese of <a href=\"#\" data-headword=\"אֶבֶן\">בית א׳</a> (Ms. M. <a href=\"#\" data-headword=\"אוּנְקַי\">אונקי</a>, <span dir=\"rtl\">איניקי</span>, Mish. Nap. <a href=\"#\" data-headword=\"וְתִינְיָיקִי\">ותינייקי</a>, v. Rabb. D. S. a. l.). <span class=\"citation\">Tosef. Shebi. V, 9</span> <a href=\"#\" data-headword=\"הוּנְיָיקִי\">הונייקי</a> (ed. Zuck. <span dir=\"rtl\">גבינה ובית היניקי</span> read <span dir=\"rtl\">גבינת ב׳ ה׳</span>); <span class=\"citation\">Tosef. Ab. Zar. IV, 13</span> <span dir=\"rtl\">בית הינייקי</span> (Var. <span dir=\"rtl\">היניקאי</span>). Cmp. <a href=\"#\" data-headword=\"וְתַנְיָה\">וְתַנְיָה</a> a. <a href=\"#\" data-headword=\"אַנְיָאקָא\">אַנְיָאקָא</a>.</div>","alt":["בית א׳"]},"743":{"h":"*אוּנִין","r":"A00743","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (prob. pl. of <a href=\"#\" data-headword=\"אוּנָא\">אוּנָא</a> <i>ear</i>) <i>bundles of wet flax</i>. <span class=\"citation\">Sabb. I, 6</span>. <span class=\"citation\">Y. Shebi. V, 36ᵃ</span> bot.; a. e. [Rashi a. Tosaf. to <span class=\"citation\">Succ. 12ᵇ</span> <span dir=\"rtl\">אונץ</span> as a plur., v. Rabb. D. S. a. l.; cmp. <a href=\"#\" data-headword=\"אָנִיץ\">אָנִיץ</a>.]</div>","alt":[]},"744":{"h":"אוֹנֵיס","r":"A00744","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">אנס</span>) <i>tyrannus, lord, ruler</i>. <span class=\"citation\">Targ. Y. Ex. II, 16</span>; <span class=\"citation\">XVIII, 1</span>.</div>","alt":["(אונוס)"]},"745":{"h":"אוֹנִיתָא","r":"A00745","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>title of possession, deed</i>. <span class=\"citation\">Y. Taan. IV, 69ᵃ</span> <span dir=\"rtl\">והוו משלחין א׳ וכ׳</span> they would send the (forged) deed of sale to the steward; <span class=\"citation\">Lam. R. to II, 2</span> (corr. acc.).</div>","alt":[]},"746":{"h":"אוֹנָיָתָא","r":"A00746","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>oppression, wrong</i>. <span class=\"citation\">B. Bath. 22ᵃ</span> <span dir=\"rtl\">א׳ דמלכא וכ׳</span> the wrong inflicted on the king of Edom. <span class=\"citation\">Lev. R. s. 33</span>, beg. (ref. to <span class=\"citation\">Amos VII, 7</span>, v. <a href=\"#\" data-headword=\"*אֲנָךְ I\"><span dir=\"rtl\">אֲנָךְ</span> I</a>) <span dir=\"rtl\">על שורא דא׳</span> upon the wall of (i.e. watching over) the wrongs (in sale and purchase); cmp. <span class=\"citation\">B. Mets. 59ᵃ</span></div>","alt":["אוֹנִיתָא"]},"747":{"h":"*אוּנְכִין","r":"A00747","html":"<div class=\"sense\"> read <span dir=\"rtl\">קוּנְכִין</span> m. pl. (κόγχη, concha) <i>purple shells</i>. <span class=\"citation\">Targ. Y. Num. XXXIII, 8</span>; cmp. <a href=\"#\" data-headword=\"קוֹנְכִי\">קוּנְכִי</a>.</div>","alt":[]},"748":{"h":"אונכלי","r":"A00748","html":"<div class=\"sense\"> <span class=\"citation\">Tosef. Shebu. VI, 4</span> ed. Zuck., v. <a href=\"#\" data-headword=\"אַמְפְּלַי\">אֲמַפְּלַי</a></div>","alt":[]},"749":{"h":"אֲוַנְכְּרֵי","r":"A00749","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (prob. a nom. gentil., from a trading station named <a href=\"#\" data-headword=\"אֲוַונְכַּר\">אוונכר</a>, a compound of <span dir=\"rtl\">אוונא</span> [a. <a href=\"#\" data-headword=\"אִכָּר\">אִכָּר</a>?]; cmp. <a href=\"#\" data-headword=\"אַיְנָא I\">אֲוָנָא</a>) <i>Avankreans</i>(?), <i>traders</i>. <span class=\"citation\">Succ. 30ᵃ</span>; <span class=\"citation\">30ᵇ</span>. [Ar. identifies our w. with <a href=\"#\" data-headword=\"אַכְוַנְגַּר\">אַכְוַנְגַּר</a> which is not in agreement with the context.]</div>","alt":["אֲוַונְכְּרֵי"]},"750":{"h":"אוֹנֵן","r":"A00750","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אָנַן\">אָנַן</a></div>","alt":[]},"751":{"h":"אוננא","r":"A00751","html":"<div class=\"sense\"> <span class=\"citation\">Deut. R. s. 6</span>, read <a href=\"#\" data-headword=\"אַוָּונָא\">אַוְונָא</a>.</div>","alt":[]},"752":{"h":"אונניות","r":"A00752","html":"<div class=\"sense\"> <span class=\"citation\">Lev. R. s. 23</span>, v. <a href=\"#\" data-headword=\"אַנֹּונָא\">אַנּוֹנָא</a>.</div>","alt":[]},"753":{"h":"אוֹנֶס","r":"A00753","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אָנַס\">אָנַס</a>) <i>compulsion, force; unavoidable interference, accident</i>. <span class=\"citation\">Git. 30ᵃ</span>, a. e. <span dir=\"rtl\">אין א׳ בגיטין</span> the plea of unavoidable interference cannot be raised in letters of divorce (to which a condition is attached). <span class=\"citation\">Y. M. Kat. III, 81ᵈ</span> bot., a. e. <span dir=\"rtl\">מחמת אוֹנְסוֹ</span> through no fault of his.—Pl. <span dir=\"rtl\">אוֹנְסִים</span>, <a href=\"#\" data-headword=\"*אונסין\">אוֹנְסִין</a>. <span class=\"citation\">Ned. III, 1</span>, a. e. <span dir=\"rtl\">נדרי א׳</span> vows on conditions unavoidably unfulfilled.</div>","alt":[]},"754":{"h":"אוֹנֶס ²","r":"A00754","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(v. <a href=\"#\" data-headword=\"אוֹנֶס\">foreg.</a>) <i>wrong, oppression</i>. <span class=\"citation\">Targ. Is. LVIII, 9</span>; <span class=\"citation\">13</span> <span dir=\"rtl\">מלין דא׳</span> offensive (violent) words (h. text <a href=\"#\" data-headword=\"אָוֶן\">אָוֶן</a>, cmp. <a href=\"#\" data-headword=\"אוֹנָאָה\">אוֹנָאָה</a>).</div>","alt":[]},"755":{"h":"אוּנְסָא","r":"A00755","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(= h. <a href=\"#\" data-headword=\"אוֹנֶס\">אוֹנֶס</a>, v. <a href=\"#\" data-headword=\"אוֹנֶס ²\">foreg.</a>) <i>force, wrong, robbery; accident</i>. <span class=\"citation\">Targ. Y. Gen. XXXI, 12</span>; a. fr.—<span class=\"citation\">Git. 34ᵃ</span>. <span dir=\"rtl\">אי משום א׳</span> shall we take into consideration the possibility of an unavoidable accident?—Pl. <span dir=\"rtl\">אוֹנְסַיָּא</span>. <span class=\"citation\">Ned. 27ᵇ</span> <span dir=\"rtl\">א׳ דמיגליא</span> (read <span dir=\"rtl\">דמיגליי</span>, Rashi <span dir=\"rtl\">אונסא</span>) accidents which may be foreseen.</div>","alt":[]},"756":{"h":"אוֹנָסָא","r":"A00756","html":"<div class=\"sense\"> m., pl. <a href=\"#\" data-headword=\"*אונסין\">אוֹנָסִין</a> = <a href=\"#\" data-headword=\"אָנִיסָא\">אָנוֹסָא</a>.</div>","alt":[]},"757":{"h":"*אונסין","r":"A00757","html":"<div class=\"sense\">, <span dir=\"rtl\">פרק א׳</span> a corrupt. of <span dir=\"rtl\">פְּרוֹקוֹנִיסוֹס</span> pr. n. pl. <i>Proconnesus</i>, in Mysia, renowned for its marble. <span class=\"citation\">Esth. R. to I, 6</span>.</div>","alt":[]},"758":{"h":"אוּנְפִּיל","r":"A00758","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">נפל</span>) <i>a wooden vessel for the reception of refuse, remnants of victuals</i> &amp;c. <span class=\"citation\">Tosef. Kel. B. Mets. V, 10</span>. Cmp. <a href=\"#\" data-headword=\"אוּנְפְּלָא\">next w.</a></div>","alt":["אַנְפִּיל"]},"759":{"h":"אוּנְפְּלָא","r":"A00759","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַמְפְּלַי\">אֲמַפְּלַי</a></div>","alt":["אוּנְפְּלַי"]},"760":{"h":"אוּנְקָא I","r":"A00760","html":"<div class=\"sense\"> <a href=\"#\" data-headword=\"עוּנְקָא\">עוּנְקָא</a> m. (<a href=\"#\" data-headword=\"עֲנָק I\">ענק</a>) <i>neck, meat from the neck</i>. <span class=\"citation\">Sabb. 140ᵇ</span> <a href=\"#\" data-headword=\"א׳\">א׳</a> ed. (Ar. <a href=\"#\" data-headword=\"ע׳\">ע׳</a>; Ms. M. <span dir=\"rtl\">עוזקא</span>). <span class=\"citation\">Ber. 44ᵇ</span> <a href=\"#\" data-headword=\"ע׳\">ע׳</a> ed. (Ms. M. <a href=\"#\" data-headword=\"א׳\">א׳</a>).</div>","alt":[]},"761":{"h":"אוּנְקָא II","r":"A00761","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>hook</i>, v. <a href=\"#\" data-headword=\"אוּנְקַי\">אוּנְקַי</a> a. <a href=\"#\" data-headword=\"אוּנְקְלַי I\"><a href=\"#\" data-headword=\"אוּנְקְלַי I\">אוּנְקְלַי</a>.</a></div>","alt":[]},"762":{"h":"אוּנְקוֹלִין","r":"A00762","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוּנְקְלַי I\">אוּנְקְלַי</a></div>","alt":[]},"763":{"h":"אוֹנְקוֹס","r":"A00763","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ὄγκος) </div><div class=\"sense\"><b>1)</b> <i>bulk, pile;</i> (in philosophy) <i>a primitive body</i>. Tanḥ. T’rum. 11 <span dir=\"rtl\">א׳ של מים</span> the body of water; <span dir=\"rtl\">א׳ של אש</span> (some ed. <span dir=\"rtl\">אונקנוס</span>). </div><div class=\"sense\"><b>2)</b> <i>trouble, difficulty, painstaking</i>. <span class=\"citation\">Gen. R. s. 12</span> (ref. to <span class=\"citation\">Neh. IX, 6</span> sq.) <span dir=\"rtl\">כל הא׳ הזה וכ׳</span> (ed. <a href=\"#\" data-headword=\"אונקים\">אונקים</a>, corr. acc.) what is all this painstaking (creating the universe &amp;c.) for? Ans. Because ‘thou art the Lord who hast chosen Abraham’ i.e. for the sake of establishing religion on earth; cmp. <span class=\"citation\">Midr. Till. to Ps. CIV, 18</span>.</div>","alt":[]},"764":{"h":"אוּנְקַי","r":"A00764","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אוּנְקָא I\"><span dir=\"rtl\">אוּנְקָא</span> I</a>, a. <a href=\"#\" data-headword=\"אוּנְקְלַי I\"><span dir=\"rtl\">אוּנְקְלַי</span> I</a>) </div><div class=\"sense\"><b>1)</b> <i>neck-shaped, hook, grapple</i>.—Pl. <span dir=\"rtl\">(<a href=\"#\" data-headword=\"אוּנְקְלָאוֹת\">אוּנְקָאוֹת</a>) <span dir=\"rtl\">אוּנְקִיּוֹת</span></span>. <span class=\"citation\">Kel. XII, 2</span> (Var. in Mish. ed. <span dir=\"rtl\">אוּנְקְלִיּוֹת</span>). <span class=\"citation\">Tosef. Kel. B. Mets. II, 4</span> (disting. from <a href=\"#\" data-headword=\"אוּנְקְלָאוֹת\">אוּנְקְלָאוֹת</a>).—[</div><div class=\"sense\"><b>2)</b>  for <a href=\"#\" data-headword=\"אוּנְקְיָא\">אונקיא</a>, v. next w.]</div>","alt":["אוּנְקָא"]},"765":{"h":"אוּנְקְיָא","r":"A00765","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (uncia, οὐγκία) </div><div class=\"sense\"><b>1)</b> <i>ounce</i>, one twelfth of a litra. <span class=\"citation\">Gen. R. s. 17</span> <span dir=\"rtl\">א׳ של כסף</span> an ounce of silver. <span class=\"citation\">Lam. R. to I, 1</span> <span dir=\"rtl\">נסבון מן אונקא</span> (<a href=\"#\" data-headword=\"עוּר I\">העיר</a>) (corr. acc.) they bought ounce-wise (pepper).</div><div class=\"sense\"><b>—2)</b>  trnsf. <i>a trifle, particle</i>. <span class=\"citation\">Y. Taan. IV, 68ᶜ</span> top there is not a generation in which there is not (to be atoned for through suffering) <span dir=\"rtl\">אונקי אחת וכ׳</span> (read <span dir=\"rtl\">אונקיא אחת</span>) a particle of the sin of the calf-worship. <span class=\"citation\">Ex. R. s. 43</span>, beg. <a href=\"#\" data-headword=\"*אוּקְיָא\">אוקיא</a> (corr. acc.). <span class=\"citation\">Gen. R. s. 29</span>; <span class=\"citation\">Yalk. Gen. 47</span>; <span class=\"citation\">Yalk. Job. 908</span> (play on <span dir=\"rtl\">אי נקי</span> <span class=\"citation\">Job. XXII, 30</span>) <span dir=\"rtl\">א׳ אחת היתה וכ׳</span> only an ounce (of merit) did Noah possess; v. <a href=\"#\" data-headword=\"*אינוניתא\">אינוניתא</a>.—Pl. <span dir=\"rtl\">אוּנְקִיּוֹת</span>. <span class=\"citation\">Gen. R. s. 79</span>, end (play on the letters of <span dir=\"rtl\">ק̇ש̇י̇ט̇ה̇</span> <span class=\"citation\">Gen. XXXIII, 19</span>) <span dir=\"rtl\">במאה אונקֹיות … ס̇לעים … ט̇לאים</span> for one hundred (<span dir=\"rtl\">ק̇</span>) ounces (of gold) &amp;c. V. <a href=\"#\" data-headword=\"*אוּקְיָא\">אוּקְיָא</a>.</div>","alt":[]},"766":{"h":"אונקיינוס","r":"A00766","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹקְיָינוֹס\">אוֹקְיָינוֹס</a></div>","alt":[]},"767":{"h":"אונקילוסיא","r":"A00767","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֶנְקְלַסְיָא\">אֶנְקְלַסְיָא</a></div>","alt":[]},"768":{"h":"אונקים","r":"A00768","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹנְקוֹס\">אוֹנְקוֹס</a></div>","alt":[]},"769":{"h":"אוּנְקַל","r":"A00769","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוּנְקְלַי II\"><span dir=\"rtl\">אוּנְקְלַי</span> II</a></div>","alt":[]},"770":{"h":"אוּנְקְלָא","r":"A00770","html":"<div class=\"sense\"> , <i>hook</i>, &amp;c. <span class=\"citation\">Targ. Job. XL, 26</span>.—Pl. <a href=\"#\" data-headword=\"אוּנְקוֹלִין\">אוּנְקְלִין</a>. <span class=\"citation\">Targ. Y. Ex. XXVII, 10</span>. Lev. (ed. <a href=\"#\" data-headword=\"וַי\">ווי</a>). <span class=\"citation\">Targ. Ez. XL, 43</span> <span dir=\"rtl\">(<a href=\"#\" data-headword=\"עֲנִקְלִין\">עֲנִקְלִין</a>) <span dir=\"rtl\">עוּנְקְלִין</span></span>.—Fem. pl. <span dir=\"rtl\">אוֹנְקַלְוָון</span>. <span class=\"citation\">Targ. Y. Lev. X, 5</span>. <span class=\"citation\">Targ. Esth. I, 6</span>.—<span class=\"citation\">Targ. Y. II, Ex. XXVI, 37</span> <span dir=\"rtl\">אַנְקְלַוָותְהוֹן</span> their hooks.</div>","alt":[]},"771":{"h":"אוּנְקְלָאוֹת","r":"A00771","html":"<div class=\"sense\"> plur. of <a href=\"#\" data-headword=\"אוּנְקְלַי I\"><span dir=\"rtl\">אוּנְקְלַי</span> I</a>.</div>","alt":[]},"772":{"h":"אוּנְקְלָה","r":"A00772","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוּנְקְלַי II\"><span dir=\"rtl\">אוּנְקְלַי</span> II</a></div>","alt":[]},"773":{"h":"אוֹנְקְלוֹס","r":"A00773","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (Ocellus?) <i>Onk’los</i>, the alleged translator of the Pentateuch into Chaldaic, freq. surnamed <span dir=\"rtl\">הַגֵּר</span> the proselyte; often identified with <i>Aquila</i>, the alleged author of a Greek translation of the Bible; v. <a href=\"#\" data-headword=\"עֲקִילַס\">עְקִילָס</a>. Cmp. <span class=\"citation\">Meg. 3ᵃ</span>; <span class=\"citation\">Ab. Zar. 11ᵃ</span>, with Tanḥ. <span class=\"citation\">Mishp. 5</span>. <span class=\"citation\">Cant. R. to I, 11</span> <a href=\"#\" data-headword=\"*אלקולאון\">אלקולאון</a> q. v.</div>","alt":["אָנְקְלוֹס"]},"774":{"h":"אונקלוסיא","r":"A00774","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֶנְקְלַסְיָא\">אֶנְקְלַסְיָא</a></div>","alt":[]},"775":{"h":"אוּנְקְלַי I","r":"A00775","html":"<div class=\"sense\"> <span dir=\"rtl\">אָנְקְלַי</span> f. (<a href=\"#\" data-headword=\"אנק\">אנק</a>, with <a href=\"#\" data-headword=\"ל\">ל</a> format.; = <a href=\"#\" data-headword=\"אוּנְקַי\">אוּנְקַי</a>; corresp. to b. h. <a href=\"#\" data-headword=\"לוּלַי\">לוּלַי</a>; Greek adapt. ἀγκολη, LXX <span class=\"citation\">Ex. XXVI, 10</span>; cmp. <a href=\"#\" data-headword=\"אוֹנִי I\">אוֹנִי</a> as to contact of the two languages) prop. <i>little</i> (<i>camel’s</i>) <i>neck</i>, hence </div><div class=\"sense\"><b>1)</b> <i>hook, rack.</i> <span class=\"citation\">Kel. XII, 2</span> א׳ של כתפין Ar. (ed. <span dir=\"rtl\">אונקליות</span>, <span dir=\"rtl\">אונקלין</span> with adject. in the sing., corr. acc.) the carriers’ hook attached to their yoke, pole &amp;c. Ib. <span dir=\"rtl\">א׳ של דרגש</span> the hook of the bedstead (used for fastening the girths to the posts); <span dir=\"rtl\">של נקליטין</span> the rack of the bed-curtain, v. <a href=\"#\" data-headword=\"נַקְלִיטִין\">נַקְלִיטִין</a>. Ib. 3 <span dir=\"rtl\">א׳ שבכותלים</span> hook attached to walls.—<span class=\"citation\">T’bul Yom IV, 6</span> <span dir=\"rtl\">ואנ׳ שלהם קיימת</span> and the hook (attached to the now broken yoke) remained unimpaired; a. fr.—Pl. <a href=\"#\" data-headword=\"אוּנְקְלָאוֹת\">אוּנְקְלָאוֹת</a>, <span dir=\"rtl\">אָנְקְ׳</span>, <span dir=\"rtl\">(<span dir=\"rtl\">אונקלין</span>) <span dir=\"rtl\">אוּנְקְלִיּוֹת</span></span>. <span class=\"citation\">Tam. III, 5</span>; Mid. III, 5; a. fr.—Kel. l. c.; <span class=\"citation\">Tosef. Kel. B. Mets. II, 4</span>; v. <a href=\"#\" data-headword=\"אוּנְקַי\">אוּנְקַי</a>.</div><div class=\"sense\"><b>—2)</b>  [cmp. ἀγκαλίς in S.] <i>the load carried on the hook, the farmer’s load of sheaves or bunches;</i> cmp. <a href=\"#\" data-headword=\"*בְּלוּנְקֵי\">בלונקי</a>. <span class=\"citation\">Tosef. Maas. Sh. IV, 10</span>. <span dir=\"rtl\">כל הא׳</span> the whole load. [<span class=\"citation\">Ib. 11</span> <a href=\"#\" data-headword=\"אוּנְקוֹלִין\">אונקולין</a>, <a href=\"#\" data-headword=\"אוּנְקְלַי I\">אונקלי</a>, read with ed. Zuck. <span dir=\"rtl\">אינפולי</span>].</div><div class=\"sense\"><b>—3)</b>  Trnsf. (medic.) <i>bent cartilage</i>, esp. <i>the cartilage</i> (cart. ensiformis) <i>at the end of the sternum which, being bent inside, presses on the stomach and creates nausea</i> &amp;c. <span class=\"citation\">Ab. Zar. 29ᵃ</span> <span dir=\"rtl\">מעלין א׳ וכ׳</span> you are permitted to lift the cartilage on the Sabbath (by means of a bandage &amp;c.). Ib. <span dir=\"rtl\">מאי א׳ וכ׳</span> what <i>unklay</i> is meant? Ans. the cartilage in front of the heart; v. <span dir=\"rtl\">אִיסְתּוֹמְכָא</span>.</div>","alt":[]},"776":{"h":"אוּנְקְלַי II","r":"A00776","html":"<div class=\"sense\"> <a href=\"#\" data-headword=\"אוּנְקַל\">אוּנְקַל</a>, <a href=\"#\" data-headword=\"נִקְלָה\">נִקְלָה</a>, <a href=\"#\" data-headword=\"נִיקְלַי\">נִיקְלַי</a> f. (<span dir=\"rtl\">נקל</span>, <span dir=\"rtl\">קל</span>, cmp. esp. <span class=\"citation\">II Sam. VI, 20</span> to 22) <i>the light garment</i>, whence, a name for the <i>easy dress</i> worn in the house and, under the cloak, in the street, but in which it was unbecoming to appear in public. [Cmp. II Sam. l. c. a. <span class=\"citation\">Num. R. s. 4</span>; a. e.] <span class=\"citation\">Y. Yoma VI, 43ᵈ</span> top <a href=\"#\" data-headword=\"אוּנְקְלָה\">אוּנְקְלָה</a>, <span dir=\"rtl\">נקלה</span>, for which <span class=\"citation\">Men. 109ᵇ</span> <a href=\"#\" data-headword=\"אוּנְקְלַי I\">אונקלי</a>. <span class=\"citation\">Snh. 82ᵃ</span> he took off the point of his spear <span dir=\"rtl\">והניחה באונקלוֹ</span> (some ed. <a href=\"#\" data-headword=\"לֵי\">לי</a>—) and put it (hiding it) in his undergarment. <span class=\"citation\">M. Kat. 24ᵃ</span> <span dir=\"rtl\">אָבֵל מטייל בא׳ וכ׳</span> (Ms. M. <span dir=\"rtl\">מטייל אָבֵל</span>) a mourner may walk on the Sabbath within the limits of his house (garden &amp;c.) in the easy dress (showing the rent on account of a death in the family; Rashi). <span class=\"citation\">Sabb. 120ᵃ</span> (garments to be saved from fire on a Sabbath) <a href=\"#\" data-headword=\"אוּנְקְלַי I\">אונקלי</a>; Y. ib. XVI, 15ᵈ top <a href=\"#\" data-headword=\"נִיקְלַי\">ניקלי</a>.—<span class=\"citation\">Meg. IV, 8</span> (<span class=\"citation\">24ᵇ</span>) <a href=\"#\" data-headword=\"אֶבֶן\">בית א׳</a>; (read as) Y. ib. a. Mss. <span dir=\"rtl\">בית יד א׳</span> the sleeve of his under-dress. [<span class=\"citation\">Tosef. Maas. Sh. IV, 11</span>, v. <a href=\"#\" data-headword=\"אוּנְקְלַי I\">foreg.</a> 2.]</div>","alt":[]},"777":{"h":"אוֹנקַלְמוֹס","r":"A00777","html":"<div class=\"sense\"><b>,</b> v. <a href=\"#\" data-headword=\"אִיקוֹנוֹמוֹס\">אִיקוֹנוֹמוֹס</a></div>","alt":[]},"778":{"h":"אונקלסיא","r":"A00778","html":"<div class=\"sense\"><b>,</b> v. <a href=\"#\" data-headword=\"אֶנְקְלַסְיָא\">אֶנְקְלַסְיָא</a></div>","alt":[]},"779":{"h":"אוס","r":"A00779","html":"<div class=\"sense\"> Ar. ed. pr., Ms. <a href=\"#\" data-headword=\"אוּם\">אוּם</a> q. v.</div>","alt":[]},"780":{"h":"אוֹסָאֵי","r":"A00780","html":"<div class=\"sense\"> m. pl., prob. <span dir=\"rtl\">מוֹסָאֵי</span>, name of a tribe. <span class=\"citation\">Targ. Ps. CXX, 5</span>, v. <a href=\"#\" data-headword=\"אוסיא\">אוֹסיא</a> (some ed. <a href=\"#\" data-headword=\"אונאי\">אונאי</a>).</div>","alt":[]},"781":{"h":"אוסטולין","r":"A00781","html":"<div class=\"sense\"> Midr. Sam. ch. XI, v. <a href=\"#\" data-headword=\"אִסְטְלִי\">אִסְטְלִי</a></div>","alt":[]},"782":{"h":"אַוְסֵי","r":"A00782","html":"<div class=\"sense\"> (or <span dir=\"rtl\">אוּ׳</span>) m. pl. (√<a href=\"#\" data-headword=\"אַף I\">אף</a> soft. into <a href=\"#\" data-headword=\"אוֹ I\">או</a>; cmp. <a href=\"#\" data-headword=\"אַף I\">אַף</a>, <a href=\"#\" data-headword=\"*אָנַף\">אָנַף</a>; also <a href=\"#\" data-headword=\"אֶפֶס\">אֶפֶס</a>) <i>nose, nostrils</i>. <span class=\"citation\">Sabb. 67ᵃ</span> <span dir=\"rtl\">ואאוסי דגוריתא</span> and on the nostrils of the young lioness. <span class=\"citation\">B. Bath. 73ᵇ</span> דסליק עליה באוסיה אכלה טינא ומית Ms. R. (ed. <span dir=\"rtl\">דיתבא ליה אכלה טינא באוסי׳</span>, Ms. M. <a href=\"#\" data-headword=\"אֶבְלָא\">אבלה</a>, Ar. ed. Koh. incorr., v. Rabb. D. S. a. l.) into whose nostrils a ‘mud-eater’ (worm) entered, and the fish died. <span class=\"citation\">Pes. 112ᵃ</span> <span dir=\"rtl\">ידא אאוסיא וכ׳</span> (Ms. M. a. Ar. <span dir=\"rtl\">א־פגא</span>) putting the hand to the nose is a step to fear (indicating anxiety). <span class=\"citation\">Ḥull. 67ᵇ</span> <span dir=\"rtl\">ועיילי באוסַיֵּיה</span> and they (the worms) creep into its nostrils.</div>","alt":["אַוְסַיָּא"]},"783":{"h":"אוסי","r":"A00783","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוּסִיָּא\">אוּסִיָּא</a></div>","alt":[]},"784":{"h":"אוסיא","r":"A00784","html":"<div class=\"sense\"> <span class=\"citation\">Pes. 111ᵃ</span>, v. <a href=\"#\" data-headword=\"אסיא\">אסיא</a></div>","alt":[]},"785":{"h":"אוסיא ²","r":"A00785","html":"<div class=\"sense\"> Targ. I Chr. Chr. I, 5; a. e. read with ed. Rahmer <a href=\"#\" data-headword=\"מוּסְיָא\">מוּסְיָא</a>; cmp. <span class=\"citation\">Yoma 10ᵃ</span>; <span class=\"citation\">Y. Meg. I, 71ᵇ</span> bot. (h. text <a href=\"#\" data-headword=\"מֶשֶׁךְ\">מֶשֶׁךְ</a>). [<span class=\"citation\">Targ. Y. II, Gen. X, 2</span> <a href=\"#\" data-headword=\"אֲנַסְיָא\">אנסייא</a>; <span class=\"citation\">Gen. R. s. 37</span> <a href=\"#\" data-headword=\"*איסניא\">איסניא</a> (misplaced); corr. acc.]</div>","alt":[]},"786":{"h":"אוּסְיָא","r":"A00786","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> a. <i>certain portion of meat</i>, v. <a href=\"#\" data-headword=\"אוּזְיָא\">אוּזְיָא</a>.</div>","alt":[]},"787":{"h":"אוּסִיָּא","r":"A00787","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (οὐσία) <i>substance</i>, (landed) <i>property, farm, estate</i>. <span class=\"citation\">Gen. R. s. 49</span> <a href=\"#\" data-headword=\"אוסי\">אוסי</a> (corr. acc.).—<span class=\"citation\">Num. R. s. 23</span> <span dir=\"rtl\">שפחות מן א׳ וכ׳</span> maid-servants from another estate. <span class=\"citation\">Y. Taan. IV, 69ᵃ</span>; <span class=\"citation\">Lam. R. to II, 2</span> <a href=\"#\" data-headword=\"אִסְקְרִיטִין\">אי׳</a> (corr. acc.). <span class=\"citation\">Lev. R. s. 34</span>.—Pl. <span dir=\"rtl\">אוּסִיּוֹת</span>. <span class=\"citation\">Ex. R. s. 20</span>. Ch. pl. <a href=\"#\" data-headword=\"אוּסְיָא\">אוּסְיָאן</a>, <span dir=\"rtl\">אוּסְיָיאן</span>. <span class=\"citation\">Lev. R. s. 3</span>, beg. he likes to be called <span dir=\"rtl\">מרי אס׳</span> (corr. acc.) lord of many estates; <span class=\"citation\">Koh. R. to IV, 6</span> <span dir=\"rtl\">אוסייאס</span> (corr. acc.).</div>","alt":["(אוסי)"]},"788":{"h":"אוסיניסי","r":"A00788","html":"<div class=\"sense\"> <span class=\"citation\">Y. Ab. Zar. V, end, 45ᵇ</span> <span dir=\"rtl\">דא׳</span>, read <span dir=\"rtl\">דאניסטיסי</span>, v. <a href=\"#\" data-headword=\"דָּנִיסְטֵיס\">דָּנִיסְטֵיס</a></div>","alt":[]},"789":{"h":"אוסיתא","r":"A00789","html":"<div class=\"sense\"> <span class=\"citation\">Gen. R. s. 14</span>, end, Ar. ed. pr., read <a href=\"#\" data-headword=\"אוֹפִיתָא\">אופיתא</a>.</div>","alt":[]},"790":{"h":"אוסכולי","r":"A00790","html":"<div class=\"sense\">, v. <span dir=\"rtl\">אִיסְכּ׳</span></div>","alt":[]},"791":{"h":"אוּסְמָנָא","r":"A00791","html":"<div class=\"sense\"> (<span dir=\"rtl\">אסם</span> = <a href=\"#\" data-headword=\"חָסַם II\"><span dir=\"rtl\">חֲסַם</span> II</a>) [the glistening.] surname of an Egyptian tribe. <span class=\"citation\">Targ. Ps. LXVIII, 32</span> (Var. <a href=\"#\" data-headword=\"חוּסְמָנָא\">חוּסְמָנַיָּא</a>, a. <a href=\"#\" data-headword=\"אוכמנא\">אוּכְמָנָא</a> <i>the dark</i>.). Cmp. LXX χασμωνίειμ, for <span dir=\"rtl\">כסלחים</span>; <span class=\"citation\">Gen. X, 14</span>; v. Fürst. H. Dict. s. v. <span dir=\"rtl\">כסלח</span>; Ges. H. Dict. s. v. <span dir=\"rtl\">חשם</span>.</div>","alt":["אוּסְמָנַיָּא"]},"792":{"h":"אוּסְנָא","r":"A00792","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִסְנָא\">אָסְנָא</a></div>","alt":[]},"793":{"h":"אוֹסֶף","r":"A00793","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>gathering in</i>. <span class=\"citation\">Snh. 94ᵇ</span>, v. <a href=\"#\" data-headword=\"חָסִיל\">חָסִיל</a>.</div>","alt":[]},"794":{"h":"אוּסְפְּלִידָא","r":"A00794","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִסְפְּלִידָא\">אִסְפְּלִידָא</a></div>","alt":[]},"795":{"h":"אוּסְקָנִיתא","r":"A00795","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">נסק</span>; cmp. <a href=\"#\" data-headword=\"מַסְקָנָא\">מַסְקָנָא</a>) <i>ascending, landing</i>. <span dir=\"rtl\">גמלא דא׳</span> <i>landing board</i>. <span class=\"citation\">Snh. 67ᵇ</span> וקם אג׳ דא׳ Ar. (ed. <span dir=\"rtl\">וקם ג׳ דוסקנ׳</span> read with Rashi <span dir=\"rtl\">דסקונ׳</span>, Ms. M. <span dir=\"rtl\">איסקניתא</span></div>","alt":["סְקוּנִיתָא"]},"796":{"h":"אוֹף I","r":"A00796","html":"<div class=\"sense\"> (= <a href=\"#\" data-headword=\"אַף I\">אַף</a>) <i>too, also</i>. (Yer. Dial.). <span class=\"citation\">Targ. Y. Num. XVI, 13</span>; a. fr.—Y. Dem. I, beg. 21ᶜ <span dir=\"rtl\">א׳ הכא</span> here too.</div>","alt":[]},"797":{"h":"אוֹף II","r":"A00797","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>nature</i>, v. <a href=\"#\" data-headword=\"אוֹפִי\">אוֹפִי</a>.</div>","alt":[]},"798":{"h":"אוּפֵי","r":"A00798","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"עֳפִי\">עֳפִי</a> <span class=\"citation\">Dan. IV, 9</span>; cmp. b. h. <a href=\"#\" data-headword=\"עָנָף\">עָנָף</a>, a. <a href=\"#\" data-headword=\"אִיבָּא I\">אִיבָּא</a>, <a href=\"#\" data-headword=\"אִנְבָּא I\">אִנְבָּא</a>) <i>branches</i>, esp. <i>dry twigs, spray-wood</i>. <span class=\"citation\">Ber. 44ᵇ</span> <span dir=\"rtl\">א׳ פרסייתא</span> twigs of Persian trees. <span class=\"citation\">Ḥull. 105ᵃ</span> פתכא דא׳ Ar. (ed. <span dir=\"rtl\">אופיי</span>) a bundle of twigs. <span class=\"citation\">B. Mets. 30ᵇ</span>. <span class=\"citation\">Git. 61ᵃ</span> <span dir=\"rtl\">שדי אופיי</span> (Ar. <span dir=\"rtl\">אופי</span>) threw twigs down (which he cut off), and dates fell off (v. Tossaf. a. l.).</div>","alt":["אוּפְיֵי"]},"799":{"h":"אוֹפִי","r":"A00799","html":"<div class=\"sense\"> f. (<a href=\"#\" data-headword=\"אוֹף I\">אוֹף</a> m.) (b. h. <i>face, looks</i>, whence, <i>nature, disposition, ways</i> &amp;c. <span class=\"citation\">Y. Shek. I, 45ᵈ</span> אין אתה יכול לעמוד על א׳ של וכ׳ You cannot understand the nature of that people. <span class=\"citation\">Lev. R. s. 30</span> אופוֹ של דוד Ar. ed. Koh. (ed. pr. <span dir=\"rtl\">אופי</span>, ed. <a href=\"#\" data-headword=\"אפו\">אפו</a>) David’s ways. Y’lamd. Vaëthḥ. (quot. in Ar.) ‘who is that nation’ שהיא יודעת אופו של אלוהיה Ar. ed. Koh. (oth. ed. <span dir=\"rtl\">אופי</span>) that knows the ways of her God (what he desires &amp;c.); v. <span class=\"citation\">Yalk. Deut. 825</span>.—<span class=\"citation\">Gen. R. s. 14</span> end <span dir=\"rtl\">נשמה זו הא׳</span> <i>n’shamah</i> (breath, soul) means the disposition, character, as people say <span dir=\"rtl\">האוֹפִיתָא טבא</span> the good nature!</div>","alt":[]}};
